    })),
  statusEmbed: (id) => embedFor(id, 60),
});
registerAlerts({ app, admin, internal, channelInfo });
registerAlertChannels({ app, admin });
registerDigest({ app, admin });
registerServerChart(app);
registerOg(app);
registerSecurity({
  app,
  admin,
  auth,
  userId: (req) => (req as AuthedRequest).user!.id,
  userFromToken,
