// The «pulse» strip above the servers: one sentence about the state, four numbers and a 24-hour chart of players.
import { useId, useState, type JSX, type PointerEvent } from 'react';
import { AnimatedNumber, fmtTime, LAG_PING, num } from '../../ui';
import { IconError, IconOk, IconWarn, IconWrench, IconClock } from '../../icons';
import { t, useI18n } from '../../i18n';
import type { Server } from '../../api';
import { chartPoints, chartStart, hasEnoughHistory, pulseOf, type OverviewData, type PulseState } from './overviewLogic';

const ICON: Record<PulseState, JSX.Element> = {
  ok: <IconOk size={20} />,
  warn: <IconWarn size={20} />,
  bad: <IconError size={20} />,
  maint: <IconWrench size={20} />,
  wait: <IconClock size={20} />,
};

function PlayersChart({ data, now }: { data: OverviewData | null; now: number }) {
  const gid = useId().replace(/:/g, '');
  const { t: tr } = useI18n();
  // hooks go before the early return below: the chart appears once the history has arrived
  const [hover, setHover] = useState<number | null>(null);
  if (!data || !hasEnoughHistory(data.points)) {
    return <div className="pulse-chart pulse-chart-empty">{tr('srv.pulse.noChart')}</div>;
  }
  const end = Math.max(now, data.points[data.points.length - 1].ts + data.bucketMs);
  const start = chartStart(data.points, data.bucketMs, end, data.hours);
  // the caption tells how much the chart really covers: «За 24 ч» on an old panel, «За 3 ч» / «За 40 мин» on a new one
  const covered = Math.min(end - start, data.points[data.points.length - 1].ts + data.bucketMs - data.points[0].ts);
  const spanMin = Math.max(1, Math.round(covered / 60_000));
  const spanText = spanMin >= 180 ? tr('srv.pulse.hours', { n: Math.round(spanMin / 60) }) : tr('srv.pulse.minutes', { n: spanMin });
  const pts = chartPoints(data.points, start, end);
  const W = 240;
  const H = 56;
  const pad = 4;
  const X = (x: number) => x * W;
  const Y = (y: number) => H - pad - y * (H - pad * 2);
  const line = pts.map((p, i) => `${i ? 'L' : 'M'}${X(p.x).toFixed(1)} ${Y(p.y).toFixed(1)}`).join('');
  const area = `${line}L${X(pts[pts.length - 1].x).toFixed(1)} ${H}L${X(pts[0].x).toFixed(1)} ${H}Z`;
  const max = Math.max(1, ...data.points.map((p) => p.players));
  const peak = data.peak;
  const near = (e: PointerEvent<HTMLDivElement>) => {
    const r = e.currentTarget.getBoundingClientRect();
    const x = Math.max(0, Math.min(1, (e.clientX - r.left) / Math.max(1, r.width)));
    let best = 0;
    pts.forEach((p, i) => { if (Math.abs(p.x - x) < Math.abs(pts[best].x - x)) best = i; });
    setHover(best);
  };
  const hp = hover != null ? pts[hover] : null;
  const hts = hp ? start + hp.x * (end - start) : 0;
  const pk = peak ? { x: Math.max(0, Math.min(1, (peak.ts - start) / (end - start))), y: peak.players / max } : null;
  return (
    <figure className="pulse-chart" aria-label={tr('srv.pulse.chart')}>
      <div className="pulse-plot" onPointerMove={near} onPointerDown={near} onPointerLeave={() => setHover(null)}>
        <svg viewBox={`0 0 ${W} ${H}`} preserveAspectRatio="none" role="img" aria-hidden>
          <defs>
            <linearGradient id={`pg${gid}`} x1="0" y1="0" x2="0" y2="1">
              <stop offset="0" stopColor="currentColor" stopOpacity=".32" />
              <stop offset="1" stopColor="currentColor" stopOpacity="0" />
            </linearGradient>
          </defs>
          <path d={area} fill={`url(#pg${gid})`} />
          <path d={line} fill="none" stroke="currentColor" strokeWidth="2" strokeLinejoin="round" strokeLinecap="round" vectorEffect="non-scaling-stroke" />
        </svg>
        {hp && (
          <>
            <span className="pulse-cursor" style={{ left: `${hp.x * 100}%` }} aria-hidden />
            <span className="pulse-tip" style={{ left: `${Math.max(14, Math.min(86, hp.x * 100))}%` }} role="status">
              <b>{Math.round(hp.y * max)}</b> · {fmtTime(hts)}
            </span>
          </>
        )}
        {pk && peak && (
          <span className="pulse-peak" style={{ left: `${pk.x * 100}%`, top: `${((Y(pk.y)) / H) * 100}%` }} aria-hidden />
        )}
      </div>
      <figcaption>
        <span>{spanText}</span>
        <span className="pulse-ticks" aria-hidden><span>{fmtTime(start)}</span><span>{fmtTime((start + end) / 2)}</span><span>{tr('spark.now')}</span></span>
        {peak ? <span className="pulse-peak-text">{tr('srv.pulse.peak', { n: peak.players, time: fmtTime(peak.ts) })}</span> : <span>{tr('srv.pulse.noPeak')}</span>}
      </figcaption>
    </figure>
  );
}

export function PulseStrip({ servers, overview, uptime, now, onOpen }: { servers: Server[]; overview: OverviewData | null; uptime: number | null; now: number; onOpen?: (s: Server) => void }) {
  useI18n();
  const { state, problems } = pulseOf(servers);
  const online = servers.filter((s) => s.online);
  const players = online.reduce((n, s) => n + s.players, 0);
  const pings = online.filter((s) => s.ping != null).map((s) => s.ping as number);
  const avg = pings.length ? Math.round(pings.reduce((a, b) => a + b, 0) / pings.length) : null;

  // problems are one slim alert row (icon, count, names, arrow); the strip below stays neutral
  const alert = state === 'bad' || state === 'warn';
  let title = '';
  let sub = '';
  if (alert) {
    title = t(state === 'bad' ? 'srv.pulse.downN' : 'srv.pulse.slowN', { n: problems.length, total: servers.length });
    const names = problems.slice(0, 2).map((s) => s.name).join(', ');
    sub = problems.length > 2 ? `${names} ${t('srv.pulse.more', { n: problems.length - 2 })}` : names;
  } else if (state === 'maint') {
    const m = servers.filter((s) => s.maintenance);
    title = t('srv.pulse.maint');
    sub = m.length === 1 ? m[0].name : t('srv.pulse.maintN', { n: m.length });
  } else if (state === 'wait') {
    title = t('srv.pulse.wait');
  } else {
    title = t('srv.pulse.ok');
    sub = t('srv.pulse.okSub', { n: online.length });
  }

  // players now against about an hour ago, from the chart buckets
  let trend: number | null = null;
  if (overview && overview.points.length > 1) {
    const pts = overview.points;
    const per = Math.max(1, Math.round(3_600_000 / overview.bucketMs));
    if (pts.length > per) trend = pts[pts.length - 1].players - pts[pts.length - 1 - per].players;
  }
  const first = problems[0];
  return (
    <div className="pulse-wrap">
      {alert && first && (
        <a
          className={`pulse-alert pulse-alert-${state}`}
          href={problems.length === 1 ? `/servers/${first.id}` : '#srv-list'}
          onClick={(e) => {
            if (e.metaKey || e.ctrlKey || e.shiftKey || e.button !== 0) return;
            e.preventDefault();
            if (problems.length === 1) onOpen?.(first);
            else document.getElementById('srv-list')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
          }}
        >
          <span className="pulse-alert-icon" aria-hidden>{ICON[state]}</span>
          <span className="pulse-alert-title">{title}</span>
          <span className="pulse-alert-names">{sub}</span>
          <span className="pulse-alert-go" aria-hidden>→</span>
        </a>
      )}
    <section className={`pulse pulse-${state}`} aria-label={t('srv.pulse.label')}>
      {!alert && (
        <div className="pulse-state" role="status">
          <span className="pulse-icon" aria-hidden>{ICON[state]}</span>
          <span className="pulse-title">{title}</span>
          {sub && <span className="pulse-sub">{sub}</span>}
        </div>
      )}
      <dl className="pulse-nums">
        <div>
          <dt>{t('srv.pulse.players')}</dt>
          <dd><AnimatedNumber value={players} pulse />{trend != null && trend !== 0 && <small className={`pulse-trend ${trend > 0 ? 'up' : 'down'}`} title={t('srv.trend.hour')}>{trend > 0 ? '▲' : '▼'} {Math.abs(trend)}</small>}</dd>
        </div>
        <div>
          <dt>{t('srv.pulse.servers')}</dt>
          <dd>{online.length}<small>/{servers.length}</small></dd>
        </div>
        <div>
          <dt>{t('srv.pulse.ping')}</dt>
          <dd className={avg != null && avg > LAG_PING ? 'text-warn' : ''}>{avg == null ? '–' : <>{avg}<small> {t('srv.unit.ms')}</small></>}</dd>
        </div>
        <div>
          <dt>{t('srv.pulse.uptime')}</dt>
          <dd>{uptime == null ? '–' : <>{num(uptime)}<small>%</small></>}</dd>
        </div>
      </dl>
      <PlayersChart data={overview} now={now} />
    </section>
    </div>
  );
}
