import { useState } from 'react';
import { useAuth } from '../auth';
import { delta, dayKey, healthScore } from './adminLogic';
import { api, type BackupInfo, type BotStatus, type CertInfo, type Server, type UpdateInfo, type UserRow } from '../api';
import type { OverviewData } from '../components/servers/overviewLogic';
import { t, useI18n } from '../i18n';
import { AdminPage, Button, PageHead, Section, SmoothArea, ago, fmtDateTime, toast, usePoll, fail } from '../ui';
import { Icon } from '../icons';
import { downloadFile } from './Backups';

interface AuditRow { id: number; ts: number; actor: string; action: string; detail: string }

interface Raw {
  servers: Server[] | null;
  overview: OverviewData | null;
  users: UserRow[] | null;
  backups: BackupInfo | null;
  update: UpdateInfo | null;
  bot: BotStatus | null;
  cert: CertInfo | null;
  audit: AuditRow[] | null;
}

interface Attention { id: string; tone: 'bad' | 'warn' | 'info'; text: string; href: string }

const ok = <T,>(r: PromiseSettledResult<T>): T | null => (r.status === 'fulfilled' ? r.value : null);
const WEEK = 7 * 86_400_000;

function Tile({ label, value, sub, tone, href, change, spark }: { label: string; value: string; sub?: string; tone?: 'ok' | 'warn' | 'bad'; href?: string; change?: { text: string; tone: 'up' | 'down' } | null; spark?: number[] }) {
  const body = (
    <>
      <span className="adm-tile-k">{label}</span>
      <span className="adm-tile-row">
        <span className={`adm-tile-v ${tone ? `is-${tone}` : ''}`}>{value}</span>
        {change && <span className={`adm-delta is-${change.tone}`} title="за 24 часа">{change.text}</span>}
      </span>
      {spark && spark.length >= 3 && <SmoothArea values={spark} color="rgb(var(--link))" w={160} h={28} fill={0.18} strokeWidth={1.5} className="adm-tile-spark" label={label} />}
      {sub && <span className="adm-tile-s">{sub}</span>}
    </>
  );
  return href ? <a href={href} className="adm-tile">{body}</a> : <div className="adm-tile">{body}</div>;
}

const REASON_TEXT: Record<string, string> = {
  down: 'Есть недоступные серверы',
  bot: 'Бот Discord в ошибке',
  cert: 'Сертификат скоро истечёт',
  backup: 'Давно нет резервной копии',
  pending: 'Ждут заявки игроков',
  update: 'Доступно обновление',
};

/** The ring of the panel's health: the number in the middle, the reasons under it */
function HealthRing({ score, reasons }: { score: number; reasons: { id: string; cost: number; tone: string }[] }) {
  const R = 38;
  const C = 2 * Math.PI * R;
  const tone = score >= 90 ? 'ok' : score >= 65 ? 'warn' : 'bad';
  return (
    <section className="panel adm-health" aria-label="Здоровье панели">
      <svg viewBox="0 0 100 100" className="adm-ring" role="img" aria-label={`Здоровье панели: ${score} из 100`}>
        <circle cx="50" cy="50" r={R} className="adm-ring-bg" />
        <circle cx="50" cy="50" r={R} className={`adm-ring-fg is-${tone}`} strokeDasharray={C} strokeDashoffset={C * (1 - score / 100)} transform="rotate(-90 50 50)" />
        <text x="50" y="56" textAnchor="middle" className="adm-ring-n">{score}</text>
      </svg>
      <div className="min-w-0">
        <p className="font-extrabold">{score >= 90 ? 'Панель в порядке' : score >= 65 ? 'Есть, на что взглянуть' : 'Нужно вмешательство'}</p>
        {reasons.length === 0 ? (
          <p className="text-sm font-semibold text-mute">Серверы, бот, сертификат и копии — всё в норме.</p>
        ) : (
          <ul className="mt-1 flex flex-wrap gap-1.5">
            {reasons.map((r) => <li key={r.id} className={`adm-reason is-${r.tone}`}>{REASON_TEXT[r.id]} <b>−{r.cost}</b></li>)}
          </ul>
        )}
      </div>
    </section>
  );
}

const DUTY = [
  { id: 'servers', text: 'Просмотреть серверы', href: '/admin/servers' },
  { id: 'users', text: 'Разобрать заявки игроков', href: '/admin/users' },
  { id: 'backup', text: 'Проверить резервную копию', href: '/admin/settings/updates' },
  { id: 'journal', text: 'Заглянуть в журнал', href: '/admin/journal' },
];

/** The checks of the day: kept in this browser, start anew each day */
function Duty() {
  const key = `adm-duty-${dayKey()}`;
  const [done, setDone] = useState<string[]>(() => {
    try { return JSON.parse(localStorage.getItem(key) ?? '[]') as string[]; } catch { return []; }
  });
  const toggle = (id: string) => {
    const next = done.includes(id) ? done.filter((x) => x !== id) : [...done, id];
    setDone(next);
    try { localStorage.setItem(key, JSON.stringify(next)); } catch { /* private mode */ }
  };
  const left = DUTY.filter((d) => !done.includes(d.id)).length;
  return (
    <Section title="Обход на сегодня" description={left === 0 ? 'Всё обойдено — можно отдыхать' : `Осталось: ${left} из ${DUTY.length}`}>
      <ul className="space-y-1.5">
        {DUTY.map((d) => (
          <li key={d.id} className="adm-duty">
            <label className="flex min-w-0 flex-1 cursor-pointer items-center gap-2.5">
              <input type="checkbox" checked={done.includes(d.id)} onChange={() => toggle(d.id)} />
              <span className={`font-bold ${done.includes(d.id) ? 'text-mute line-through' : ''}`}>{d.text}</span>
            </label>
            <a href={d.href} className="text-sm font-extrabold text-link hover:underline">Открыть</a>
          </li>
        ))}
      </ul>
    </Section>
  );
}

function auditTone(action: string): string {
  if (/delete|remove|удал/i.test(action)) return 'is-del';
  if (/create|add|создан|добав/i.test(action)) return 'is-add';
  if (/login|password|2fa|security|вход|парол/i.test(action)) return 'is-sec';
  return '';
}

/** «Сводка»: the state of the panel now, what needs attention, the last actions and the common jobs in one click */
export default function AdminOverview() {
  useI18n();
  const [raw, setRaw] = useState<Raw | null>(null);
  const [busy, setBusy] = useState<'poll' | 'backup' | null>(null);
  const { me } = useAuth();
  const [mine, setMine] = useState(false);

  const load = async () => {
    const [servers, overview, users, backups, update, bot, sys, audit] = await Promise.allSettled([
      api<Server[]>('/servers'),
      api<OverviewData>('/overview?hours=24'),
      api<UserRow[]>('/users'),
      api<BackupInfo>('/backups'),
      api<UpdateInfo>('/update/status'),
      api<BotStatus>('/bot/status'),
      api<{ cert?: CertInfo }>('/system'),
      api<AuditRow[]>('/audit?limit=30'),
    ]);
    setRaw({
      servers: ok(servers), overview: ok(overview), users: ok(users), backups: ok(backups), update: ok(update), bot: ok(bot),
      cert: ok(sys)?.cert ?? null, audit: ok(audit),
    });
  };
  usePoll(load, 30_000);

  const servers = raw?.servers ?? [];
  const online = servers.filter((s) => s.online).length;
  const down = servers.filter((s) => !s.online && s.hasStatus && !s.maintenance);
  const players = servers.reduce((n, s) => n + (s.online ? s.players : 0), 0);
  const pending = (raw?.users ?? []).filter((u) => u.status === 'pending').length;
  const lastBackup = raw?.backups?.items.reduce<number>((m, b) => Math.max(m, b.createdAt), 0) ?? 0;

  const attention: Attention[] = [];
  if (down.length > 0) {
    const names = down.slice(0, 3).map((s) => s.name).join(', ');
    attention.push({ id: 'down', tone: 'bad', text: t('adm.ov.down', { names }) + (down.length > 3 ? t('adm.ov.downMore', { k: down.length - 3 }) : ''), href: '/admin/servers' });
  }
  if (raw?.bot?.state === 'error') attention.push({ id: 'bot', tone: 'bad', text: t('adm.ov.botErr'), href: '/admin/settings/bot' });
  if (raw?.cert && raw.cert.daysLeft != null && raw.cert.daysLeft <= 14) {
    attention.push({ id: 'cert', tone: raw.cert.daysLeft <= 0 ? 'bad' : 'warn', text: raw.cert.daysLeft <= 0 ? t('adm.ov.certGone') : t('adm.ov.certSoon', { k: raw.cert.daysLeft }), href: '/admin/system' });
  }
  if (pending > 0) attention.push({ id: 'pending', tone: 'warn', text: t('adm.ov.pend', { k: pending }), href: '/admin/users' });
  if (raw?.update?.available) attention.push({ id: 'update', tone: 'info', text: t('adm.ov.upd'), href: '/admin/settings/updates' });
  if (raw?.backups) {
    if (raw.backups.items.length === 0) attention.push({ id: 'nobackup', tone: 'warn', text: t('adm.ov.noBackups'), href: '/admin/settings/updates' });
    else if (Date.now() - lastBackup > WEEK) attention.push({ id: 'oldbackup', tone: 'warn', text: t('adm.ov.oldBackup'), href: '/admin/settings/updates' });
  }

  const points = raw?.overview?.points ?? [];
  const series = points.map((p) => p.players);
  const health = healthScore({
    servers: servers.length, down: down.length, botError: raw?.bot?.state === 'error', certDays: raw?.cert?.daysLeft ?? null,
    pending, updateAvailable: !!raw?.update?.available, backupAgeMs: lastBackup ? Date.now() - lastBackup : null, backupsKnown: !!raw?.backups,
  });
  const avatarOf = (name: string) => raw?.users?.find((u) => u.username === name)?.avatarUrl ?? null;
  const auditRows = (raw?.audit ?? []).filter((r) => !mine || r.actor === me?.username).slice(0, 10);

  const pollAll = async () => {
    setBusy('poll');
    await Promise.allSettled(servers.map((s) => api(`/servers/${s.id}/refresh`, 'POST')));
    toast(t('adm.ov.polled'));
    await load();
    setBusy(null);
  };
  const backupNow = async () => {
    setBusy('backup');
    try {
      await downloadFile('/backup', 'coregsm-backup.tar.gz');
      toast(t('adm.ov.backupDone'));
    } catch (e) {
      fail(e);
    }
    setBusy(null);
  };

  return (
    <AdminPage head={<PageHead title={t('adm.ov.title')} subtitle={t('adm.ov.subtitle')} icon={<Icon size={22}><rect x="3" y="3" width="7" height="9" rx="1.5" /><rect x="14" y="3" width="7" height="5" rx="1.5" /><rect x="14" y="12" width="7" height="9" rx="1.5" /><rect x="3" y="16" width="7" height="5" rx="1.5" /></Icon>} />}>
      {!raw ? (
        <div className="space-y-5" aria-busy="true" aria-label={t('adm.loading')}>
          <div className="adm-tiles">{[0, 1, 2, 3, 4].map((i) => <div key={i} className="skeleton h-24 rounded-2xl" />)}</div>
          <div className="skeleton tile h-32" />
        </div>
      ) : (
        <>
          <HealthRing score={health.score} reasons={health.reasons} />

          <div className="adm-tiles">
            <Tile label={t('adm.ov.servers')} value={servers.length ? `${online} / ${servers.length}` : '–'} tone={servers.length === 0 ? undefined : down.length ? 'bad' : 'ok'} href="/admin/servers" />
            <Tile label={t('adm.ov.players')} value={String(players)} change={delta(players, series[0])} spark={series} href="/admin/servers" />
            <Tile label={t('adm.ov.pending')} value={raw.users ? String(pending) : '–'} tone={pending > 0 ? 'warn' : undefined} href="/admin/users" />
            <Tile label={t('adm.ov.backup')} value={raw.backups ? (lastBackup ? ago(lastBackup) : t('adm.ov.noBackup')) : '–'} tone={raw.backups && (!lastBackup || Date.now() - lastBackup > WEEK) ? 'warn' : undefined} href="/admin/settings/updates" />
            <Tile label={t('adm.ov.version')} value={raw.update?.currentLabel || (raw.update?.current ? raw.update.current.slice(0, 7) : '–')} sub={raw.update?.available ? t('adm.ov.upd') : undefined} tone={raw.update?.available ? 'warn' : undefined} href="/admin/settings/updates" />
          </div>

          {servers.length > 0 && (
            <div className="adm-now" role="list" aria-label="Серверы сейчас">
              {servers.map((s) => (
                <a key={s.id} role="listitem" href={`/servers/${s.id}`} className={`adm-now-card ${s.maintenance ? 'is-maint' : s.online ? 'is-on' : 'is-off'}`}>
                  <span className="adm-now-dot" aria-hidden />
                  <span className="min-w-0">
                    <span className="block truncate text-sm font-extrabold">{s.name}</span>
                    <span className="block text-xs font-semibold tabular-nums text-mute">{s.maintenance ? 'обслуживание' : s.online ? `${s.players} / ${s.maxPlayers}` : 'недоступен'}</span>
                  </span>
                </a>
              ))}
            </div>
          )}

          <Section title={t('adm.ov.attn')}>
            {attention.length === 0 ? (
              <div className="st-calm">
                <span aria-hidden>✓</span>
                <div>
                  <p className="font-extrabold">{t('adm.ov.allGood')}</p>
                  <p className="text-sm font-semibold text-mute">{t('adm.ov.allGoodText')}</p>
                </div>
              </div>
            ) : (
              <ul className="space-y-2">
                {attention.map((a) => (
                  <li key={a.id} className={`adm-attn is-${a.tone}`}>
                    <span className="adm-attn-dot" aria-hidden />
                    <span className="min-w-0 flex-1 font-bold">{a.text}</span>
                    <a href={a.href} className="btn btn-soft btn-sm">{t('adm.ov.fix')}</a>
                  </li>
                ))}
              </ul>
            )}
          </Section>

          <div className="grid items-start gap-5 lg:grid-cols-2">
            <Section title={t('adm.ov.chart')} description={raw.overview?.peak ? t('adm.ov.chartPeak', { k: raw.overview.peak.players }) : undefined}>
              {series.length >= 3 ? (
                <SmoothArea values={series} color="rgb(var(--link))" w={400} h={90} fill={0.22} strokeWidth={2} className="h-24" label={t('adm.ov.chart')} />
              ) : (
                <p className="font-semibold text-mute">{t('adm.ov.chartNone')}</p>
              )}
            </Section>

            <Section title={t('adm.ov.quick')}>
              <div className="flex flex-wrap gap-2">
                <a href="/admin/servers/new" className="btn">{t('adm.ov.addServer')}</a>
                <a href="/admin/news/new" className="btn btn-soft">{t('adm.ov.writeNews')}</a>
                <Button type="button" variant="soft" loading={busy === 'poll'} disabled={servers.length === 0} onClick={() => void pollAll()}>{t('adm.ov.pollAll')}</Button>
                <Button type="button" variant="soft" loading={busy === 'backup'} onClick={() => void backupNow()}>{t('adm.ov.backupNow')}</Button>
              </div>
            </Section>
          </div>

          <div className="grid items-start gap-5 lg:grid-cols-[2fr_1fr]">
            <Section
              title={t('adm.ov.recent')}
              actions={
                <span className="flex items-center gap-3">
                  <button type="button" className="adm-chip" aria-pressed={mine} onClick={() => setMine((v) => !v)}>Только мои</button>
                  <a href="/admin/journal" className="text-sm font-extrabold text-link hover:underline">{t('adm.ov.journal')}</a>
                </span>
              }
            >
              {auditRows.length > 0 ? (
                <ul className="divide-y divide-line">
                  {auditRows.map((r) => {
                    const pic = avatarOf(r.actor);
                    return (
                      <li key={r.id} className="flex items-center gap-3 py-2">
                        {pic ? (
                          <img src={pic} alt="" width={28} height={28} loading="lazy" referrerPolicy="no-referrer" className="adm-av" />
                        ) : (
                          <span className="adm-av" aria-hidden>{r.actor.slice(0, 1).toUpperCase()}</span>
                        )}
                        <div className="min-w-0 flex-1">
                          <p className="truncate"><span className={`adm-act ${auditTone(r.action)}`}>{r.action}</span>{r.detail && <span className="ml-2 font-semibold text-mute">{r.detail}</span>}</p>
                          <p className="text-xs font-semibold text-mute" title={fmtDateTime(r.ts)}>{r.actor} · {ago(r.ts)}</p>
                        </div>
                      </li>
                    );
                  })}
                </ul>
              ) : (
                <p className="font-semibold text-mute">{mine ? 'Ваших действий пока нет' : t('adm.ov.noEvents')}</p>
              )}
            </Section>
            <Duty />
          </div>
        </>
      )}
    </AdminPage>
  );
}
__COREGSM_EOF__
  mkdir -p "$APP_DIR/core-frontend/src/pages"
  cat > "$APP_DIR/core-frontend/src/pages/AdminServersTable.tsx" << '__COREGSM_EOF__'
// The «Серверы» table of the admin area: search, filters, a checkbox per row for bulk actions, the figures of every
// server (status, players, ping, uptime, a 24 h curve) and the row actions as icons. On a phone it is a list of cards.
import { Fragment, useEffect, useMemo, useState } from 'react';
import type { Server } from '../api';
import { confirmDialog } from '../confirm';
import { t, useI18n, type TKey } from '../i18n';
import { gameColor, gameLabel } from '../games';
import RowMenu, { type RowMenuItem } from '../components/RowMenu';
import { AnimatedNumber, GameAvatar, IconEdit, IconRefresh, MiniSpark, StatusPill, ago, isLag, toast } from '../ui';
import { countServers, filterServers, loadColumns, loadTableState, saveColumns, saveTableState, TABLE_COLUMNS, type ServerFilter, type TableColumn } from './adminServersLogic';

export interface TableActions {
  isAdmin: boolean;
  busyId: number | null;
  uptime: Map<number, number>;
  /** Discord channels bound to each server */
  bindings: Map<number, number>;
  onMaintenance: (s: Server) => void;
  onRefresh: (s: Server) => void;
  onEdit: (s: Server) => void;
  onRemove: (s: Server) => void;
  /** refresh / delete several at once; resolve when done */
  onRefreshMany: (list: Server[]) => Promise<void>;
  onRemoveMany: (list: Server[]) => Promise<void>;
  /** move a server one step up/down in the manual order (the ids on screen, in order) */
  onMove: (s: Server, dir: -1 | 1, shown: number[]) => void;
}

const FILTERS: [ServerFilter, TKey][] = [['all', 'adm.tbl.all'], ['online', 'adm.tbl.online'], ['problems', 'adm.tbl.problems']];
/** «2 ч», «15 мин»: how long a state has lasted */
export function spanText(ms: number): string {
  const m = Math.floor(ms / 60_000);
  if (m < 1) return 'меньше минуты';
  if (m < 60) return `${m} мин`;
  const h = Math.floor(m / 60);
  if (h < 48) return `${h} ч`;
  return `${Math.floor(h / 24)} дн`;
}
const stateLine = (s: Server): string | null => {
  if (s.maintenance || !s.hasStatus || !s.stateSince) return null;
  return `${s.online ? 'работает' : 'не отвечает'} · ${spanText(Date.now() - s.stateSince)}`;
};
const pct = (v: number | undefined) => (v == null ? '–' : `${(Math.round(v * 10) / 10).toLocaleString('ru-RU')}%`);

export function AdminServersTable({ servers, a }: { servers: Server[]; a: TableActions }) {
  useI18n();
  const [saved] = useState(loadTableState);
  const [filter, setFilter] = useState<ServerFilter>(saved.filter);
  const [query, setQuery] = useState(saved.query);
  useEffect(() => { saveTableState(filter, query); }, [filter, query]);
  const [cols, setCols] = useState<TableColumn[]>(loadColumns);
  const toggleCol = (c: TableColumn) => setCols((l) => { const n = l.includes(c) ? l.filter((x) => x !== c) : TABLE_COLUMNS.filter((x) => x === c || l.includes(x)); saveColumns(n); return n; });
  const has = (c: TableColumn) => cols.includes(c);
  const [sel, setSel] = useState<number[]>([]);
  const [busy, setBusy] = useState(false);
  const [open, setOpen] = useState<number[]>([]);
  const [view, setView] = useState<'table' | 'cards'>(() => { try { return localStorage.getItem('coregsm_admin_srv_view') === 'cards' ? 'cards' : 'table'; } catch { return 'table'; } });
  const pickView = (v: 'table' | 'cards') => { setView(v); try { localStorage.setItem('coregsm_admin_srv_view', v); } catch { /* not remembered */ } };
  const counts = useMemo(() => countServers(servers), [servers]);
  const rows = useMemo(() => filterServers(servers, filter, query), [servers, filter, query]);
  const shownIds = rows.map((s) => s.id);
  const canMove = filter === 'all' && !query.trim() && rows.length > 1;
  const picked = servers.filter((s) => sel.includes(s.id));
  const allOn = rows.length > 0 && shownIds.every((id) => sel.includes(id));
  const toggle = (id: number) => setSel((l) => (l.includes(id) ? l.filter((x) => x !== id) : [...l, id]));
  const toggleAll = () => setSel((l) => (allOn ? l.filter((id) => !shownIds.includes(id)) : [...new Set([...l, ...shownIds])]));

  const flip = (id: number) => setOpen((l) => (l.includes(id) ? l.filter((x) => x !== id) : [...l, id]));
  const copy = async (s: Server) => {
    try { await navigator.clipboard.writeText(`${s.host}:${s.port}`); toast(t('adm.tbl.copied')); } catch { toast(t('nw.copyFail'), 'err'); }
  };

  /** the rest of a row's actions: a text menu behind «⋯» */
  const menuItems = (s: Server): RowMenuItem[] => [
    ...(canMove ? [
      { key: 'up', label: t('adm.tbl.up'), disabled: s.id === shownIds[0], onSelect: () => a.onMove(s, -1, shownIds) },
      { key: 'down', label: t('adm.tbl.down'), disabled: s.id === shownIds[shownIds.length - 1], onSelect: () => a.onMove(s, 1, shownIds) },
    ] : []),
    { key: 'bind', label: t('adm.tbl.bind'), href: `/admin/discord/new/${s.id}`, sep: canMove },
    { key: 'maint', label: s.maintenance ? t('adm.tbl.maintOff') : t('adm.tbl.maintOn'), onSelect: () => a.onMaintenance(s) },
    ...(a.isAdmin ? [{ key: 'del', label: t('adm.srv.delete'), danger: true, sep: true, onSelect: () => a.onRemove(s) }] : []),
  ];

  const many = async (fn: (list: Server[]) => Promise<void>) => {
    setBusy(true);
    try { await fn(picked); setSel([]); } finally { setBusy(false); }
  };
  const removeMany = async () => {
    if (!(await confirmDialog({ title: t('adm.tbl.deleteQ', { n: picked.length }), text: t('adm.tbl.deleteText'), confirmLabel: t('adm.srv.delete'), danger: true }))) return;
    await many(a.onRemoveMany);
  };

  return (
    <div className="adm-st space-y-3">
      <div className="flex flex-wrap items-center gap-2.5">
        <nav className="seg flex w-fit max-w-full overflow-x-auto" aria-label={t('adm.tbl.filter')}>
          {FILTERS.map(([id, label]) => (
            <button key={id} type="button" className="seg-item whitespace-nowrap" aria-pressed={filter === id} onClick={() => setFilter(id)}>
              {t(label)} · {counts[id]}
            </button>
          ))}
        </nav>
        <div className="seg hidden w-fit md:flex" role="group" aria-label="Вид списка">
          <button type="button" className="seg-item" aria-pressed={view === 'table'} onClick={() => pickView('table')}>Таблица</button>
          <button type="button" className="seg-item" aria-pressed={view === 'cards'} onClick={() => pickView('cards')}>Карточки</button>
        </div>
        <details className="adm-cols hidden md:block">
          <summary className="seg-item cursor-pointer select-none">{t('adm.cols')}</summary>
          <div className="adm-cols-pop" role="group" aria-label={t('adm.cols')}>
            {TABLE_COLUMNS.map((c) => (
              <label key={c} className="flex cursor-pointer items-center gap-2 px-2 py-1 font-semibold">
                <input type="checkbox" className="srv-check" checked={has(c)} onChange={() => toggleCol(c)} />{t(`adm.col.${c}` as TKey)}
              </label>
            ))}
          </div>
        </details>
        <label className="adm-search ml-auto">
          <span aria-hidden>⌕</span>
          <input type="search" value={query} onChange={(e) => setQuery(e.target.value)} placeholder={t('adm.tbl.search')} aria-label={t('adm.tbl.search')} />
        </label>
      </div>

      {picked.length > 0 && (
        <div className="adm-bulk adm-bulk-float" role="region" aria-label={t('adm.tbl.selected')}>
          <b>{t('adm.tbl.picked', { n: picked.length })}</b>
          <button type="button" className="btn btn-soft btn-sm" disabled={busy} onClick={() => void many(a.onRefreshMany)}>{t('adm.tbl.poll')}</button>
          {a.isAdmin && <button type="button" className="btn btn-danger btn-sm" disabled={busy} onClick={() => void removeMany()}>{t('adm.srv.delete')}</button>}
          <button type="button" className="btn btn-ghost btn-sm ml-auto" onClick={() => setSel([])}>{t('adm.tbl.clear')}</button>
        </div>
      )}

      {rows.length === 0 ? (
        <div className="tile px-5 py-8 text-center font-semibold text-mute">
          {t('adm.tbl.none')} <button type="button" className="font-extrabold text-link underline" onClick={() => { setFilter('all'); setQuery(''); }}>{t('adm.tbl.reset')}</button>
        </div>
      ) : (
        <>
          {/* wide screens: a table */}
          <div className={`tile adm-tablewrap hidden p-1.5 ${view === 'table' ? 'md:block' : ''}`}>
            <table className="adm-table">
              <thead>
                <tr>
                  <th className="w-9"><input type="checkbox" className="srv-check" checked={allOn} onChange={toggleAll} aria-label={t('adm.tbl.selectAll')} /></th>
                  <th>{t('adm.tbl.server')}</th>
                  <th>{t('adm.tbl.status')}</th>
                  <th>{t('adm.tbl.players')}</th>
                  <th>{t('adm.tbl.ping')}</th>
                  {has('map') && <th>{t('adm.col.map')}</th>}
                  {has('version') && <th>{t('adm.col.version')}</th>}
                  {has('channels') && <th>{t('adm.col.channels')}</th>}
                  {has('uptime') && <th>{t('adm.tbl.uptime')}</th>}
                  {has('h24') && <th>{t('adm.tbl.h24')}</th>}
                  {has('updated') && <th>{t('adm.col.updated')}</th>}
                  <th aria-label={t('adm.tbl.actions')} />
                </tr>
              </thead>
              <tbody>
                {rows.map((s) => (
                  <Fragment key={s.id}>
                  <tr data-state={s.maintenance ? 'maint' : !s.online && s.hasStatus ? 'off' : isLag(s) ? 'lag' : 'on'} data-selected={sel.includes(s.id) ? 'true' : undefined} className="cursor-pointer" onClick={(e) => { if (!(e.target as HTMLElement).closest('a, button, input, label')) a.onEdit(s); }}>
                    <td><input type="checkbox" className="srv-check" checked={sel.includes(s.id)} onChange={() => toggle(s.id)} aria-label={`${t('adm.tbl.select')}: ${s.name}`} /></td>
                    <td>
                      <div className="flex min-w-0 items-center gap-3">
                        <button type="button" className="adm-expand" aria-expanded={open.includes(s.id)} aria-label={`${t('adm.tbl.details')}: ${s.name}`} title={t('adm.tbl.details')} onClick={() => flip(s.id)}><span aria-hidden>{open.includes(s.id) ? '▾' : '▸'}</span></button>
                        <GameAvatar game={s.game} size={38} />
                        <div className="min-w-0">
                          <a href={`/servers/${s.id}`} className="block max-w-50 xl:max-w-60 truncate font-extrabold leading-tight hover:text-link" title={s.name}>{s.name}</a>
                          <div className="max-w-50 xl:max-w-60 truncate text-xs font-semibold text-mute" title={s.displayAddress ? t('adm.tbl.shownAs', { a: s.displayAddress }) : undefined}>
                            {gameLabel(s.game)} · <button type="button" className="adm-copy font-mono" title={t('adm.tbl.copy')} onClick={() => void copy(s)}>{s.host}:{s.port}</button>
                          </div>
                        </div>
                      </div>
                    </td>
                    <td>
                      <StatusPill online={s.online} known={s.hasStatus} lag={isLag(s)} maintenance={!!s.maintenance} />
                      {stateLine(s) && <div className="mt-0.5 text-xs font-semibold text-mute">{stateLine(s)}</div>}
                    </td>
                    <td className="tabular-nums text-mute">{s.online ? <><b className="text-ink"><AnimatedNumber value={s.players} /></b>/{s.maxPlayers}</> : '—'}</td>
                    <td className="tabular-nums text-mute">{s.online && s.ping != null ? t('adm.tbl.ms', { n: s.ping }) : '—'}</td>
                    {has('map') && <td className="max-w-40 truncate text-mute" title={s.map ?? undefined}>{s.online && s.map ? s.map : '—'}</td>}
                    {has('version') && <td className="max-w-32 truncate font-mono text-xs text-mute" title={s.version ?? undefined}>{s.version || '—'}</td>}
                    {has('channels') && <td className="tabular-nums"><a href="/admin/discord" className="text-link hover:underline">{a.bindings.get(s.id) ?? 0}</a></td>}
                    {has('uptime') && <td className="tabular-nums">{pct(a.uptime.get(s.id))}</td>}
                    {has('h24') && <td><MiniSpark serverId={s.id} color={gameColor(s.game)} /></td>}
                    {has('updated') && <td className="text-mute">{ago(s.updatedAt)}</td>}
                    <td>
                      <div className="flex items-center justify-end gap-1" role="group" aria-label={`${t('adm.tbl.actions')}: ${s.name}`}>
                        <button type="button" className="btn btn-soft btn-sm" aria-label={`${t('adm.tbl.edit')}: ${s.name}`} onClick={() => a.onEdit(s)}><IconEdit /><span>{t('adm.tbl.edit')}</span></button>
                        <button type="button" className="row-act" title={t('adm.tbl.poll')} aria-label={`${t('adm.tbl.poll')}: ${s.name}`} onClick={() => a.onRefresh(s)} disabled={a.busyId === s.id} aria-busy={a.busyId === s.id || undefined}>
                          <IconRefresh spinning={a.busyId === s.id} />
                        </button>
                        <RowMenu label={`${t('adm.tbl.more')}: ${s.name}`} items={menuItems(s)} />
                      </div>
                    </td>
                  </tr>
                  {open.includes(s.id) && (
                    <tr className="adm-detail">
                      <td colSpan={14}>
                        <dl className="adm-detail-grid">
                          <div><dt>{t('adm.tbl.d.addr')}</dt><dd className="font-mono">{s.host}:{s.port}</dd></div>
                          <div><dt>{t('adm.tbl.d.query')}</dt><dd className="font-mono">{s.queryPort ?? '—'}</dd></div>
                          <div><dt>{t('adm.tbl.d.shown')}</dt><dd>{s.displayAddress || '—'}</dd></div>
                          <div><dt>{t('adm.tbl.d.game')}</dt><dd>{gameLabel(s.game)}</dd></div>
                          <div><dt>{t('adm.tbl.d.channels')}</dt><dd><a href="/admin/discord" className="text-link hover:underline">{a.bindings.get(s.id) ?? 0}</a></dd></div>
                          <div><dt>{t('adm.tbl.d.updated')}</dt><dd>{ago(s.updatedAt)}</dd></div>
                          {s.maintenance && <div><dt>{t('adm.tbl.d.maint')}</dt><dd>{s.maintenance.name}</dd></div>}
                        </dl>
                      </td>
                    </tr>
                  )}
                  </Fragment>
                ))}
              </tbody>
            </table>
          </div>

          {/* a phone: a card per server */}
          <div className="adm-cards" data-hide-md={view === 'table' ? 'true' : undefined}>
            {rows.map((s) => (
              <div key={s.id} className="tile adm-card flex flex-wrap items-center gap-x-3 gap-y-2 p-3.5" data-state={s.maintenance ? 'maint' : !s.online && s.hasStatus ? 'off' : isLag(s) ? 'lag' : 'on'} data-selected={sel.includes(s.id) ? 'true' : undefined}>
                <input type="checkbox" className="srv-check" checked={sel.includes(s.id)} onChange={() => toggle(s.id)} aria-label={`${t('adm.tbl.select')}: ${s.name}`} />
                <GameAvatar game={s.game} size={40} />
                <div className="min-w-0 flex-1 basis-40">
                  <a href={`/servers/${s.id}`} className="block wrap-break-word font-extrabold leading-tight">{s.name}</a>
                  <div className="truncate text-xs font-semibold text-mute">{gameLabel(s.game)} · <span className="font-mono">{s.host}:{s.port}</span></div>
                </div>
                <StatusPill online={s.online} known={s.hasStatus} lag={isLag(s)} maintenance={!!s.maintenance} />
                {stateLine(s) && <div className="w-full text-xs font-semibold text-mute">{stateLine(s)}</div>}
                <div className="flex w-full items-center gap-2 text-sm font-semibold text-mute">
                  <span className="tabular-nums">{s.online ? <><b className="text-ink">{s.players}</b>/{s.maxPlayers}</> : '—'}</span>
                  <span>· {ago(s.updatedAt)}</span>
                  <div className="ml-auto flex items-center gap-1">
                    <button type="button" className="row-act" aria-label={`${t('adm.tbl.poll')}: ${s.name}`} onClick={() => a.onRefresh(s)} disabled={a.busyId === s.id}><IconRefresh spinning={a.busyId === s.id} /></button>
                    <button type="button" className="btn btn-soft btn-sm" aria-label={`${t('adm.tbl.edit')}: ${s.name}`} onClick={() => a.onEdit(s)}><IconEdit /><span>{t('adm.tbl.edit')}</span></button>
                    <RowMenu label={`${t('adm.tbl.more')}: ${s.name}`} items={menuItems(s)} />
                  </div>
                </div>
              </div>
            ))}
          </div>
        </>
      )}
    </div>
  );
}
