import { useAuth } from '../auth';
import { getPrefs, t, useI18n } from '../i18n';
import { Icon } from '../icons';
import { useEffect, useMemo, useRef, useState, type KeyboardEvent, type PointerEvent } from 'react';
import { api, type StatusDay, type StatusIncident, type StatusInfo, type StatusNote, type StatusServer } from '../api';
import { Empty, ErrorLine, GameAvatar, LoadError, PageHead, SmoothArea, StatusPill, ago, fmtDateTime, fmtTime, usePoll } from '../ui';
import '../styles/status.css';

const loc = () => (getPrefs().lang === 'en' ? 'en-US' : 'ru-RU');
const fmtDay = (day: string) => {
  const d = new Date(`${day}T12:00:00`);
  return Number.isNaN(d.getTime()) ? day : d.toLocaleDateString(loc(), { day: 'numeric', month: 'long' });
};
const fmtPct = (p: number) => `${(Math.round(p * 10) / 10).toLocaleString(loc())}%`;
const dur = (min: number) => (min < 60 ? t('st.dur.m', { m: min }) : min % 60 ? t('st.dur.hm', { h: Math.floor(min / 60), m: min % 60 }) : t('st.dur.h', { h: Math.floor(min / 60) }));
/** «, 3 сбоя» after a duration when a day had several outages */
const incSuffix = (n?: number) => (n && n > 1 ? `, ${t('st.outages', { n })}` : '');

const POLL_MS = 60_000;

const fmtShort = (day: string) => {
  const d = new Date(`${day}T12:00:00`);
  return Number.isNaN(d.getTime()) ? day : d.toLocaleDateString(loc(), { day: 'numeric', month: 'short' }).replace('.', '');
};

const reducedMotion = () => window.matchMedia('(prefers-reduced-motion: reduce)').matches || document.documentElement.dataset.motion === 'reduce';

/** a re-render every `ms` (for «обновлено N с назад») */
function useNow(ms: number) {
  const [now, setNow] = useState(() => Date.now());
  useEffect(() => {
    const id = window.setInterval(() => setNow(Date.now()), ms);
    return () => window.clearInterval(id);
  }, [ms]);
  return now;
}

/** the number counts up to its value and, on a later poll, from the old value to the new one */
function useCountUp(target: number, ms = 600) {
  const [v, setV] = useState(target);
  const from = useRef(target);
  const first = useRef(true);
  useEffect(() => {
    if (reducedMotion()) { from.current = target; setV(target); return; }
    const a = first.current ? 0 : from.current;
    first.current = false;
    const t0 = performance.now();
    let raf = 0;
    const step = (now: number) => {
      const p = Math.min(1, (now - t0) / ms);
      const cur = a + (target - a) * (1 - (1 - p) ** 3);
      from.current = cur;
      setV(cur);
      if (p < 1) raf = requestAnimationFrame(step);
    };
    raf = requestAnimationFrame(step);
    return () => cancelAnimationFrame(raf);
  }, [target, ms]);
  return v;
}

const IconCheck = () => <Icon size={30}><path d="M20 6 9 17l-5-5" /></Icon>;
const IconWarn = () => <Icon size={30}><path d="M10.3 3.9 1.8 18a2 2 0 0 0 1.7 3h17a2 2 0 0 0 1.7-3L13.7 3.9a2 2 0 0 0-3.4 0Z" /><path d="M12 9v4M12 17h.01" /></Icon>;
const IconCross = () => <Icon size={30}><circle cx="12" cy="12" r="10" /><path d="m15 9-6 6M9 9l6 6" /></Icon>;
const IconServer = () => <Icon size={16}><rect x="3" y="4" width="18" height="7" rx="2" /><rect x="3" y="13" width="18" height="7" rx="2" /><path d="M7 7.5h.01M7 16.5h.01" /></Icon>;
const IconUsers = () => <Icon size={16}><path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2" /><circle cx="9" cy="7" r="4" /><path d="M23 21v-2a4 4 0 0 0-3-3.9M16 3.1a4 4 0 0 1 0 7.8" /></Icon>;
const IconAct = () => <Icon size={16}><path d="M22 12h-4l-3 9L9 3l-3 9H2" /></Icon>;
const IconAlert = () => <Icon size={16}><circle cx="12" cy="12" r="10" /><path d="M12 8v4M12 16h.01" /></Icon>;

/** the colour of a day: by how long the server was down, not by a percentage that hides a 40-minute outage */
function dayTone(d: StatusDay): 'none' | 'ok' | 'blip' | 'warn' | 'bad' | 'planned' {
  if (d.pct == null) return 'none';
  const down = d.down ?? 0;
  if (down >= 60) return 'bad';
  if (down >= 15) return 'warn';
  if (down > 0) return 'blip';
  if ((d.planned ?? 0) > 0) return 'planned';
  return 'ok';
}

function dayText(d: StatusDay): string {
  if (d.pct == null) return t('st.day.none', { d: fmtDay(d.day) });
  const parts = [t('st.day.up', { d: fmtDay(d.day), p: fmtPct(d.pct) })];
  if (d.down) parts.push(t('st.day.down', { dur: dur(d.down), inc: incSuffix(d.incidents) }));
  else parts.push(t('st.noOutages'));
  if (d.planned) parts.push(t('st.day.planned', { dur: dur(d.planned) }));
  return parts.join(' · ');
}

function UptimeBar({ s }: { s: StatusServer }) {
  const [active, setActive] = useState<number | null>(null);
  const ref = useRef<HTMLDivElement>(null);
  const n = s.days.length;
  const summary = s.uptime30 == null ? t('st.up.none', { d: n }) : t('st.up.sum', { p: fmtPct(s.uptime30), d: n });
  const at = (e: PointerEvent) => {
    const r = ref.current?.getBoundingClientRect();
    if (!r || r.width === 0) return null;
    return Math.min(n - 1, Math.max(0, Math.floor(((e.clientX - r.left) / r.width) * n)));
  };
  const onKey = (e: KeyboardEvent) => {
    const cur = active ?? n - 1;
    if (e.key === 'ArrowLeft') setActive(Math.max(0, cur - 1));
    else if (e.key === 'ArrowRight') setActive(Math.min(n - 1, cur + 1));
    else if (e.key === 'Home') setActive(0);
    else if (e.key === 'End') setActive(n - 1);
    else if (e.key === 'Escape') setActive(null);
    else return;
    e.preventDefault();
  };
  const d = active != null ? s.days[active] : null;
  return (
    <div className="st-uptime">
      <div
        ref={ref}
        className="st-bars"
        role="img"
        tabIndex={0}
        aria-label={t('st.up.aria', { s: summary })}
        onPointerMove={(e) => { if (e.pointerType === 'mouse') setActive(at(e)); }}
        onPointerDown={(e) => { const i = at(e); setActive((cur) => (e.pointerType !== 'mouse' && cur === i ? null : i)); }}
        onPointerLeave={(e) => { if (e.pointerType === 'mouse') setActive(null); }}
        onKeyDown={onKey}
        onBlur={() => setActive(null)}
      >
        {s.days.map((x, i) => (
          <span key={x.day} className={`st-day is-${dayTone(x)} ${i === n - 1 ? 'is-today' : ''} ${active === i ? 'is-hover' : ''}`} />
        ))}
      </div>
      {d && active != null && (
        <div className={`st-tip ${active < 4 ? 'is-l' : active > n - 5 ? 'is-r' : ''}`} style={{ left: `${((active + 0.5) / n) * 100}%` }} aria-hidden>
          <div className="st-tip-day"><span className={`st-day st-legend is-${dayTone(d)}`} />{fmtDay(d.day)}</div>
          <div className="st-tip-main">{d.pct == null ? t('st.nodata') : t('st.tip.up', { p: fmtPct(d.pct) })}</div>
          {d.pct != null && <div className="st-tip-sub">{d.down ? t('st.tip.down', { dur: dur(d.down), inc: incSuffix(d.incidents) }) : t('st.tip.none')}</div>}
          {!!d.planned && <div className="st-tip-sub">{t('st.tip.planned', { dur: dur(d.planned) })}</div>}
        </div>
      )}
      <div className="st-ticks" aria-hidden>
        {s.days.map((x, i) => (
          <span key={x.day} className="st-tick">
            {(n - 1 - i) % 7 === 0 && <em className={i === n - 1 ? 'is-last' : ''}>{i === n - 1 ? t('st.today') : fmtShort(x.day)}</em>}
          </span>
        ))}
      </div>
      <div className="sr-only" aria-live="polite">{d ? dayText(d) : ''}</div>
    </div>
  );
}

/** the hourly average ping of the day: the 100 ms line, the worst hour marked, best / average / worst under it */
function Latency({ s }: { s: StatusServer }) {
  const vals = (s.latency ?? []).filter((v): v is number => v != null);
  if (vals.length < 2) return null;
  let prev = vals[0];
  const filled = (s.latency ?? []).map((v) => (v == null ? prev : (prev = v)));
  const lo = Math.min(...vals);
  const hi = Math.max(...vals);
  // the 100 ms line only matters when the ping is near it; with a quiet ping the chart zooms in on the data instead
  const showLimit = hi >= 60;
  const top = showLimit ? Math.max(110, hi) : Math.max(10, hi * 1.5);
  const W = 200, H = 36, PAD = 3, scale = top * 1.12;
  const yOf = (v: number) => ((H - PAD - (v / scale) * (H - PAD * 2)) / H) * 100;
  const peak = filled.indexOf(Math.max(...filled));
  const showPeak = hi >= 1.3 * (s.avgPing ?? hi) && hi > lo;
  const tone = (s.avgPing ?? 0) > 100 ? 'rgb(var(--warn))' : 'rgb(var(--link))';
  return (
    <div className="st-lat">
      <div className="st-lat-k">{t('st.lat.k')}</div>
      <div className="st-lat-chart">
        <SmoothArea values={filled} color={tone} w={W} h={H} fill={0.2} strokeWidth={1.8} className="h-9" max={top} label={t('st.lat.label', { lo, hi })} />
        {showLimit && <span className="st-lat-limit" style={{ top: `${yOf(100)}%` }} aria-hidden><i>100</i></span>}
        {showPeak && (
          <span className={`st-lat-peak ${hi > 100 ? 'is-high' : ''}`} style={{ left: `${((PAD + (peak / Math.max(1, filled.length - 1)) * (W - PAD * 2)) / W) * 100}%`, top: `${yOf(filled[peak])}%` }} title={t('st.lat.max', { hi })} aria-hidden />
        )}
      </div>
      <div className="st-lat-v">{s.avgPing != null ? t('st.lat.v', { lo, avg: s.avgPing, hi }) : '–'}</div>
    </div>
  );
}

function ServerRow({ s, index }: { s: StatusServer; index: number }) {
  const incidents30 = s.days.reduce((n, d) => n + (d.incidents ?? 0), 0);
  const lag = s.online && s.avgPing != null && s.avgPing > 100;
  const upTone = s.uptime30 == null ? 'none' : s.uptime30 >= 99.9 ? 'great' : s.uptime30 >= 99 ? 'good' : s.uptime30 >= 95 ? 'meh' : 'poor';
  const fill = s.maxPlayers > 0 ? Math.min(100, Math.round((s.players / s.maxPlayers) * 100)) : 0;
  return (
    <li className={`st-server tile tile-in is-${!s.online ? 'off' : lag ? 'lag' : 'on'}`} style={{ animationDelay: `${Math.min(index, 8) * 70}ms`, animationFillMode: 'backwards' }}>
      <div className="flex flex-wrap items-center gap-x-3 gap-y-2">
        <GameAvatar game={s.game} size={44} />
        <div className="min-w-0 flex-1 basis-40">
          <a href={`/servers/${s.id}`} className="block wrap-break-word text-fs-xl font-extrabold leading-tight hover:text-link">{s.name}</a>
          <div className="truncate font-mono text-sm font-semibold text-mute">{s.address}</div>
        </div>
        {s.online && (
          <span className="st-players" title={t('st.players.title', { p: s.players, m: s.maxPlayers })}>
            <b>{s.players}/{s.maxPlayers} <span>{t('st.players.word')}</span></b>
            <i className="st-meter" aria-hidden><i style={{ width: `${fill}%` }} /></i>
          </span>
        )}
        <StatusPill online={s.online} known lag={lag} />
      </div>
      <div className="st-server-body">
        <div className="min-w-0 flex-1">
          <UptimeBar s={s} />
        </div>
        <div className="st-server-side">
          <div className="st-up">
            <div className={`st-up-v is-${upTone}`}>{s.uptime30 == null ? '–' : fmtPct(s.uptime30)}</div>
            <div className="st-up-k">{incidents30 ? t('st.inc30', { n: incidents30, d: s.days.length }) : t('st.noInc30', { d: s.days.length })}</div>
          </div>
          {s.avgPing != null && <div className="st-ping-inline">{t('st.ping', { n: s.avgPing })}</div>}
          <Latency s={s} />
        </div>
      </div>
    </li>
  );
}

function Banner({ data, fetchedAt }: { data: StatusInfo; fetchedAt: number }) {
  const servers = data.servers;
  const total = servers.length;
  const up = servers.filter((s) => s.online).length;
  const ongoing = (data.incidents ?? []).filter((i) => i.end == null && !i.planned).length;
  const lastBad = (data.incidents ?? []).find((i) => !i.planned);
  const ups = servers.map((s) => s.uptime30).filter((v): v is number => v != null);
  const avg = ups.length ? ups.reduce((a, b) => a + b, 0) / ups.length : null;
  const players = servers.reduce((n, s) => n + (s.online ? s.players : 0), 0);
  const upN = Math.round(useCountUp(up));
  const playersN = Math.round(useCountUp(players));
  const avgN = useCountUp(avg ?? 0);
  const [tone, title, text] = up === total
    ? ['ok', t('st.hero.ok'), t('st.hero.okText')]
    : up === 0
      ? ['bad', t('st.hero.bad'), t('st.hero.badText')]
      : ['warn', t('st.hero.some', { n: total - up }), t('st.hero.someText')];
  const last = ongoing > 0 ? t('st.last.now') : lastBad ? t('st.last.ago', { when: ago(lastBad.start) }) : t('st.last.none', { d: data.range ?? 30 });
  return (
    <section className={`st-banner is-${tone}`} role="status">
      <span className="st-banner-ico" aria-hidden>{tone === 'ok' ? <IconCheck /> : tone === 'warn' ? <IconWarn /> : <IconCross />}</span>
      <div className="min-w-0 flex-1 basis-60">
        <h2 className="text-2xl font-black leading-tight sm:text-3xl">{title}</h2>
        <p className="mt-1 font-semibold opacity-85">{text}</p>
        <div className="st-segs" role="img" aria-label={t('st.seg.aria', { up, total })}>
          {servers.map((s) => (
            <span key={s.id} className={`st-seg ${!s.online ? 'is-down' : s.avgPing != null && s.avgPing > 100 ? 'is-lag' : 'is-up'}`} title={t(s.online ? 'st.seg.on' : 'st.seg.off', { name: s.name })} />
          ))}
        </div>
        <div className="st-banner-meta">
          <span>{last}</span>
          <Refresh fetchedAt={fetchedAt} />
        </div>
      </div>
      <dl className="st-banner-stats">
        <div><dt><IconServer />{t('st.stat.online')}</dt><dd>{t('st.stat.of', { a: upN, b: total })}</dd></div>
        <div><dt><IconUsers />{t('st.stat.players')}</dt><dd>{playersN}</dd></div>
        <div><dt><IconAct />{t('st.stat.uptime', { d: data.range ?? 30 })}</dt><dd>{avg == null ? '–' : fmtPct(avgN)}</dd></div>
        {ongoing > 0 && <div className="is-alert"><dt><IconAlert />{t('st.stat.now')}</dt><dd>{ongoing}</dd></div>}
      </dl>
    </section>
  );
}

/** «обновлено 12 с назад» with a ring that fills up to the next poll */
function Refresh({ fetchedAt }: { fetchedAt: number }) {
  const now = useNow(1000);
  const p = Math.min(1, Math.max(0, (now - fetchedAt) / POLL_MS));
  const C = 2 * Math.PI * 7;
  return (
    <span className="st-refresh">
      <svg width="18" height="18" viewBox="0 0 18 18" aria-hidden>
        <circle cx="9" cy="9" r="7" className="st-ring-bg" />
        <circle cx="9" cy="9" r="7" className="st-ring" strokeDasharray={C} strokeDashoffset={C * (1 - p)} />
      </svg>
      {t('st.updated', { ago: ago(fetchedAt) })}
    </span>
  );
}

function IncidentItem({ i }: { i: StatusIncident }) {
  const live = i.end == null;
  const kind = i.planned ? 'planned' : live ? 'live' : 'past';
  return (
    <li className={`st-inc is-${kind}`}>
      <GameAvatar game={i.game} size={36} />
      <div className="min-w-0 flex-1">
        <div className="flex flex-wrap items-center gap-x-2 gap-y-1">
          <span className="min-w-0 font-extrabold [overflow-wrap:anywhere]">{i.serverName}</span>
          <span className={`st-inc-badge is-${kind}`}>{i.planned ? t('st.inc.planned') : live ? t('st.inc.live') : t('st.inc.done')}</span>
        </div>
        <p className="text-sm font-semibold text-mute">
          {live ? t('st.inc.liveText', { dur: dur(i.minutes), from: fmtTime(i.start) }) : t('st.inc.pastText', { dur: dur(i.minutes), from: fmtTime(i.start), to: fmtTime(i.end!) })}
          {i.playersBefore > 0 && t('st.inc.players', { n: i.playersBefore })}
        </p>
      </div>
      <time className="shrink-0 text-xs font-bold text-mute" dateTime={new Date(i.start).toISOString()} title={fmtDateTime(i.start)}>{ago(i.start)}</time>
    </li>
  );
}

/** notes of the administrators: «Идут работы», «Причина найдена», «Починено»; closed ones are calm and stay for two weeks */
function NotesBoard({ notes }: { notes: StatusNote[] }) {
  if (notes.length === 0) return null;
  return (
    <section className="space-y-2" aria-label={t('st.notes')}>
      {notes.map((n) => {
        const done = n.resolvedAt != null;
        const tone = done ? 'ok' : n.level;
        return (
          <article key={n.id} className={`st-note is-${tone}`} role={done || n.level === 'info' ? undefined : 'alert'}>
            <div className="flex flex-wrap items-center gap-x-2 gap-y-1">
              <h2 className="font-extrabold">{n.title}</h2>
              <span className={`st-inc-badge is-${done ? 'past' : n.level === 'bad' ? 'live' : n.level === 'warn' ? 'planned' : 'past'}`}>{done ? t('st.note.done') : t(`st.note.${n.level}` as const)}</span>
              {n.serverName && <span className="text-sm font-bold text-mute">{n.serverName}</span>}
              <time className="ml-auto text-xs font-bold text-mute" dateTime={new Date(n.createdAt).toISOString()} title={fmtDateTime(n.createdAt)}>{ago(n.createdAt)}</time>
            </div>
            {n.body && <p className="mt-1 whitespace-pre-line text-sm font-semibold">{n.body}</p>}
            {done && <p className="mt-1 text-xs font-bold text-mute">{t('st.note.closed', { when: ago(n.resolvedAt as number) })}</p>}
          </article>
        );
      })}
    </section>
  );
}

const PAGE = 10;

/** incidents of the 30 days grouped by day, newest first; ten at first, then «Показать ещё» */
function Incidents({ list, days }: { list: StatusIncident[]; days: number }) {
  const [shown, setShown] = useState(PAGE);
  const groups = useMemo(() => {
    const m = new Map<string, StatusIncident[]>();
    for (const i of list.slice(0, shown)) {
      const key = new Date(i.start).toLocaleDateString(loc(), { day: 'numeric', month: 'long', weekday: 'long' });
      m.set(key, [...(m.get(key) ?? []), i]);
    }
    return [...m];
  }, [list, shown]);
  return (
    <section className="tile tile-in p-4 sm:p-5">
      <h2 className="mb-3 text-lg font-extrabold">{t('st.hist')}</h2>
      {list.length === 0 ? (
        <div className="st-calm">
          <span aria-hidden>✨</span>
          <div>
            <p className="font-extrabold">{t('st.hist.none', { d: days })}</p>
            <p className="text-sm font-semibold text-mute">{t('st.hist.noneText')}</p>
          </div>
        </div>
      ) : (
        <div className="space-y-4">
          {groups.map(([day, items]) => (
            <div key={day}>
              <h3 className="mb-2 text-xs font-extrabold uppercase tracking-wide text-mute">{day}</h3>
              <ul className="st-tl">{items.map((i) => <IncidentItem key={`${i.serverId}-${i.start}`} i={i} />)}</ul>
            </div>
          ))}
          {list.length > shown && (
            <button type="button" className="btn btn-soft" onClick={() => setShown((n) => n + PAGE)}>{t('st.hist.more', { n: list.length - shown })}</button>
          )}
        </div>
      )}
    </section>
  );
}

const LEGEND = ['ok', 'blip', 'warn', 'bad', 'planned', 'none'] as const;

/** Public status page: the state now, 30 days of availability per server and the incidents behind it. */
const IconPulse = () => <Icon size={22}><path d="M22 12h-4l-3 9L9 3l-3 9H2" /></Icon>;

export default function StatusPage() {
  useI18n();
  const { isAdmin } = useAuth();
  const [data, setData] = useState<StatusInfo | null>(null);
  const [error, setError] = useState('');
  const [fetchedAt, setFetchedAt] = useState(() => Date.now());

  // 30 days or three months of bars: the choice is remembered in this browser
  const [range, setRange] = useState<30 | 90>(() => { try { return localStorage.getItem('coregsm_status_range') === '90' ? 90 : 30; } catch { return 30; } });
  const rangeRef = useRef(range);
  rangeRef.current = range;
  const pickRange = (r: 30 | 90) => { setRange(r); try { localStorage.setItem('coregsm_status_range', String(r)); } catch { /* not remembered */ } };
  useEffect(() => { void load(); }, [range]);
  const load = () =>
    api<StatusInfo>(`/status${rangeRef.current === 90 ? '?days=90' : ''}`)
      .then((r) => { setData(r); setFetchedAt(Date.now()); setError(''); })
      .catch((e: Error) => setError(e.message));
  usePoll(load, POLL_MS);
  const month = data ? (data.incidents ?? []).filter((i) => !i.planned).length : 0;
  const subtitle = data && data.servers.length > 0
    ? t('st.sub', { servers: t('st.servers', { n: data.servers.length }), outages: month ? t('st.inc30', { n: month, d: range }) : t('st.noInc30', { d: range }) })
    : t('st.sub.none', { d: range });

  return (
    <div className="space-y-5">
      <PageHead icon={<IconPulse />} title={t('st.title')} subtitle={subtitle} />
      {error && !data ? <LoadError error={error} onRetry={() => void load()} /> : <ErrorLine text={error} />}

      {!data && !error && (
        <div className="space-y-3" aria-busy="true" aria-label={t('st.loading')}>
          <div className="skeleton panel h-28" />
          <div className="skeleton panel h-36" />
          <div className="skeleton panel h-36" />
        </div>
      )}

      {data && data.servers.length === 0 && (
        <Empty title={t('st.empty')} text={t('st.emptyText')}>{isAdmin && <a href="/admin/servers/new" className="btn mt-2">{t('st.add')}</a>}</Empty>
      )}

      {data && data.servers.length > 0 && (
        <div className="fade-in space-y-5">
          <NotesBoard notes={data.notes ?? []} />
          <Banner data={data} fetchedAt={fetchedAt} />
          <ul className="space-y-3">
            {data.servers.map((s, i) => <ServerRow key={s.id} s={s} index={i} />)}
          </ul>
          <div className="seg w-fit" role="group" aria-label={t('st.range')}>
            {([30, 90] as const).map((r) => (
              <button key={r} type="button" className="seg-item" aria-pressed={range === r} onClick={() => pickRange(r)}>{t('st.range.n', { d: r })}</button>
            ))}
          </div>
          <div className="flex flex-wrap items-center gap-x-4 gap-y-2 text-sm font-semibold text-mute">
            {LEGEND.map((c) => (
              <span key={c} className="inline-flex items-center gap-1.5"><span className={`st-day st-legend is-${c}`} aria-hidden />{t(`st.leg.${c}` as const)}</span>
            ))}
          </div>
          <Incidents list={data.incidents ?? []} days={data.range ?? range} />
        </div>
      )}
    </div>
  );
}
__COREGSM_EOF__
  mkdir -p "$APP_DIR/core-frontend/src/pages"
  cat > "$APP_DIR/core-frontend/src/pages/System.tsx" << '__COREGSM_EOF__'
import { useMemo, useState } from 'react';
import { api, type CertInfo } from '../api';
import { Gauge, usageTone, type GaugeTone } from '../components/Gauge';
import HealthHistoryCard, { type HealthFlag } from '../components/HealthHistoryCard';
import ProbesSection from '../components/ProbesSection';
import { AdminPage, ErrorLine, GoLink, LoadError, IconDatabase, IconDisk, IconMemory, IconSystem, Notice, PageHead, Section, Strip, ago, fmtDateTime, fmtTime, plural, usePoll } from '../ui';

interface Health {
  version: string | null;
  versionName?: string | null;
  uptimeSec: number;
  node: string;
  dbBytes: number | null;
  diskFree: number | null;
  diskTotal: number | null;
  memoryMb: number;
  load1?: number;
  cpuCount?: number;
  counts: { servers: number; online: number; bindings: number; users: number; history: number };
  bot: { state: string; tag: string | null; error: string | null; updatedAt: number };
  guilds: number;
  publicBase: string | null;
  cert?: CertInfo;
  flags?: HealthFlag[];
}
interface Check { id: string; label: string; status: 'ok' | 'warn' | 'fail'; detail: string }

const mb = (n: number | null) => (n == null ? '–' : n > 1073741824 ? `${(n / 1073741824).toFixed(1)} ГБ` : `${(n / 1048576).toFixed(1)} МБ`);
const dur = (s: number) => (s < 3600 ? `${Math.floor(s / 60)} мин` : s < 86400 ? `${Math.floor(s / 3600)} ч ${Math.floor((s % 3600) / 60)} мин` : `${Math.floor(s / 86400)} д ${Math.floor((s % 86400) / 3600)} ч`);

// the backend reports the process memory and the database file only, so they are drawn against a fixed reference size
const MEM_REF_MB = 512;
const DB_REF_BYTES = 1024 * 1048576;

const certTone = (c: CertInfo): GaugeTone => (c.daysLeft == null ? 'mute' : c.daysLeft <= 0 ? 'bad' : c.daysLeft <= 14 ? 'warn' : 'ok');
const certText = (c: CertInfo) => {
  if (c.daysLeft == null) return 'нет (панель работает по HTTP)';
  const d = c.daysLeft;
  return d <= 0 ? 'истёк' : `${d} ${plural(d, ['день', 'дня', 'дней'])}`;
};

/** Health, diagnostics and the certificate; the backups live under Settings → «Обновления и копии». */
export default function SystemPage() {
  const [h, setH] = useState<Health | null>(null);
  const [checks, setChecks] = useState<{ at: number; list: Check[] } | null>(null);
  const [running, setRunning] = useState(false);
  const [error, setError] = useState('');
  const [histFlags, setHistFlags] = useState<HealthFlag[]>([]);

  const load = () => api<Health>('/system').then((r) => { setH(r); setError(''); }).catch((e: Error) => setError(e.message));
  usePoll(load, 15_000);

  const run = async () => {
    setRunning(true);
    await api<{ at: number; checks: Check[] }>('/system/run', 'POST').then((r) => setChecks({ at: r.at, list: r.checks })).catch((e: Error) => setError(e.message));
    setRunning(false);
  };

  // warnings from /system and from the history, one per kind (the earliest «с» wins)
  const flags = useMemo(() => {
    const m = new Map<string, HealthFlag>();
    for (const f of [...(h?.flags ?? []), ...histFlags]) {
      const old = m.get(f.kind);
      if (!old || f.since < old.since) m.set(f.kind, f);
    }
    return [...m.values()].sort((a, b) => a.since - b.since);
  }, [h, histFlags]);

  const diskUsed = h && h.diskTotal && h.diskFree != null ? 1 - h.diskFree / h.diskTotal : null;
  const memFrac = h ? h.memoryMb / MEM_REF_MB : null;
  const cpuFrac = h && h.load1 != null && h.cpuCount ? h.load1 / h.cpuCount : null;
  const dbFrac = h && h.dbBytes != null ? h.dbBytes / DB_REF_BYTES : null;

  const botTone: GaugeTone = !h ? 'mute' : h.bot.state === 'online' ? 'ok' : h.bot.state === 'connecting' ? 'warn' : h.bot.state === 'error' ? 'bad' : 'mute';
  const status: { k: string; v: string; sub?: string; tone: GaugeTone }[] = h
    ? [
        { k: 'Версия', v: h.versionName || (h.version ? h.version.slice(0, 7) : 'сборка из исходников'), sub: `Node ${h.node}`, tone: 'mute' },
        { k: 'Работает', v: dur(h.uptimeSec), tone: 'ok' },
        { k: 'Серверы', v: `${h.counts.online} из ${h.counts.servers} онлайн`, tone: h.counts.servers === 0 ? 'mute' : h.counts.online === h.counts.servers ? 'ok' : h.counts.online === 0 ? 'bad' : 'warn' },
        { k: 'Привязки Discord', v: String(h.counts.bindings), sub: `${h.guilds} ${plural(h.guilds, ['сервер', 'сервера', 'серверов'])} с ботом`, tone: 'mute' },
        { k: 'Бот', v: h.bot.state === 'online' ? 'в сети' : h.bot.state === 'idle' ? 'ожидание' : h.bot.state === 'connecting' ? 'подключается' : 'ошибка', sub: h.bot.tag ?? (h.bot.updatedAt ? ago(h.bot.updatedAt) : undefined), tone: botTone },
        ...(h.cert ? [{ k: 'Сертификат HTTPS', v: certText(h.cert), sub: [h.cert.issuer, h.cert.selfSigned ? 'самоподписанный' : null].filter(Boolean).join(' · ') || undefined, tone: certTone(h.cert) }] : []),
        { k: 'Пользователи', v: String(h.counts.users), tone: 'mute' as GaugeTone },
      ]
    : [];
  const dot = { ok: 'dot-ok', warn: 'dot-warn', fail: 'dot-bad' } as const;

  return (
    <AdminPage
      head={(
        <PageHead
          icon={<IconSystem />}
          title="Система"
          subtitle="Состояние панели и диагностика"
          hint="Здоровье панели: версия, место на диске, бот, сертификат HTTPS. Если что-то не работает, начните с проверки."
          help={<p>Проверка занимает несколько секунд: она смотрит базу, диск, подключение бота, опрос серверов и доступ к Discord и GitHub. Зелёная точка значит, что всё в порядке, жёлтая — стоит присмотреться, красная — нужно исправить.</p>}
        >
          <button className="btn" onClick={run} disabled={running}>{running ? 'Проверяю…' : 'Запустить проверку'}</button>
        </PageHead>
      )}
    >
      {error && !h ? <LoadError error={error} onRetry={() => void load()} /> : <ErrorLine text={error} />}

      {flags.length > 0 && (
        <div className="space-y-2" role="group" aria-label="Предупреждения">
          {flags.map((f) => (
            <Notice key={f.kind} tone="warn">
              {f.text}<span className="font-semibold opacity-80"> · с {new Date(f.since).toDateString() === new Date().toDateString() ? fmtTime(f.since) : fmtDateTime(f.since)}</span>
            </Notice>
          ))}
        </div>
      )}

      {h ? (
        <>
          <div className="grid grid-cols-1 gap-4 min-[460px]:grid-cols-2 xl:grid-cols-4" role="group" aria-label="Ресурсы">
            <div className="panel p-5 text-center">
              <Gauge
                value={diskUsed}
                label="Диск: занято"
                display={diskUsed == null ? '–' : `${Math.round(diskUsed * 100)} %`}
                caption={h.diskFree != null ? `свободно ${mb(h.diskFree)}` : undefined}
                icon={<IconDisk size={18} />}
              />
              <div className="mt-2 font-extrabold">Диск</div>
              <div className="text-sm font-semibold text-mute">{h.diskTotal ? `всего ${mb(h.diskTotal)}` : 'размер неизвестен'}</div>
            </div>
            <div className="panel p-5 text-center">
              <Gauge value={cpuFrac} tone={usageTone(cpuFrac)} label="Нагрузка процессора" display={cpuFrac == null ? '–' : `${Math.round(cpuFrac * 100)} %`} caption={h.load1 != null ? `load ${h.load1}` : undefined} icon={<IconSystem size={18} />} />
              <div className="mt-2 font-extrabold">Процессор</div>
              <div className="text-sm font-semibold text-mute">{h.cpuCount ? `ядер: ${h.cpuCount}, средняя за минуту` : 'нет данных'}</div>
            </div>
            <div className="panel p-5 text-center">
              <Gauge value={memFrac} tone={usageTone(memFrac)} label="Память панели" display={`${h.memoryMb} МБ`} caption={`из ${MEM_REF_MB} МБ`} icon={<IconMemory size={18} />} />
              <div className="mt-2 font-extrabold">Память</div>
              <div className="text-sm font-semibold text-mute">процесс панели, ориентир {MEM_REF_MB} МБ</div>
            </div>
            <div className="panel p-5 text-center">
              <Gauge value={dbFrac} tone={usageTone(dbFrac)} label="База данных" display={mb(h.dbBytes)} caption="ориентир 1 ГБ" icon={<IconDatabase size={18} />} />
              <div className="mt-2 font-extrabold">База данных</div>
              <div className="text-sm font-semibold text-mute">{h.counts.history.toLocaleString('ru-RU')} точек истории</div>
            </div>
          </div>

          {h.cert && h.cert.daysLeft != null && (
            <Section title="Сертификат HTTPS" description={h.cert.notAfter ? `Действует до ${fmtDateTime(h.cert.notAfter)}` : undefined}>
              <div className="cert-bar" role="img" aria-label={`Осталось дней: ${h.cert.daysLeft}`}>
                <i className={`is-${certTone(h.cert)}`} style={{ width: `${Math.max(2, Math.min(100, (h.cert.daysLeft / 90) * 100))}%` }} />
              </div>
              <p className="text-sm font-semibold text-mute">
                {certText(h.cert)} из 90{h.cert.selfSigned ? ' · самоподписанный: браузеры покажут предупреждение' : h.cert.issuer ? ` · выдал ${h.cert.issuer}` : ''}.
                {h.cert.daysLeft <= 14 ? ' Пора продлевать: обычно это делает ваш обратный прокси (Caddy, Nginx Proxy Manager, certbot).' : ''}
              </p>
            </Section>
          )}

          <Section title="Состояние">
            <ul className="divide-y divide-line">
              {status.map((r) => (
                <li key={r.k} className="flex flex-wrap items-center gap-x-3 gap-y-0.5 py-2.5">
                  <span aria-hidden className={`h-2.5 w-2.5 shrink-0 rounded-full dot-${r.tone}`} />
                  <span className="font-extrabold">{r.k}</span>
                  {r.sub && <span className="min-w-0 wrap-break-word text-sm font-semibold text-mute">{r.sub}</span>}
                  <span className={`ml-auto font-black tabular-nums ${r.tone === 'bad' ? 'text-bad' : r.tone === 'warn' ? 'text-warn' : ''}`}>{r.v}</span>
                </li>
              ))}
            </ul>
          </Section>
        </>
      ) : (
        <div className="skeleton panel h-40" aria-busy="true" aria-label="Загрузка" />
      )}

      <HealthHistoryCard onFlags={setHistFlags} />

      <Section title="Диагностика" description="Проверяет базу, диск, бота, опрос серверов и доступ к Discord и GitHub.">
        {!checks && <p className="text-sm font-semibold text-mute">Нажмите «Запустить проверку» вверху страницы: результат появится здесь.</p>}
        {checks && (
          <>
            <ul className="divide-y divide-line rounded-ui-lg border border-line">
              {checks.list.map((c) => (
                <li key={c.id} className="flex items-start gap-3 px-4 py-2.5">
                  <span className={`mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full ${dot[c.status]}`} role="img" aria-label={c.status === 'ok' ? 'в порядке' : c.status === 'warn' ? 'внимание' : 'ошибка'} />
                  <div className="min-w-0">
                    <div className="font-extrabold">{c.label}</div>
                    <div className="wrap-break-word text-sm font-semibold text-mute">{c.detail}</div>
                  </div>
                </li>
              ))}
            </ul>
            <p className="text-sm font-semibold text-mute">Проверено {fmtDateTime(checks.at)}</p>
          </>
        )}
      </Section>

      <ProbesSection />

      <Strip>
        <div className="min-w-0">
          <h2 className="text-lg font-black">Резервные копии</h2>
          <p className="font-semibold text-mute">Скачать копию данных, настроить расписание или восстановить панель из файла.</p>
        </div>
        <GoLink href="/admin/settings/updates">Обновления и копии</GoLink>
      </Strip>
    </AdminPage>
  );
}
__COREGSM_EOF__
  mkdir -p "$APP_DIR/core-frontend/src/pages"
  cat > "$APP_DIR/core-frontend/src/pages/UiKit.tsx" << '__COREGSM_EOF__'
import { useState, type ReactNode } from 'react';
import { AccentPicker } from '../components/AccentPicker';
import { BtnSpinner } from '../components/Button';
import { SplitButton } from '../components/SplitButton';
import { Gauge } from '../components/Gauge';
import MaintenanceChip from '../components/MaintenanceChip';
import { buildSparkline } from '../sparkline';
import { confirmDialog, promptDialog } from '../confirm';
import { SubscribeForm } from '../components/server/SubscribeMenu';
import { badgeText, type SubKind } from '../notifications';
import { unreadableSecrets } from '../security';
import {
  AdminPage, Button, Empty, ErrorLine, FieldError, FillBar, GoLink, ICON_SET, IconBell, IconPlus, IconRefresh, IconTrash, IconEdit, Modal,
  Notice, PageHead, PasswordField, SaveBadge, Section, Spinner, StateView, StatusPill, Strip, Switch, TextField, ThemeToggle, toast, undoable,
  type SaveStatus,
} from '../ui';

/** reference page for future screens: /_ui (administrators only, not listed in any menu) */

const RADII: [string, string][] = [['sm', '8 px'], ['md', '12 px'], ['lg', '16 px'], ['xl', '26 px'], ['pill', '9999 px']];
const SHADOWS: [string, string][] = [['shadow-1', 'мелкие элементы'], ['shadow-2', 'карточки'], ['shadow-3', 'всплывающее']];
const SURFACES: [string, string, string][] = [
  ['page', 'bg-page', 'фон страницы'], ['card', 'bg-card', 'карточка'], ['raised', 'bg-raised', 'диалоги, меню'], ['soft', 'bg-soft', 'поля, подложки'],
];
const TEXTS: [string, string][] = [['text-ink', 'Основной текст'], ['text-mute', 'Вторичный текст'], ['text-link', 'Ссылка и акцент'], ['text-ok', 'Успех'], ['text-warn', 'Внимание'], ['text-bad', 'Ошибка']];

function Block({ title, note, children }: { title: string; note?: ReactNode; children: ReactNode }) {
  return (
    <Section title={title} description={note}>
      {children}
    </Section>
  );
}

const Row = ({ label, children }: { label?: string; children: ReactNode }) => (
  <div className="space-y-2">
    {label && <div className="text-sm font-extrabold text-mute">{label}</div>}
    <div className="flex flex-wrap items-center gap-2.5">{children}</div>
  </div>
);

/** one specimen (buttons, pill, field, switch, card) that is shown in a forced theme next to the other one */
/** bell badge, subscription kinds, new-device strip and the unreadable-secrets list: the pieces of the notification and security extras */
function NotifyExtras() {
  const [kinds, setKinds] = useState<SubKind[]>(['free_slot']);
  const secrets = unreadableSecrets(['discord_token', 'smtp_password', 'proxy_url']);
  return (
    <div className="space-y-4">
      <Row label="Колокольчик: значок непрочитанных (до 99, дальше 99+)">
        {[0, 3, 99, 150].map((n) => (
          <span key={n} className="relative grid h-10 w-10 place-items-center rounded-full bg-soft text-mute">
            <IconBell size={20} />
            {badgeText(n) && <span className="absolute -right-1 -top-1 min-w-[18px] rounded-full bg-bad px-1 text-center text-xs font-extrabold leading-[18px] text-white shadow-[0_0_0_2px_rgb(var(--card))]">{badgeText(n)}</span>}
          </span>
        ))}
      </Row>
      <div className="max-w-md"><SubscribeForm kinds={kinds} onChange={setKinds} discordLinked={false} idPrefix="kit-sub" /></div>
      <div className="flex flex-wrap items-center gap-x-4 gap-y-2.5 rounded-2xl bg-warnbg px-4 py-3 text-warn">
        <span className="min-w-0 flex-1 basis-60 text-sm font-bold">Вход с нового устройства: Chrome на Windows. Это были вы?</span>
        <span className="flex gap-2"><button className="btn btn-soft btn-sm">Это я</button><button className="btn btn-danger btn-sm">Нет, выйти на всех устройствах</button></span>
      </div>
      <div className="space-y-2 rounded-ui-lg bg-warnbg p-4 text-warn">
        <h3 className="font-black">Часть секретов не удалось прочитать</h3>
        <ul className="list-disc pl-5 font-bold">{secrets.map((x) => <li key={x.id}>{x.label}</li>)}</ul>
      </div>
    </div>
  );
}

/** the button system: every variant at every size, then the states; `compact` is the short version shown in both themes */
const BTN_VARIANTS: [string, string][] = [
  ['btn', 'Основная'], ['btn btn-soft', 'Мягкая'], ['btn btn-outline', 'Контур'], ['btn btn-ghost', 'Призрачная'],
  ['btn btn-danger', 'Опасная'], ['btn btn-danger-solid', 'Удалить'], ['btn btn-success', 'Успех'], ['btn btn-success-solid', 'Готово'], ['btn btn-warn', 'Внимание'],
];
const BTN_SIZES: [string, string][] = [['btn-xs', 'XS 28'], ['btn-sm', 'SM 34'], ['', 'MD 42'], ['btn-lg', 'LG 50']];

function ButtonKit({ compact = false }: { compact?: boolean }) {
  const [pressed, setPressed] = useState({ a: true, b: false });
  const [group, setGroup] = useState('week');
  const sizes = compact ? BTN_SIZES.filter(([c]) => c === 'btn-sm' || c === '') : BTN_SIZES;
  return (
    <div className="space-y-4">
      {sizes.map(([sz, name]) => (
        <Row key={name} label={`Размер ${name} px`}>
          {BTN_VARIANTS.map(([cls, label]) => <button key={cls} type="button" className={`${cls} ${sz}`}>{label}</button>)}
        </Row>
      ))}
      <Row label="Недоступные (disabled)">
        {BTN_VARIANTS.map(([cls, label]) => <button key={cls} type="button" className={cls} disabled>{label}</button>)}
      </Row>
      <Row label="Загрузка (aria-busy, спиннер перед текстом)">
        {BTN_VARIANTS.map(([cls, label]) => <button key={cls} type="button" className={cls} disabled aria-busy="true"><BtnSpinner />{label}</button>)}
      </Row>
      <Row label="Переключатели (aria-pressed)">
        <button type="button" className="btn btn-soft" aria-pressed={pressed.a} onClick={() => setPressed((p) => ({ ...p, a: !p.a }))}>Включено</button>
        <button type="button" className="btn btn-soft" aria-pressed={pressed.b} onClick={() => setPressed((p) => ({ ...p, b: !p.b }))}>Выключено</button>
        <button type="button" className="btn btn-outline" aria-pressed>Контур</button>
        <button type="button" className="btn btn-ghost" aria-pressed>Призрачная</button>
        <button type="button" className="btn-icon" aria-pressed aria-label="Закреплено"><IconBell /></button>
      </Row>
      <Row label="С иконкой и во всю ширину">
        <button type="button" className="btn"><IconPlus size={16} />С иконкой</button>
        <button type="button" className="btn btn-soft btn-sm"><IconRefresh size={16} />Обновить</button>
        <button type="button" className="btn btn-outline btn-sm"><IconEdit size={16} />Изменить</button>
        <button type="button" className="btn btn-danger btn-sm"><IconTrash size={16} />Удалить</button>
        <button type="button" className="btn btn-block">Во всю ширину</button>
      </Row>
      <Row label="Иконки-кнопки (всегда с aria-label)">
        <button type="button" className="btn-icon" aria-label="Обновить"><IconRefresh /></button>
        <button type="button" className="btn-icon-sm" aria-label="Обновить"><IconRefresh size={16} /></button>
        <button type="button" className="btn-icon-ghost" aria-label="Обновить"><IconRefresh /></button>
        <button type="button" className="btn-icon-danger" aria-label="Удалить"><IconTrash /></button>
        <button type="button" className="row-act" aria-label="Изменить"><IconEdit /></button>
        <button type="button" className="row-act row-act-danger" aria-label="Удалить"><IconTrash /></button>
        <button type="button" className="btn-icon" aria-label="Недоступно" disabled><IconRefresh /></button>
      </Row>
      <Row label="Текстовые: действие внутри текста">
        <span className="text-sm font-semibold">Обновите данные: <button type="button" className="btn-link">обновить список</button> или <button type="button" className="btn-link-danger">удалить токен</button>.</span>
      </Row>
      <Row label="Группа и составная кнопка">
        <span className="btn-group" role="group" aria-label="Период">
          {[['day', 'День'], ['week', 'Неделя'], ['month', 'Месяц']].map(([k, label]) => (
            <button key={k} type="button" className="btn btn-soft btn-sm" aria-pressed={group === k} onClick={() => setGroup(k)}>{label}</button>
          ))}
        </span>
        <span className="btn-group" role="group" aria-label="Действия">
          <button type="button" className="btn btn-outline btn-sm">Назад</button>
          <button type="button" className="btn btn-outline btn-sm">Вперёд</button>
        </span>
        <SplitButton label="Опросить" onClick={() => undefined} items={[{ key: 'a', label: 'Опросить все', hint: 'Все выбранные', onSelect: () => undefined }, { key: 'b', label: 'Только онлайн', onSelect: () => undefined }]} />
      </Row>
      <Row label="На градиенте и на обложке">
        <div className="cover-grad flex flex-wrap items-center gap-2.5 rounded-ui-lg p-4" style={{ ['--c1' as string]: '#4338ca', ['--c2' as string]: '#7c3aed' }}>
          <button type="button" className="btn-cta">Подключиться</button>
          <button type="button" className="btn-on-grad">Белая</button>
          <button type="button" className="btn-ghost-on-grad">Прозрачная</button>
          <button type="button" className="btn-glass"><IconBell size={18} />Подписаться</button>
          <button type="button" className="btn-glass-quiet">Тихая</button>
          <button type="button" className="btn-glass-quiet btn-glass-danger">Опасная</button>
          <button type="button" className="btn-icon-glass" aria-label="В избранное">☆</button>
          <button type="button" className="btn-glass" disabled>Недоступна</button>
          <span className="chip-on-grad">Чип</span>
        </div>
      </Row>
    </div>
  );
}

function Specimen() {
  const [on, setOn] = useState(true);
  const [seg, setSeg] = useState('a');
  return (
    <div className="space-y-3.5">
      <div className="panel space-y-3 p-4">
        <div className="flex flex-wrap items-center gap-2">
          <button className="btn btn-sm">Основная</button>
          <button className="btn btn-soft btn-sm">Мягкая</button>
          <button className="btn btn-danger btn-sm">Опасная</button>
          <span className="pill pill-ok">ОНЛАЙН</span>
          <span className="pill pill-warn">ЛАГИ</span>
          <span className="pill pill-bad">ОФЛАЙН</span>
          <span className="pill pill-mute">ОЖИДАНИЕ</span>
        </div>
        <ButtonKit compact />
        <input className="input" defaultValue="Поле ввода" aria-label="Пример поля" />
        <label className="flex items-center gap-3 text-sm font-bold"><Switch checked={on} onChange={setOn} /> Переключатель</label>
        <div className="seg">
          {['a', 'b', 'c'].map((k, i) => <button key={k} type="button" className="seg-item" aria-pressed={seg === k} onClick={() => setSeg(k)}>Вкладка {i + 1}</button>)}
        </div>
      </div>
      <div className="panel panel-raised space-y-1 p-4">
        <div className="font-black">Приподнятая поверхность</div>
        <p className="text-sm font-semibold text-mute">Диалоги и меню: на один шаг светлее карточки.</p>
        <a href="/_ui" className="text-sm font-extrabold text-link hover:underline">Ссылка</a>
      </div>
    </div>
  );
}

