/** Settings → Updates: version check, changelog, update and rollback through the host updater. */
import { type CSSProperties, useEffect, useRef, useState } from 'react';
import { api, type Changelog, type UpdateInfo, type UpdateNotes, type UpdatePreflight } from '../../api';
import { confirmDialog } from '../../confirm';
import { t } from '../../i18n';
import { ago, ErrorLine, fmtDate, IconArrowUp, IconCheck, Spinner, usePoll, errText } from '../../ui';
import { HistoryCard, NotesCard, OptionsCard, PreflightNote, StepList } from './updateParts';
import { offered, versionText } from './updateLogic';

const DISMISS_KEY = 'coregsm_dismissed_update_error';
const readDismissed = (): number => {
  try { return Number(localStorage.getItem(DISMISS_KEY)) || 0; } catch { return 0; }
};
const rememberDismissed = (t: number) => {
  try { localStorage.setItem(DISMISS_KEY, String(t)); } catch { /* not remembered */ }
};

export function UpdateCard() {
  const [info, setInfo] = useState<UpdateInfo | null>(null);
  const [error, setError] = useState('');
  const [busy, setBusy] = useState(false);
  // set when "Update" or "Rollback" was pressed: remembers the previous job timestamp to recognise the new result
  const [waiting, setWaiting] = useState<{ since: number; baseTime: number | null; kind: 'update' | 'rollback' } | null>(null);
  const [offline, setOffline] = useState(false);
  const [log, setLog] = useState<Changelog | null>(null);
  const [logError, setLogError] = useState('');
  const [notes, setNotes] = useState<UpdateNotes | null>(null);
  const [pf, setPf] = useState<UpdatePreflight | null>(null);

  useEffect(() => {
    api<Changelog>('/update/changelog')
      .then((r) => { setLog(r); setLogError(r.error ?? ''); })
      .catch((e: Error) => setLogError(e.message));
    api<UpdateNotes>('/update/notes').then(setNotes).catch(() => setNotes({ releases: [], error: null }));
    api<UpdatePreflight>('/update/preflight').then(setPf).catch(() => undefined);
  }, []);

  // percent of the running job: only grows while the same job runs (never goes backwards between polls)
  const [pct, setPct] = useState<number | null>(null);
  const pctJob = useRef<number | null>(null);
  const [finished, setFinished] = useState<'update' | 'rollback' | null>(null);
  const running = !!waiting || info?.job?.state === 'running';

  usePoll(() => {
    api<UpdateInfo>('/update/status')
      .then((r) => {
        setOffline(false);
        setInfo(r);
        const j = r.job;
        const current = !!j && (j.state === 'running' || (!!waiting && j.time !== waiting.baseTime));
        if (j && current && typeof j.progress === 'number') {
          const p = Math.max(0, Math.min(100, Math.round(j.progress)));
          if (pctJob.current !== j.time) { pctJob.current = j.time; setPct(p); } else setPct((c) => Math.max(c ?? 0, p));
        }
        if (!waiting || !j || j.time === waiting.baseTime) return;
        if (j.state === 'done') {
          setFinished(waiting.kind);
          setPct(100);
          setWaiting(null);
          // new frontend files are served now: reload to pick them up
          setTimeout(() => window.location.reload(), 1500);
        } else if (j.state === 'error') {
          setWaiting(null);
          setError(j.message);
        }
      })
      .catch(() => {
        // the backend restarts during an update
        if (waiting || info?.job?.state === 'running') setOffline(true);
      });
  }, running && !finished ? 2_000 : 30_000);

  const check = async () => {
    setBusy(true);
    setError('');
    try {
      setInfo(await api<UpdateInfo>('/update/check', 'POST'));
    } catch (e) {
      setError(errText(e));
    } finally {
      setBusy(false);
    }
  };

  const apply = async () => {
    const players = pf?.players ?? 0;
    const text = players > 0 ? `${t('upd.c.text')}\n\n${t('upd.c.players', { n: players })}` : t('upd.c.text');
    if (!(await confirmDialog({ title: t('upd.c.title'), text, confirmLabel: t('upd.c.ok') }))) return;
    setBusy(true);
    setError('');
    try {
      const r = await api<UpdateInfo>('/update/apply', 'POST');
      setInfo(r);
      setPct(null);
      setFinished(null);
      setWaiting({ since: Date.now(), baseTime: r.job?.time ?? null, kind: 'update' });
    } catch (e) {
      setError(errText(e));
    } finally {
      setBusy(false);
    }
  };

  const rollback = async () => {
    const ok = await confirmDialog({
      title: t('upd.rb.title'),
      text: t('upd.rb.text'),
      confirmLabel: t('upd.rb.ok'),
      danger: true,
    });
    if (!ok) return;
    setBusy(true);
    setError('');
    try {
      const r = await api<UpdateInfo>('/update/rollback', 'POST');
      setInfo(r);
      setPct(null);
      setFinished(null);
      setWaiting({ since: Date.now(), baseTime: r.job?.time ?? null, kind: 'rollback' });
    } catch (e) {
      setError(errText(e));
    } finally {
      setBusy(false);
    }
  };

  const rollingBack = (waiting?.kind ?? finished) === 'rollback' || (info?.stage === 'rollback' && running);
  // an old failure matters only while an update is still pending; a manual install that succeeded makes it moot
  const [dismissed, setDismissed] = useState<number>(readDismissed);
  const showOldFailure = !running && !error && info?.job?.state === 'error' && !!info.available && info.job.time !== dismissed;
  const stuck = !!waiting && Date.now() - waiting.since > 60_000 && !!info?.pending;

  const skipped = !!info?.available && !!info.skipped;
  const state: 'running' | 'available' | 'latest' | 'skipped' | 'unknown' = running || finished ? 'running' : offered(info) ? 'available' : skipped ? 'skipped' : info?.latest ? 'latest' : 'unknown';
  const lastChecked = info?.checkedAt ?? null;
  const onGrad = state === 'available' || state === 'running';
  const curText = versionText(info?.currentLabel, info?.current);
  const newText = versionText(info?.latestLabel, info?.latest);

  const setSkip = async (build: string | null) => {
    setBusy(true);
    setError('');
    try {
      setInfo(await api<UpdateInfo>('/update/settings', 'PUT', { skip: build }));
    } catch (e) {
      setError(errText(e));
    } finally {
      setBusy(false);
    }
  };

  const title =
    state === 'running' ? (rollingBack ? t('upd.t.rolling') : t('upd.t.running'))
    : state === 'available' ? t('upd.t.available')
    : state === 'latest' ? t('upd.t.latest')
    : state === 'skipped' ? t('upd.t.skipped')
    : t('upd.t.checking');
  const subtitle =
    state === 'running'
      ? finished ? t('upd.s.done') : offline ? t('upd.s.restarting') : info?.job?.state === 'running' && info.job.message ? info.job.message : ''
      : state === 'available' ? t('upd.s.available')
      : state === 'latest' ? (lastChecked ? t('upd.s.latestChecked', { when: ago(lastChecked) }) : t('upd.s.latest'))
      : state === 'skipped' ? t('upd.s.skipped', { v: newText })
      : t('upd.s.checking');

  return (
    <div className="space-y-5">
      <section
        aria-live="polite"
        className={`relative overflow-hidden rounded-ui-xl p-6 sm:p-7 ${
          state === 'available' ? 'update-hero text-white' : state === 'running' ? 'update-hero update-hero-run text-white' : 'panel'
        }`}
      >
        {onGrad && <span aria-hidden className="pointer-events-none absolute -right-14 -top-14 h-56 w-56 rounded-full bg-white/15" />}
        <div className="relative flex flex-wrap items-start gap-4">
          <span
            aria-hidden
            className={`grid h-14 w-14 shrink-0 place-items-center rounded-2xl ${
              onGrad ? 'bg-white/20 text-white' : state === 'latest' ? 'bg-okbg text-ok' : 'bg-soft text-mute'
            }`}
          >
            {state === 'latest' ? (
              <IconCheck size={30} />
            ) : state === 'running' ? (
              <Spinner className="h-7 w-7" />
            ) : (
              <IconArrowUp size={30} className={state === 'available' ? 'update-bob' : ''} />
            )}
          </span>
          <div className="min-w-0 flex-1">
            <h2 className="text-2xl font-extrabold leading-tight" style={{ letterSpacing: '-0.02em' }}>{title}</h2>
            <p className={`mt-1 font-semibold ${onGrad ? 'text-white/90' : 'text-mute'}`}>{subtitle}</p>

            <dl className="mt-4 flex flex-wrap items-center gap-2 text-sm font-bold">
              <div className={`flex flex-wrap items-center gap-x-2 rounded-full px-3.5 py-1.5 ${onGrad ? 'bg-white/20' : 'bg-soft'}`}>
                <dt className={onGrad ? 'text-white/85' : 'text-mute'}>{t('upd.installed')}</dt>
                <dd className="font-mono">{curText}</dd>
                {info?.installedAt ? <dd className={`font-sans font-semibold ${onGrad ? 'text-white/80' : 'text-mute'}`}>{t('upd.since', { date: fmtDate(info.installedAt) })}</dd> : null}
              </div>
              {state === 'available' && <span aria-hidden className="text-lg font-black text-white/90">→</span>}
              <div className={`flex flex-wrap items-center gap-x-2 rounded-full px-3.5 py-1.5 ${state === 'available' ? 'bg-white text-ink' : state === 'running' ? 'bg-white/20' : 'bg-soft'}`}>
                <dt className={state === 'running' ? 'text-white/85' : 'text-mute'}>{t('upd.inRepo')}</dt>
                <dd className="font-mono">{newText}</dd>
                {info?.latestAt ? <dd className="font-sans font-semibold text-mute">{t('upd.from', { date: fmtDate(info.latestAt) })}</dd> : null}
              </div>
            </dl>
          </div>
        </div>

        {state === 'running' && (
          <div className="relative mt-5 space-y-3">
            {!rollingBack && <StepList stage={info?.stage} finished={!!finished} />}
            <div className="flex items-center gap-3">
              <div
                className={`update-progress min-w-0 flex-1 ${pct != null ? 'det' : ''}`}
                role="progressbar"
                aria-label={rollingBack ? t('upd.aria.rollback') : t('upd.aria.update')}
                aria-valuemin={0}
                aria-valuemax={100}
                aria-valuenow={pct ?? undefined}
              >
                <i style={pct != null ? ({ '--p': `${pct}%` } as CSSProperties) : undefined} />
              </div>
              {pct != null && <span className="w-14 shrink-0 text-right text-lg font-black tabular-nums" aria-hidden>{pct} %</span>}
              {finished && (
                <span className="grid h-7 w-7 shrink-0 place-items-center rounded-full bg-okbg text-ok" aria-hidden>
                  <IconCheck size={16} />
                </span>
              )}
            </div>
          </div>
        )}

        {state === 'available' && <PreflightNote pf={pf} current={info?.currentLabel} notes={notes} />}

        <div className="relative mt-5 flex flex-wrap items-center gap-2.5">
          {state === 'available' && (
            <>
              <button className="btn-on-grad btn-lg" onClick={apply} disabled={busy || running || !info?.canApply}>
                {busy ? t('upd.btn.sending') : t('upd.btn.now')}
              </button>
              <a className="btn-ghost-on-grad" href="#update-changes" onClick={(e) => { e.preventDefault(); document.getElementById('update-changes')?.scrollIntoView({ behavior: 'smooth', block: 'start' }); }}>{t('upd.btn.notes')}</a>
              <button className="btn-ghost-on-grad" onClick={check} disabled={busy || running}>{t('upd.btn.recheck')}</button>
              {info?.latest && <button className="btn-ghost-on-grad" onClick={() => void setSkip(info.latest)} disabled={busy || running}>{t('upd.btn.skip')}</button>}
            </>
          )}
          {state === 'skipped' && (
            <>
              <button className="btn" onClick={apply} disabled={busy || running || !info?.canApply}>{t('upd.btn.anyway')}</button>
              <button className="btn btn-soft" onClick={() => void setSkip(null)} disabled={busy || running}>{t('upd.btn.unskip')}</button>
            </>
          )}
          {(state === 'latest' || state === 'unknown') && (
            <button className="btn" onClick={check} disabled={busy || running}>{busy ? t('upd.btn.checking') : t('upd.btn.check')}</button>
          )}
          {info?.canRollback && state !== 'running' && (
            <button className={`${state === 'available' ? 'btn-ghost-on-grad' : 'btn btn-soft'} sm:ml-auto`} onClick={() => void rollback()} disabled={busy || running}>{t('upd.btn.rollback')}</button>
          )}
        </div>

        {info && !info.canApply && state !== 'running' && (
          <p className={`relative mt-3 text-sm font-semibold ${state === 'available' ? 'rounded-2xl bg-black/15 px-4 py-2.5 font-bold' : 'text-mute'}`}>
            {t('upd.noApply')} <span className="font-mono">sudo coregsm update</span>.
          </p>
        )}
        {stuck && (
          <p className="relative mt-3 rounded-2xl bg-badbg px-4 py-2.5 text-sm font-bold text-bad">
            {t('upd.stuck')} <span className="font-mono">systemctl status coregsm-update.path</span> {rollingBack ? t('upd.stuckRb') : <>{t('upd.stuckUp')} <span className="font-mono">sudo coregsm update</span></>}.
          </p>
        )}
        {info?.error && !running && <p className="relative mt-3 text-sm font-semibold text-mute">{info.error}</p>}
        {showOldFailure && info?.job && (
          <div className="relative mt-3 flex flex-wrap items-start justify-between gap-3 rounded-2xl bg-badbg px-4 py-2.5 text-sm font-bold text-bad">
            <span>{t('upd.oldFail', { msg: info.job.message })}</span>
            <button type="button" className="btn-link btn-link-tone" onClick={() => { rememberDismissed(info.job!.time); setDismissed(info.job!.time); }}>{t('upd.hide')}</button>
          </div>
        )}
        <div className="relative"><ErrorLine text={error} /></div>
      </section>

      <NotesCard notes={notes} log={log} logError={logError} current={info?.currentLabel} installedAt={info?.installedAt} />
      <HistoryCard refreshKey={info?.job?.time ?? 0} />
      {info && <OptionsCard info={info} onChange={setInfo} />}
    </div>
  );
}
__COREGSM_EOF__
  mkdir -p "$APP_DIR/core-frontend/src/pages/settings"
  cat > "$APP_DIR/core-frontend/src/pages/settings/UsersTab.tsx" << '__COREGSM_EOF__'
/** Users: registration and access settings, pending requests, roles and passwords. */
import RulesHistoryCard from '../../components/RulesHistoryCard';
import { useEffect, useRef, useState, type KeyboardEvent } from 'react';
import { type Access, api, type Perm, PERM_LABELS, type UserRow } from '../../api';
import '../../styles/admin.css';
import { useAuth } from '../../auth';
import { Switch as ToggleSwitch } from '../../components/Switch';
import { promptDialog } from '../../confirm';
import { getPrefs, t, useI18n, type TKey } from '../../i18n';
import { AdminPage, DiscordBadge, ErrorLine, GoLink, IconKey, IconTrash, IconUsers, PageHead, SaveBadge, Section, TextField, UserAvatar, ago, toast, undoable, useAutosave } from '../../ui';
import { SaveBarProvider, useSaveBar, useSaveBarActive } from '../../saveBar';

function Switch({ on, onChange, label, hint }: { on: boolean; onChange: (v: boolean) => void; label: string; hint: string }) {
  return (
    <label className="flex cursor-pointer items-start gap-3">
      <ToggleSwitch className="mt-0.5" checked={on} onChange={onChange} />
      <span>
        <span className="block font-extrabold">{label}</span>
        <span className="block text-sm font-semibold text-mute">{hint}</span>
      </span>
    </label>
  );
}

/** ready sets of moderator permissions */
const PERM_PRESETS: { label: TKey; perms: Perm[] }[] = [
  { label: 'us.preset.news', perms: ['news'] },
  { label: 'us.preset.comm', perms: ['news', 'moderation', 'journal'] },
  { label: 'us.preset.srv', perms: ['servers', 'maintenance'] },
  { label: 'us.preset.none', perms: [] },
];

const ONLINE_MS = 5 * 60_000;
/** «в сети» / «был 3 ч назад» / «ещё не заходил» */
function seenText(u: UserRow, now = Date.now()): { online: boolean; text: string } {
  if (!u.lastSeen) return { online: false, text: t('us.seen.never') };
  if (now - u.lastSeen < ONLINE_MS) return { online: true, text: t('us.seen.online') };
  return { online: false, text: t('us.seen.was', { ago: ago(u.lastSeen) }) };
}

type UserTab = 'users' | 'access' | 'rules' | 'roles';
const USER_TABS: [UserTab, TKey][] = [['users', 'us.tab.users'], ['access', 'us.tab.access'], ['rules', 'us.tab.rules'], ['roles', 'us.tab.roles']];
const TAB_KEY = 'coregsm_admin_users_tab';

const ROLE_LABEL =(r: UserRow['role']): string => t(`us.role.${r}` as const);

/** The users page: the rules text joins the common save bar. */
export function UsersTab() {
  return <SaveBarProvider><UsersTabInner /></SaveBarProvider>;
}

function UsersTabInner() {
  useI18n();
  const { me, reload } = useAuth();
  const [access, setAccess] = useState<Access | null>(null);
  const [users, setUsers] = useState<UserRow[]>([]);
  const [error, setError] = useState('');
  const [loaded, setLoaded] = useState(false);
  const [q, setQ] = useState('');
  const [roleFilter, setRoleFilter] = useState<'all' | UserRow['role']>('all');
  const [picked, setPicked] = useState<number[]>([]);
  const [hidden, setHidden] = useState<number[]>([]);
  const [rules, setRules] = useState('');
  const [banFor, setBanFor] = useState<number | null>(null);
  const [banReason, setBanReason] = useState('');
  const [banHours, setBanHours] = useState(24);
  const rulesInit = useRef(false);
  // the section of the page: the list of people first; the choice is remembered in this browser
  const [tab, setTab] = useState<UserTab>(() => {
    try { const v = localStorage.getItem(TAB_KEY); return USER_TABS.some(([id]) => id === v) ? (v as UserTab) : 'users'; } catch { return 'users'; }
  });
  const pickTab = (id: UserTab) => { setTab(id); try { localStorage.setItem(TAB_KEY, id); } catch { /* not remembered */ } };
  const onTabKey = (e: KeyboardEvent<HTMLElement>) => {
    const d = e.key === 'ArrowRight' ? 1 : e.key === 'ArrowLeft' ? -1 : 0;
    if (!d && e.key !== 'Home' && e.key !== 'End') return;
    e.preventDefault();
    const i = USER_TABS.findIndex(([id]) => id === tab);
    const n = e.key === 'Home' ? 0 : e.key === 'End' ? USER_TABS.length - 1 : (i + d + USER_TABS.length) % USER_TABS.length;
    pickTab(USER_TABS[n][0]);
    document.getElementById(`us-tab-${USER_TABS[n][0]}`)?.focus();
  };

  const load = () => {
    api<Access>('/access').then((a) => {
      setAccess(a);
      // the text is taken from the server once: a later reload must not replace what is being typed
      if (!rulesInit.current) { rulesInit.current = true; setRules(a.rules ?? ''); }
    }).catch((e) => setError(e.message));
    api<UserRow[]>('/users').then(setUsers).catch((e) => setError(e.message)).finally(() => setLoaded(true));
  };
  useEffect(load, []);

  const save = async (patch: Partial<Access>) => {
    await api<Access>('/access', 'PUT', patch).then((a) => { setAccess(a); void reload(); toast(t('us.saved')); }).catch((e) => setError(e.message));
  };
  const approve = async (u: UserRow) => {
    await api(`/users/${u.id}/approve`, 'POST').then(() => toast(t('us.approved', { name: u.username }))).catch((e) => setError(e.message));
    load();
  };
  // an account that is deleted goes out of the list at once and can be taken back for 6 s; the request is sent after that
  const dropUsers = (list: UserRow[], text: string) => {
    const ids = list.map((u) => u.id);
    setHidden((h) => [...h, ...ids]);
    setPicked((p) => p.filter((x) => !ids.includes(x)));
    undoable({
      text,
      restore: () => setHidden((h) => h.filter((x) => !ids.includes(x))),
      commit: async () => {
        const res = await Promise.allSettled(ids.map((id) => api(`/users/${id}`, 'DELETE')));
        if (res.some((r) => r.status === 'rejected')) setError(t('us.delFail'));
        setHidden((h) => h.filter((x) => !ids.includes(x)));
        load();
      },
    });
  };
  const reject = (u: UserRow) => dropUsers([u], t('us.rejected'));
  const approveMany = async (list: UserRow[]) => {
    const res = await Promise.allSettled(list.map((u) => api(`/users/${u.id}/approve`, 'POST')));
    const bad = res.filter((r) => r.status === 'rejected').length;
    toast(bad ? t('us.approvedMany', { a: list.length - bad, b: bad }) : t('us.approvedAll', { n: list.length }), bad ? 'err' : undefined);
    setPicked([]);
    load();
  };
  // the rules text is saved as you type (after a pause and on leaving the field); the text is never replaced under the cursor
  const bar = useSaveBarActive();
  const rulesAuto = useAutosave({
    manual: bar,
    value: rules,
    saved: access?.rules ?? '',
    enabled: !!access,
    delay: 1200,
    equal: (a, b) => a.trim() === b.trim(),
    validate: (v) => (v.length > 5000 ? t('us.rulesMax') : null),
    save: async (v) => {
      const a = await api<Access>('/access', 'PUT', { rules: v.trim() });
      setAccess(a);
      void reload();
    },
  });
  useSaveBar('rules', t('us.rulesBar'), rulesAuto.status, rulesAuto.saveNow, () => setRules(access?.rules ?? ''));
  const setPerms = async (u: UserRow, perms: Perm[]) => {
    await api(`/users/${u.id}`, 'PUT', { role: u.role, perms }).then(() => { toast(t('us.permsSaved')); void load(); }).catch((e) => setError(e.message));
  };
  const setRole = async (u: UserRow, role: UserRow['role']) => {
    await api(`/users/${u.id}`, 'PUT', { role }).then(() => toast(t('us.roleChanged'))).catch((e) => setError(e.message));
    load();
  };
  const ban = async (u: UserRow) => {
    await api(`/users/${u.id}/ban`, 'POST', { reason: banReason.trim(), hours: banHours || null })
      .then(() => { toast(t('us.banDone', { name: u.username })); setBanFor(null); setBanReason(''); })
      .catch((e) => setError(e.message));
    void load();
  };
  const unban = async (u: UserRow) => {
    await api(`/users/${u.id}/unban`, 'POST').then(() => toast(t('us.unbanDone', { name: u.username }))).catch((e) => setError(e.message));
    void load();
  };
  const resetPassword = async (u: UserRow) => {
    const pw = await promptDialog({
      title: t('us.pwTitle', { name: u.username }),
      label: t('us.pwLabel'),
      password: true,
      confirmLabel: t('us.pwBtn'),
      validate: (v) => (v.length < 8 ? t('us.pwMin') : null),
    });
    if (!pw) return;
    await api(`/users/${u.id}/password`, 'PUT', { password: pw }).then(() => toast(t('us.pwDone'))).catch((e) => setError(e.message));
  };
  const remove = (u: UserRow) => dropUsers([u], t('us.userDeleted'));

  const visible = users.filter((u) => !hidden.includes(u.id));
  const pendingUsers = visible.filter((u) => u.status === 'pending');
  const needle = q.trim().toLowerCase();
  const listed = visible.filter((u) => (roleFilter === 'all' || u.role === roleFilter) && (!needle || `${u.username} ${u.discordName ?? ''}`.toLowerCase().includes(needle)));
  const pickedPending = pendingUsers.filter((u) => picked.includes(u.id));
  const togglePick = (id: number) => setPicked((p) => (p.includes(id) ? p.filter((x) => x !== id) : [...p, id]));

  return (
    <AdminPage
      head={(
        <PageHead
          icon={<IconUsers />}
          title={t('us.title')}
          subtitle={t('us.sub')}
          hint={t('us.hint')}
          help={<p>{t('us.help')}</p>}
        >
          <a className="btn btn-soft" href="/admin/journal">{t('us.journal')}</a>
        </PageHead>
      )}
    >
      <div className="no-scrollbar -mx-1 overflow-x-auto px-1" role="tablist" aria-label={t('us.tabs')} onKeyDown={onTabKey}>
        <div className="seg flex w-max min-w-full">
          {USER_TABS.map(([id, label]) => (
            <button
              key={id}
              type="button"
              role="tab"
              id={`us-tab-${id}`}
              aria-selected={tab === id}
              aria-controls={`us-panel-${id}`}
              tabIndex={tab === id ? 0 : -1}
              className={`seg-item min-h-11 whitespace-nowrap ${tab === id ? 'on' : ''}`}
              onClick={() => pickTab(id)}
            >
              {t(label)}{id === 'users' && pendingUsers.length > 0 ? ` · ${pendingUsers.length}` : ''}
            </button>
          ))}
        </div>
      </div>

      {tab === 'access' && (
      <div role="tabpanel" id="us-panel-access" aria-labelledby="us-tab-access" className="space-y-5">
      <Section title={t('us.who')}>
        {access && (
          <>
            <Switch on={access.publicPanel} onChange={(v) => void save({ publicPanel: v })} label={t('us.public')} hint={t('us.publicHint')} />
            <Switch on={access.registration} onChange={(v) => void save({ registration: v })} label={t('us.reg')} hint={t('us.regHint')} />
            <div className="pl-8">
              <label htmlFor="reg-mode" className="label">{t('us.regMode')}</label>
              <select id="reg-mode" className="input w-auto! max-w-full" value={access.registrationMode} disabled={!access.registration} onChange={(e) => void save({ registrationMode: e.target.value as Access['registrationMode'] })}>
                <option value="open">{t('us.regOpen')}</option>
                <option value="approval">{t('us.regApproval')}</option>
              </select>
            </div>
          </>
        )}
        <p className="text-sm font-semibold text-mute">{t('us.guestNote')}</p>
        <div className="rounded-ui-lg bg-soft px-4 py-3 text-sm font-semibold text-mute">
          <p><b className="text-ink">{t('us.r.player')}</b>{t('us.r.playerText')}</p>
          <p><b className="text-ink">{t('us.r.mod')}</b>{t('us.r.modText')}</p>
          <p><b className="text-ink">{t('us.r.admin')}</b>{t('us.r.adminText')}</p>
        </div>
      </Section>
      </div>
      )}

      {tab === 'rules' && (
      <div role="tabpanel" id="us-panel-rules" aria-labelledby="us-tab-rules" className="space-y-5">
      <Section
        title={t('us.rules')}
        description={t('us.rulesText')}
        actions={<SaveBadge status={rulesAuto.status} error={rulesAuto.error} retry={rulesAuto.retry} />}
      >
        <TextField
          id="rules"
          label={t('us.rulesLabel')}
          multiline
          rows={6}
          maxLength={5000}
          value={rules}
          onChange={setRules}
          onBlur={rulesAuto.flush}
          error={rulesAuto.invalid ? rulesAuto.error : undefined}
          placeholder={t('us.rulesHolder')}
          hint={`${rules.length} / 5000`}
          className="min-h-32"
        />
      </Section>

      <RulesHistoryCard rulesKey={rules} onRestore={setRules} />
      </div>
      )}

      {tab === 'users' && (
      <div role="tabpanel" id="us-panel-users" aria-labelledby="us-tab-users" className="space-y-5">
      {pendingUsers.length > 0 && (
        <Section
          title={t('us.req')}
          actions={(
            <>
              <button type="button" className="btn btn-soft btn-sm" onClick={() => setPicked(pickedPending.length === pendingUsers.length ? [] : pendingUsers.map((u) => u.id))}>
