.adm-item[draggable='true'] { cursor: grab; }

/* ---------- servers table: sticky head, state stripe, details; journal; presets; density ---------- */
/* clipped at the rounded corners, but a wide table scrolls sideways instead of losing its last column */
.tile.adm-tablewrap { overflow-x: auto; overflow-y: clip; }
