@media (prefers-reduced-motion: reduce) { .adm-ind, .adm-status-dot { transition: none; animation: none; } }

/* ---------- servers: cards view, the floating bulk bar ---------- */
.adm-cards { display: grid; gap: 10px; grid-template-columns: 1fr; }
@media (min-width: 768px) { .adm-cards { grid-template-columns: repeat(auto-fill, minmax(18rem, 1fr)); } .adm-cards[data-hide-md] { display: none; } }
.adm-card { position: relative; box-shadow: inset 4px 0 0 rgb(var(--ok)), var(--shadow-1); transition: box-shadow .15s ease, transform .15s ease; }
.adm-card:hover { transform: translateY(-1px); }
.adm-card[data-state='off'] { box-shadow: inset 4px 0 0 rgb(var(--bad)), var(--shadow-1); }
.adm-card[data-state='lag'] { box-shadow: inset 4px 0 0 rgb(var(--warn)), var(--shadow-1); }
.adm-card[data-state='maint'] { box-shadow: inset 4px 0 0 rgb(var(--link)), var(--shadow-1); }
.adm-card[data-selected='true'] { background: rgb(var(--brand) / .1); }
.adm-bulk.adm-bulk-float { position: fixed; top: auto; bottom: 5.5rem; left: 50%; z-index: 45; width: max-content; max-width: calc(100vw - 2rem); transform: translateX(-50%); background: rgb(var(--raised)); box-shadow: var(--shadow-3), inset 0 0 0 1px rgb(var(--brand) / .5); animation: adm-rise .22s cubic-bezier(.2, .8, .2, 1); }
@media (min-width: 768px) { .adm-bulk.adm-bulk-float { bottom: 1.25rem; } }
@keyframes adm-rise { from { opacity: 0; transform: translate(-50%, 12px); } }
.adm-st:has(.adm-bulk) .adm-table thead th { top: 4.75rem; }
@media (prefers-reduced-motion: reduce) { .adm-bulk.adm-bulk-float { animation: none; } .adm-card { transition: none; } }

/* server form: the card as it will look in the list */
.sf-preview { display: flex; align-items: center; gap: 12px; padding: 12px 14px; border-radius: var(--r-xl); background: rgb(var(--soft)); box-shadow: inset 0 0 0 1px rgb(var(--line)); background-size: cover; background-position: center; }
.sf-preview[data-cover='true'] { color: #fff; }
.sf-preview-st { flex: none; padding: 3px 11px; border-radius: var(--r-pill); font-size: var(--fs-xs); font-weight: 750; background: rgb(var(--card)); color: rgb(var(--mute)); box-shadow: inset 0 0 0 1px rgb(var(--line)); font-variant-numeric: tabular-nums; }
.sf-preview-st.is-on { background: rgb(var(--okbg)); color: rgb(var(--ok)); box-shadow: none; }
.sf-preview-st.is-off { background: rgb(var(--badbg)); color: rgb(var(--bad)); box-shadow: none; }

/* users: cards, online dot, permissions grid */
.us-row, .us-req { padding-inline: 4px; border-radius: var(--r-md); transition: background-color .15s ease; }
.us-row:hover, .us-req:hover { background: rgb(var(--soft) / .55); }
.us-av { position: relative; display: inline-grid; flex: none; }
.us-online { position: absolute; right: -1px; bottom: -1px; width: 12px; height: 12px; border-radius: 50%; background: rgb(var(--ok)); box-shadow: 0 0 0 2px rgb(var(--card)); }
.us-perms { display: grid; grid-template-columns: repeat(auto-fill, minmax(15rem, 1fr)); }
.us-perms > .basis-full { grid-column: 1 / -1; }
.us-perm { align-items: flex-start; border-radius: var(--r-lg); padding: 8px 12px 8px 10px; }
.us-preset[aria-pressed='true'] { color: rgb(var(--link)); background: rgb(var(--brand) / .14); box-shadow: inset 0 0 0 1px rgb(var(--brand) / .45); }

/* discord: the chain server → channel → message, the bot ring */
.dc-flow { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 0; margin: 0; padding: 0; list-style: none; }
.dc-flow li { position: relative; display: grid; gap: 1px; min-width: 0; padding: 6px 10px; font-size: var(--fs-xs); font-weight: 650; color: rgb(var(--mute)); background: rgb(var(--soft)); box-shadow: inset 0 -3px 0 rgb(var(--ok)); }
.dc-flow li:first-child { border-radius: var(--r-md) 0 0 var(--r-md); }
.dc-flow li:last-child { border-radius: 0 var(--r-md) var(--r-md) 0; }
.dc-flow li + li { margin-left: 2px; }
.dc-flow li b { color: rgb(var(--ink)); font-weight: 800; }
.dc-flow li.is-bad { box-shadow: inset 0 -3px 0 rgb(var(--bad)); }
.dc-flow li.is-warn { box-shadow: inset 0 -3px 0 rgb(var(--warn)); }
.dc-flow li.is-mute { box-shadow: inset 0 -3px 0 rgb(var(--line)); }
.dc-ring { width: 14px; height: 14px; flex: none; border-radius: 50%; border: 3px solid rgb(var(--line)); }
.dc-ring.is-online { border-color: rgb(var(--ok)); animation: adm-pulse 2.4s ease-out infinite; }
.dc-ring.is-connecting { border-color: rgb(var(--warn)); border-top-color: transparent; animation: adm-spin 1s linear infinite; }
@keyframes adm-spin { to { transform: rotate(360deg); } }
.dc-ring.is-error { border-color: rgb(var(--bad)); }
@media (prefers-reduced-motion: reduce) { .dc-ring { animation: none !important; } }

/* alerts: kinds of messages, the delivery bar */
.al-kinds { display: grid; grid-template-columns: repeat(auto-fill, minmax(15rem, 1fr)); gap: 10px; }
.al-kind { display: grid; gap: 6px; padding: 12px 14px; border-radius: var(--r-lg); background: rgb(var(--card)); border: 1px solid rgb(var(--line)); box-shadow: var(--shadow-1); }
.al-kind.is-off { opacity: .6; box-shadow: none; background: rgb(var(--soft) / .6); }
.al-msg { padding: 8px 10px; border-radius: var(--r-md); border-left: 3px solid rgb(var(--brand)); background: rgb(var(--soft)); font-size: var(--fs-sm); font-weight: 650; }
.al-queue { display: flex; height: 8px; border-radius: var(--r-pill); overflow: hidden; background: rgb(var(--line)); }
.al-queue i { display: block; height: 100%; transition: width .4s ease; }
.al-queue i.is-ok { background: rgb(var(--ok)); }
.al-queue i.is-warn { background: rgb(var(--warn)); }
.al-queue i.is-bad { background: rgb(var(--bad)); }

/* system: the days of the certificate */
.cert-bar { height: 10px; border-radius: var(--r-pill); background: rgb(var(--line)); overflow: hidden; }
.cert-bar i { display: block; height: 100%; border-radius: var(--r-pill); background: rgb(var(--ok)); transition: width .5s ease; }
.cert-bar i.is-warn { background: rgb(var(--warn)); }
.cert-bar i.is-bad { background: rgb(var(--bad)); }

/* community: the seasons line, the moderation queue */
.se-line { display: flex; gap: 3px; margin: 0 0 10px; padding: 0; list-style: none; }
.se-line li { min-width: 3.5rem; padding: 6px 10px; border-radius: var(--r-md); background: rgb(var(--soft)); box-shadow: inset 0 0 0 1px rgb(var(--line)); font-size: var(--fs-xs); font-weight: 750; color: rgb(var(--mute)); overflow: hidden; }
.se-line li.is-now { color: #fff; background: linear-gradient(135deg, rgb(var(--brand)), rgb(var(--brand-2))); box-shadow: none; }
.mq { display: flex; flex-wrap: wrap; gap: 14px; padding: 12px; border-radius: var(--r-xl); background: rgb(var(--brand) / .08); box-shadow: inset 0 0 0 1px rgb(var(--brand) / .35); }
.mq-img { width: min(100%, 16rem); aspect-ratio: 16 / 9; object-fit: cover; border-radius: var(--r-lg); background: rgb(var(--soft)); }
.mq-body { flex: 1 1 14rem; min-width: 0; }
.mq kbd { margin-left: 4px; font: inherit; font-size: var(--fs-2xs); font-weight: 800; padding: 0 5px; border-radius: 5px; background: rgb(255 255 255 / .25); }

/* every admin page: the blocks come up one after another */
.adm-stage > * { animation: adm-in .35s cubic-bezier(.2, .8, .2, 1) both; }
.adm-stage > :nth-child(2) { animation-delay: .04s; }
.adm-stage > :nth-child(3) { animation-delay: .08s; }
.adm-stage > :nth-child(4) { animation-delay: .12s; }
.adm-stage > :nth-child(n+5) { animation-delay: .16s; }
@keyframes adm-in { from { opacity: 0; transform: translateY(8px); } }
@media (prefers-reduced-motion: reduce) { .adm-stage > * { animation: none; } }

/* admin news list: the thumbnail, the reactions */
.nl-thumb { width: 5.5rem; aspect-ratio: 16 / 10; flex: none; object-fit: cover; border-radius: var(--r-md); background: rgb(var(--soft)); box-shadow: inset 0 0 0 1px rgb(var(--line)); }
.nl-react { padding: 1px 9px; border-radius: var(--r-pill); background: rgb(var(--soft)); box-shadow: inset 0 0 0 1px rgb(var(--line)); font-variant-numeric: tabular-nums; }

/* the shared line chart (ui/LineChart.tsx): a cursor and a tooltip for the point under the pointer or the keyboard */
.lc-plot { cursor: crosshair; touch-action: pan-y; border-radius: var(--r-md); }
.lc-plot:focus-visible { outline: 2px solid rgb(var(--link)); }
.lc-cursor { position: absolute; top: 0; bottom: 0; width: 1px; background: rgb(var(--mute) / .7); pointer-events: none; }
.lc-tip { position: absolute; top: 4px; transform: translateX(-50%); padding: 3px 8px; border-radius: var(--r-sm); background: rgb(var(--card)); box-shadow: var(--shadow-1); font-size: var(--fs-xs); font-weight: 700; white-space: nowrap; pointer-events: none; }

/* the menu shrunk to icons (desktop only) */
@media (min-width: 768px) {
  .adm-rail { padding-inline: 6px; }
  .adm-rail .adm-lbl, .adm-rail .adm-group-title, .adm-rail .adm-pin, .adm-rail .adm-progress, .adm-rail .adm-find > :not(:first-child) { display: none; }
  .adm-rail .adm-link, .adm-rail .adm-density, .adm-rail .adm-find { justify-content: center; padding-inline: 0; }
  .adm-rail .adm-link.md\:w-full { padding-right: 0; }
  .adm-rail .adm-link { position: relative; }
  .adm-rail .adm-badge, .adm-rail .adm-dot, .adm-rail .update-dot { position: absolute; top: 2px; right: 4px; margin: 0; }
  .adm-rail .adm-badge { min-width: 1rem; height: 1rem; padding: 0 3px; font-size: var(--fs-2xs); line-height: 1rem; }
}

/* column chooser of the servers table */
.adm-cols { position: relative; }
.adm-cols > summary { list-style: none; padding: 6px 12px; border-radius: var(--r-md); background: rgb(var(--soft)); box-shadow: inset 0 0 0 1px rgb(var(--line)); font-weight: 650; }
.adm-cols > summary::-webkit-details-marker { display: none; }
.adm-cols[open] > summary { box-shadow: inset 0 0 0 1px rgb(var(--brand) / .5); }
.adm-cols-pop { position: absolute; left: 0; top: calc(100% + 6px); z-index: 40; min-width: 13rem; padding: 6px; border-radius: var(--r-lg); background: rgb(var(--overlay)); box-shadow: var(--shadow-3), inset 0 0 0 1px rgb(var(--line)); }

/* settings on the left, the live preview on the right (it stays in view while the settings scroll) */
.adm-split { display: grid; gap: 16px; }
@media (min-width: 1280px) {
  .adm-split { grid-template-columns: minmax(0, 1fr) minmax(0, 26rem); align-items: start; gap: 24px; }
  .adm-split-side { position: sticky; top: 6.5rem; }
}
__COREGSM_EOF__
  mkdir -p "$APP_DIR/core-frontend/src/styles"
  cat > "$APP_DIR/core-frontend/src/styles/analytics.css" << '__COREGSM_EOF__'
/* «Аналитика» tab of a server page. The colour is the game's (--srv-accent, set on .srv-page); --a is a cell's weight. */
.an { --an: var(--srv-accent, rgb(var(--brand))); }

.an-kpis { display: grid; gap: 10px; grid-template-columns: repeat(auto-fit, minmax(min(100%, 9.5rem), 1fr)); }
@media (max-width: 639px) { .an-kpi-v { font-size: 24px; } }
.an-kpi { border-radius: var(--r-lg, 18px); background: rgb(var(--soft)); padding: 12px 14px; }
.an-kpi-k { font-size: var(--fs-sm); font-weight: 650; color: rgb(var(--mute)); }
.an-kpi-v { margin-top: 2px; font-size: 30px; font-weight: 650; line-height: 1.1; letter-spacing: -0.02em; font-variant-numeric: tabular-nums; }
.an-kpi-h { margin-top: 4px; font-size: var(--fs-sm); font-weight: 600; color: rgb(var(--mute)); }

/* weekday x hour */
.an-heat { display: grid; grid-template-columns: 2.2rem repeat(24, minmax(0, 1fr)); gap: 3px; align-items: center; }
.an-heat-hour { font-size: var(--fs-xs); font-weight: 600; color: rgb(var(--mute)); text-align: left; }
.an-heat-dow { font-size: var(--fs-xs); font-weight: 650; color: rgb(var(--mute)); }
.an-heat-cell {
  height: clamp(12px, 2.6vw, 28px); border-radius: 5px;
  background: color-mix(in srgb, var(--an) calc(var(--a, 0) * 100%), rgb(var(--soft)));
  transition: transform .12s ease, box-shadow .12s ease;
}
.an-heat-cell.is-empty { background: repeating-linear-gradient(135deg, rgb(var(--soft)) 0 4px, transparent 4px 8px); }
.an-heat-cell.is-hover { transform: scale(1.18); box-shadow: 0 0 0 2px rgb(var(--card)), 0 0 0 4px var(--an); position: relative; z-index: 1; }
@media (max-width: 639px) { .an-heat { gap: 2px; grid-template-columns: 1.8rem repeat(24, minmax(0, 1fr)); } .an-heat-cell { border-radius: 3px; } }
.an-heat-foot { margin-top: 10px; display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 6px 16px; font-size: var(--fs-sm); font-weight: 600; color: rgb(var(--mute)); }
.an-heat-scale { display: inline-flex; align-items: center; gap: 4px; }
.an-heat-scale i { width: 14px; height: 14px; border-radius: 4px; background: color-mix(in srgb, var(--an) calc(var(--a) * 100%), rgb(var(--soft))); }
.an-facts { margin-top: 12px; display: grid; gap: 6px 18px; grid-template-columns: repeat(auto-fit, minmax(min(100%, 15rem), 1fr)); font-size: var(--fs-md); font-weight: 600; }
.an-facts p { border-left: 3px solid var(--an); padding: 2px 0 2px 10px; }
.an-facts b { display: block; font-size: var(--fs-xs); font-weight: 650; letter-spacing: .02em; text-transform: uppercase; color: rgb(var(--mute)); }

/* players per day */
.an-bars { display: flex; align-items: flex-end; gap: 3px; height: 180px; }
.an-bar { flex: 1 1 0; min-width: 2px; height: 100%; display: flex; flex-direction: column-reverse; border-radius: 6px 6px 2px 2px; overflow: hidden; cursor: default; }
.an-bar > span { display: block; width: 100%; transition: height .4s cubic-bezier(.2, .8, .2, 1); }
.an-bar-old { background: var(--an); }
.an-bar-new { background: color-mix(in srgb, var(--an) 40%, rgb(var(--card))); }
.an-bar.is-hover > span { filter: brightness(1.12) saturate(1.1); }
.an-bars-axis { display: flex; gap: 3px; margin-top: 6px; }
.an-bars-axis span { flex: 1 1 0; min-width: 2px; font-size: var(--fs-xs); font-weight: 600; color: rgb(var(--mute)); white-space: nowrap; overflow: visible; }
.an-legend { display: inline-flex; align-items: center; gap: 6px; }
.an-legend i { width: 12px; height: 12px; border-radius: 4px; }

/* visit lengths */
.an-hbar { display: grid; grid-template-columns: 7.5rem minmax(0, 1fr) 3rem; align-items: center; gap: 10px; font-size: var(--fs-md); }
.an-hbar-k { font-weight: 600; color: rgb(var(--mute)); }
.an-hbar-track { height: 12px; border-radius: var(--r-pill); background: rgb(var(--soft)); overflow: hidden; }
.an-hbar-track > span { display: block; height: 100%; border-radius: inherit; background: linear-gradient(90deg, color-mix(in srgb, var(--an) 55%, rgb(var(--card))), var(--an)); transition: width .5s cubic-bezier(.2, .8, .2, 1); }
.an-hbar-v { text-align: right; font-weight: 650; font-variant-numeric: tabular-nums; }

/* retention cohorts */
.an-cohorts { width: 100%; border-collapse: separate; border-spacing: 3px; font-size: var(--fs-sm); }
.an-cohorts th { font-weight: 650; color: rgb(var(--mute)); text-align: left; white-space: nowrap; padding: 4px 6px; }
.an-cohorts td { min-width: 3.4rem; border-radius: var(--r-sm); padding: 7px 6px; text-align: center; font-weight: 650; font-variant-numeric: tabular-nums;
  background: color-mix(in srgb, var(--an) calc(var(--a, 0) * 100%), rgb(var(--soft))); }
.an-cohorts td.is-strong { color: #fff; }
.an-cohorts td.is-empty { background: transparent; }

/* top players */
.an-top { display: grid; gap: 10px; }
.an-top li { display: flex; align-items: center; gap: 10px; }
.an-top-n { display: grid; place-items: center; width: 28px; height: 28px; flex: none; border-radius: var(--r-pill); background: rgb(var(--soft)); font-size: var(--fs-sm); font-weight: 650; color: rgb(var(--mute)); }
.an-top-n.is-1 { background: linear-gradient(135deg, #f6d365, #fda085); color: #5a3200; }
.an-top-n.is-2 { background: linear-gradient(135deg, #e0e6ee, #b6c2d1); color: #2b3442; }
.an-top-n.is-3 { background: linear-gradient(135deg, #f3c39b, #c98a5a); color: #4a2408; }
.an-top-bar { display: block; margin-top: 5px; height: 6px; border-radius: var(--r-pill); background: rgb(var(--soft)); overflow: hidden; }
.an-top-bar > span { display: block; height: 100%; border-radius: inherit; background: var(--an); }

@media (prefers-reduced-motion: reduce) { .an-bar > span, .an-hbar-track > span, .an-heat-cell { transition: none; } }
__COREGSM_EOF__
  mkdir -p "$APP_DIR/core-frontend/src/styles"
  cat > "$APP_DIR/core-frontend/src/styles/buttons.css" << '__COREGSM_EOF__'
/* buttons: the single source of truth for every button in the panel (imported in main.tsx after index.css and the other styles).

   Rules (see the black-square notes in index.css): no transform / translate / scale on buttons, hover and press feedback by
   background-color, colour, box-shadow and opacity only (<= .18s), border colours never transition (rings are inset
   box-shadows), no outline styling (the focus ring is the unlayered :focus-visible rule at the end of index.css), no
   backdrop-filter / will-change / filter, no endless animation except the spinner.

   Anatomy of a button: --b-* custom properties describe the look of a variant, one generic rule paints them.
     --b-bg / --b-bg-h  background colour at rest / on hover      --b-fg / --b-fg-h  text colour
     --b-img            background image (primary gradient)        --b-hl             1px inner top highlight
     --b-ring           1px inset ring                             --b-ovl            full inset wash (hover darkens / lightens)
     --b-drop           outer shadow                               -h / -a suffix: hover / pressed value (fall back to rest)
   Every variant class also works on its own (`btn-soft` without `btn`), `btn btn-soft` is the same thing.

   Variants   .btn (primary) .btn-soft .btn-outline .btn-ghost .btn-danger .btn-danger-solid (= .btn-solid-danger)
              .btn-success .btn-success-solid .btn-warn .btn-link (.btn-link-danger)
   Sizes      .btn-xs 28px  .btn-sm 34px  (default 42px)  .btn-lg 50px  .btn-block (full width)
   Icon       .btn-icon 40px  .btn-icon-sm 32px  .btn-icon-ghost  .btn-icon-danger  (always give them an aria-label); .row-act (compact row action)
   Groups     .btn-group joins buttons with a 1px gap
   Context    on a gradient: .btn-on-grad .btn-ghost-on-grad  .btn-cta ; on a cover: .btn-glass .btn-glass-quiet .btn-glass-danger .btn-icon-glass .pp-copy
   State      :disabled / [aria-disabled='true'] / [aria-busy='true'] / [aria-pressed='true']
   All sizes are rem: «Крупный текст» scales buttons together with the text. */

/* ---------- shared base ----------
   Layout properties live in :where() (zero specificity): a utility class on the element (hidden, w-full, rounded-xl,
   min-h-*, max-sm:hidden) always wins. Paint properties that Tailwind's preflight also sets (padding, font, colour,
   background) are at class specificity; do not fight them with utilities, use the size and variant classes. */
:where(
  .btn, .btn-soft, .btn-outline, .btn-ghost, .btn-danger, .btn-danger-solid, .btn-solid-danger, .btn-success, .btn-success-solid, .btn-warn, .btn-link, .btn-link-danger,
  .btn-icon, .btn-icon-sm, .btn-icon-ghost, .btn-icon-danger, .row-act,
  .btn-on-grad, .btn-ghost-on-grad, .btn-cta, .btn-glass, .btn-glass-quiet, .btn-icon-glass, .pp-copy
) {
  display: inline-flex; align-items: center; justify-content: center; gap: var(--b-gap, .5rem);
  min-height: max(var(--b-h, 2.625rem), var(--tap, 0px));
  border-radius: var(--r-pill);
  text-align: center; text-decoration: none; letter-spacing: .01em;
  cursor: pointer; user-select: none; -webkit-tap-highlight-color: transparent;
}
:is(
  .btn, .btn-soft, .btn-outline, .btn-ghost, .btn-danger, .btn-danger-solid, .btn-solid-danger, .btn-success, .btn-success-solid, .btn-warn, .btn-link, .btn-link-danger,
  .btn-icon, .btn-icon-sm, .btn-icon-ghost, .btn-icon-danger, .row-act,
  .btn-on-grad, .btn-ghost-on-grad, .btn-cta, .btn-glass, .btn-glass-quiet, .btn-icon-glass, .pp-copy
) {
  --b-h: 2.625rem; --b-px: 1.1rem; --b-fs: .9375rem; --b-gap: .5rem;
  --b-img: none; --b-bg: transparent; --b-fg: rgb(var(--ink));
  --b-hl: inset 0 1px 0 0 transparent; --b-ring: inset 0 0 0 1px transparent;
  --b-ovl: inset 0 0 0 999px transparent; --b-drop: 0 0 0 0 transparent;
  padding: .3rem var(--b-px);
  font-size: var(--b-fs); font-weight: 650; line-height: 1.2;
  color: var(--b-fg); background-color: var(--b-bg); background-image: var(--b-img);
  box-shadow: var(--b-hl), var(--b-ring), var(--b-ovl), var(--b-drop);
  /* colours and shadows only: no border/outline colour, no transform */
  transition: background-color .15s ease, color .15s ease, box-shadow .15s ease, opacity .15s ease;
}
:is(
  .btn, .btn-soft, .btn-outline, .btn-ghost, .btn-danger, .btn-danger-solid, .btn-solid-danger, .btn-success, .btn-success-solid, .btn-warn, .btn-link, .btn-link-danger,
  .btn-on-grad, .btn-ghost-on-grad, .btn-cta, .btn-glass, .btn-glass-quiet
) > svg { flex: none; width: 1.1em; height: 1.1em; }
:is(.btn-icon, .btn-icon-sm, .btn-icon-ghost, .btn-icon-danger, .row-act, .btn-icon-glass, .pp-copy) > svg { flex: none; }

/* ---------- states ---------- */
:is(
  .btn, .btn-soft, .btn-outline, .btn-ghost, .btn-danger, .btn-danger-solid, .btn-solid-danger, .btn-success, .btn-success-solid, .btn-warn, .btn-link, .btn-link-danger,
  .btn-icon, .btn-icon-sm, .btn-icon-ghost, .btn-icon-danger, .row-act,
  .btn-on-grad, .btn-ghost-on-grad, .btn-cta, .btn-glass, .btn-glass-quiet, .btn-icon-glass, .pp-copy
):where(:not(:disabled, [aria-disabled='true'])):hover {
  background-color: var(--b-bg-h, var(--b-bg)); color: var(--b-fg-h, var(--b-fg));
  box-shadow: var(--b-hl-h, var(--b-hl)), var(--b-ring-h, var(--b-ring)), var(--b-ovl-h, var(--b-ovl)), var(--b-drop-h, var(--b-drop));
}
:is(
  .btn, .btn-soft, .btn-outline, .btn-ghost, .btn-danger, .btn-danger-solid, .btn-solid-danger, .btn-success, .btn-success-solid, .btn-warn,
  .btn-icon, .btn-icon-sm, .btn-icon-ghost, .btn-icon-danger, .row-act,
  .btn-on-grad, .btn-ghost-on-grad, .btn-cta, .btn-glass, .btn-glass-quiet, .btn-icon-glass, .pp-copy
):where(:not(:disabled, [aria-disabled='true'])):active {
  background-color: var(--b-bg-a, var(--b-bg-h, var(--b-bg))); color: var(--b-fg-a, var(--b-fg-h, var(--b-fg)));
  box-shadow: var(--b-hl-a, var(--b-hl)), var(--b-ring-a, var(--b-ring-h, var(--b-ring))), var(--b-ovl-a, var(--b-ovl-h, var(--b-ovl))), var(--b-drop-a, var(--b-drop));
}
:is(
  .btn, .btn-soft, .btn-outline, .btn-ghost, .btn-danger, .btn-danger-solid, .btn-solid-danger, .btn-success, .btn-success-solid, .btn-warn, .btn-link, .btn-link-danger,
  .btn-icon, .btn-icon-sm, .btn-icon-ghost, .btn-icon-danger, .row-act,
  .btn-on-grad, .btn-ghost-on-grad, .btn-cta, .btn-glass, .btn-glass-quiet, .btn-icon-glass, .pp-copy
):is(:disabled, [aria-disabled='true']) { opacity: .62; cursor: not-allowed; box-shadow: none; }
/* busy: the label stays, a spinner precedes it (Button component); the button is disabled but should not look dead */
:is(
  .btn, .btn-soft, .btn-outline, .btn-ghost, .btn-danger, .btn-danger-solid, .btn-solid-danger, .btn-success, .btn-success-solid, .btn-warn, .btn-link, .btn-link-danger,
  .btn-icon, .btn-icon-sm, .btn-icon-ghost, .btn-icon-danger, .row-act,
  .btn-on-grad, .btn-ghost-on-grad, .btn-cta, .btn-glass, .btn-glass-quiet, .btn-icon-glass
)[aria-busy='true']:is(:disabled, [aria-disabled='true']) { opacity: .85; cursor: progress; }
.btn-spin { width: 1rem; height: 1rem; flex-shrink: 0; }

/* ---------- primary ---------- */
/* flat: one brand fill, a hairline top light and a small neutral shadow (no gradient, no coloured glow) */
.btn {
  --b-fg: #fff;
  --b-bg: rgb(var(--brand)); --b-bg-h: rgb(var(--brand-hover));
  --b-img: none;
  --b-hl: inset 0 1px 0 0 rgb(255 255 255 / .12);
  --b-drop: 0 1px 2px rgb(0 0 0 / .28);
  --b-ovl-h: inset 0 0 0 999px transparent;
  --b-drop-h: 0 1px 3px rgb(0 0 0 / .34);
  --b-hl-a: inset 0 2px 6px 0 rgb(0 0 0 / .26);
  --b-ovl-a: inset 0 0 0 999px rgb(0 0 0 / .08);
  --b-drop-a: 0 1px 1px rgb(0 0 0 / .2);
}

/* ---------- soft (secondary): brand-tinted surface ---------- */
.btn-soft {
  --b-img: none; --b-fg: rgb(var(--link));
  --b-bg: rgb(var(--brand) / .1); --b-bg-h: rgb(var(--brand) / .12);
  --b-ring-h: inset 0 0 0 1px rgb(var(--brand) / .35);
  --b-hl: inset 0 1px 0 0 transparent; --b-drop: 0 0 0 0 transparent; --b-ovl: inset 0 0 0 999px transparent;
  --b-ovl-h: inset 0 0 0 999px transparent; --b-drop-h: 0 0 0 0 transparent;
  --b-hl-a: inset 0 2px 6px 0 rgb(var(--ink) / .14); --b-ovl-a: inset 0 0 0 999px transparent; --b-drop-a: 0 0 0 0 transparent;
}

/* ---------- outline ---------- */
.btn-outline {
  --b-img: none; --b-fg: rgb(var(--ink));
  --b-bg: transparent; --b-bg-h: rgb(var(--soft));
  --b-hl: inset 0 1px 0 0 transparent; --b-drop: 0 0 0 0 transparent; --b-ovl: inset 0 0 0 999px transparent;
  --b-ring: inset 0 0 0 1px rgb(var(--line)); --b-ring-h: inset 0 0 0 1px rgb(var(--field) / .6);
  --b-ovl-h: inset 0 0 0 999px transparent; --b-drop-h: 0 0 0 0 transparent;
  --b-hl-a: inset 0 2px 6px 0 rgb(var(--ink) / .1); --b-ovl-a: inset 0 0 0 999px transparent; --b-drop-a: 0 0 0 0 transparent;
}

/* ---------- ghost (tertiary) ---------- */
.btn-ghost {
  --b-img: none; --b-fg: rgb(var(--mute)); --b-fg-h: rgb(var(--ink));
  --b-bg: transparent; --b-bg-h: rgb(var(--soft));
  --b-hl: inset 0 1px 0 0 transparent; --b-drop: 0 0 0 0 transparent; --b-ovl: inset 0 0 0 999px transparent; --b-ring: inset 0 0 0 1px transparent;
  --b-ovl-h: inset 0 0 0 999px transparent; --b-drop-h: 0 0 0 0 transparent;
  --b-hl-a: inset 0 2px 6px 0 rgb(var(--ink) / .1); --b-ovl-a: inset 0 0 0 999px transparent; --b-drop-a: 0 0 0 0 transparent;
}

/* ---------- status variants: soft and solid ---------- */
.btn-danger {
  --b-img: none; --b-fg: rgb(var(--bad));
  --b-bg: rgb(var(--badbg)); --b-bg-h: rgb(var(--badbg)); --b-ring-h: inset 0 0 0 1px rgb(var(--bad) / .45);
  --b-hl: inset 0 1px 0 0 transparent; --b-drop: 0 0 0 0 transparent; --b-ovl: inset 0 0 0 999px transparent;
  --b-ovl-h: inset 0 0 0 999px transparent; --b-drop-h: 0 0 0 0 transparent;
  --b-hl-a: inset 0 2px 6px 0 rgb(var(--ink) / .14); --b-ovl-a: inset 0 0 0 999px transparent; --b-drop-a: 0 0 0 0 transparent;
}
.btn-success {
  --b-img: none; --b-fg: rgb(var(--ok));
  --b-bg: rgb(var(--okbg)); --b-bg-h: rgb(var(--okbg)); --b-ring-h: inset 0 0 0 1px rgb(var(--ok) / .45);
  --b-hl: inset 0 1px 0 0 transparent; --b-drop: 0 0 0 0 transparent; --b-ovl: inset 0 0 0 999px transparent;
  --b-ovl-h: inset 0 0 0 999px transparent; --b-drop-h: 0 0 0 0 transparent;
  --b-hl-a: inset 0 2px 6px 0 rgb(var(--ink) / .14); --b-ovl-a: inset 0 0 0 999px transparent; --b-drop-a: 0 0 0 0 transparent;
}
.btn-warn {
  --b-img: none; --b-fg: rgb(var(--warn));
  --b-bg: rgb(var(--warnbg)); --b-bg-h: rgb(var(--warnbg)); --b-ring-h: inset 0 0 0 1px rgb(var(--warn) / .45);
  --b-hl: inset 0 1px 0 0 transparent; --b-drop: 0 0 0 0 transparent; --b-ovl: inset 0 0 0 999px transparent;
  --b-ovl-h: inset 0 0 0 999px transparent; --b-drop-h: 0 0 0 0 transparent;
  --b-hl-a: inset 0 2px 6px 0 rgb(var(--ink) / .14); --b-ovl-a: inset 0 0 0 999px transparent; --b-drop-a: 0 0 0 0 transparent;
}
/* solid: white text on a dark fill; hover darkens (a lighter fill would drop under 4.5:1 in the dark theme) */
:is(.btn-danger-solid, .btn-solid-danger, .btn-success-solid) {
  --b-img: none; --b-fg: #fff;
  --b-hl: inset 0 1px 0 0 rgb(255 255 255 / .2); --b-ring: inset 0 0 0 1px transparent; --b-ovl: inset 0 0 0 999px transparent;
  --b-ovl-h: inset 0 0 0 999px rgb(0 0 0 / .1);
  --b-hl-a: inset 0 2px 8px 0 rgb(0 0 0 / .3); --b-ovl-a: inset 0 0 0 999px rgb(0 0 0 / .12);
}
:is(.btn-danger-solid, .btn-solid-danger) {
  --b-bg: rgb(var(--badsolid));
  --b-drop: 0 1px 2px rgb(var(--badsolid) / .25), 0 8px 18px -8px rgb(var(--badsolid) / .5);
  --b-drop-h: 0 1px 2px rgb(var(--badsolid) / .3), 0 10px 22px -8px rgb(var(--badsolid) / .6);
  --b-drop-a: 0 1px 1px rgb(var(--badsolid) / .2);
}
.btn-success-solid {
  --b-bg: rgb(var(--oksolid));
  --b-drop: 0 1px 2px rgb(var(--oksolid) / .25), 0 8px 18px -8px rgb(var(--oksolid) / .5);
  --b-drop-h: 0 1px 2px rgb(var(--oksolid) / .3), 0 10px 22px -8px rgb(var(--oksolid) / .6);
  --b-drop-a: 0 1px 1px rgb(var(--oksolid) / .2);
}

/* ---------- text-only inline button: a link that performs an action ---------- */
:is(.btn-link, .btn-link-danger) {
  --b-h: 0px; --b-px: 0px; --b-fs: inherit; --b-gap: .35rem;
  --b-img: none; --b-bg: transparent; --b-fg: rgb(var(--link));
  position: relative; min-height: 0; padding: 0; border-radius: var(--r-sm);
  text-decoration: underline; text-decoration-color: transparent; text-underline-offset: 3px; text-decoration-thickness: 1.5px;
  font-size: inherit; box-shadow: none; vertical-align: baseline;
}
:where(.btn-link, .btn-link-danger) { display: inline; }
.btn-link-danger { --b-fg: rgb(var(--bad)); }
/* a text action inside a coloured notice: keeps the notice's text colour and stays underlined */
.btn-link-tone { --b-fg: inherit; text-decoration-color: currentColor; }
:is(.btn-link, .btn-link-danger):where(:not(:disabled, [aria-disabled='true'])):hover { text-decoration-color: currentColor; box-shadow: none; }
:is(.btn-link, .btn-link-danger):active { opacity: .75; }
/* a bigger hit area on phones without moving the text */
@media (max-width: 639px) {
  :is(.btn-link, .btn-link-danger)::before { content: ''; position: absolute; inset: -.7rem -.4rem; }
}

/* ---------- icon buttons: always carry an aria-label ---------- */
:is(.btn-icon, .btn-icon-sm, .btn-icon-ghost, .btn-icon-danger, .row-act, .btn-icon-glass, .pp-copy) {
  --b-px: 0px; --b-i: 2.5rem;
  place-items: center; min-height: 0; padding: 0; flex: none;
}
:where(.btn-icon, .btn-icon-sm, .btn-icon-ghost, .btn-icon-danger, .row-act, .btn-icon-glass, .pp-copy) {
  display: inline-grid; min-height: 0;
  width: max(var(--b-i), var(--tap, 0px)); height: max(var(--b-i), var(--tap, 0px));
}
:is(.btn-icon, .btn-icon-sm, .btn-icon-danger, .row-act) {
  --b-fg: rgb(var(--mute)); --b-fg-h: rgb(var(--link));
  --b-bg: rgb(var(--soft)); --b-bg-h: rgb(var(--brand) / .12);
}
.btn-icon-sm { --b-i: 2rem; }
.row-act { --b-i: 2.375rem; }
.btn-icon-ghost {
  --b-fg: rgb(var(--mute)); --b-fg-h: rgb(var(--ink));
  --b-bg: transparent; --b-bg-h: rgb(var(--soft));
}
.row-act-danger { --b-bg-h: rgb(var(--badbg)); --b-ring-h: inset 0 0 0 1px rgb(var(--bad) / .45); --b-fg-h: rgb(var(--bad)); }
.btn-icon-danger { --b-bg-h: rgb(var(--badbg)); --b-ring-h: inset 0 0 0 1px rgb(var(--bad) / .45); --b-fg-h: rgb(var(--bad)); }
/* a button that is also a toggle: brand tint with an inner ring */
:is(.btn-soft, .btn-outline, .btn-ghost, .btn-icon, .btn-icon-sm, .btn-icon-ghost, .row-act)[aria-pressed='true'] {
  --b-fg: rgb(var(--link)); --b-fg-h: rgb(var(--link));
  --b-bg: rgb(var(--brand) / .12); --b-bg-h: rgb(var(--brand) / .12);
  --b-ring: inset 0 0 0 1.5px rgb(var(--brand) / .55); --b-ring-h: inset 0 0 0 1.5px rgb(var(--brand) / .7);
}

/* ---------- button on a coloured status surface (toast, notice): keeps the surface's text colour ---------- */
.btn-tone {
  --b-fg: inherit; --b-fg-h: inherit; --b-bg: rgb(var(--ink) / .1); --b-bg-h: rgb(var(--ink) / .18); --b-ring: inset 0 0 0 1px transparent; --b-ring-h: inset 0 0 0 1px transparent;
  --b-img: none; --b-hl: inset 0 1px 0 0 transparent; --b-drop: 0 0 0 0 transparent; --b-drop-h: 0 0 0 0 transparent; --b-ovl-h: inset 0 0 0 999px transparent;
}

/* ---------- group: buttons joined with a 1px gap, the outer ends are round ---------- */
.btn-group { display: inline-flex; max-width: 100%; gap: 1px; vertical-align: middle; }
.btn-group > * { border-radius: 0; flex: 0 1 auto; }
.btn-group > :first-child { border-top-left-radius: 9999px; border-bottom-left-radius: 9999px; }
.btn-group > :last-child { border-top-right-radius: 9999px; border-bottom-right-radius: 9999px; }
.btn-group > :only-child { border-radius: var(--r-pill); }
.btn-group > :focus-visible { z-index: 1; }

/* ---------- split button (main action + chevron) ---------- */
.split { position: relative; display: inline-flex; max-width: 100%; gap: 1px; }
.split > .split-main { border-top-right-radius: 0; border-bottom-right-radius: 0; flex: 1 1 auto; min-width: 0; }
.split > .split-caret { border-top-left-radius: 0; border-bottom-left-radius: 0; --b-px: .7rem; }
.split > .split-caret svg { transition: transform .25s cubic-bezier(.34, 1.4, .5, 1); }
.split > .split-caret[aria-expanded='true'] svg { transform: rotate(180deg); }
.split-menu {
  position: absolute; right: 0; z-index: 40; min-width: 100%; width: max-content; max-width: min(22rem, 86vw);
  padding: .35rem; border-radius: var(--r-lg); background: rgb(var(--overlay)); border: 1px solid var(--tile-border);
  box-shadow: var(--shadow-3);
  transform-origin: top right; animation: split-in .18s cubic-bezier(.2, .9, .3, 1.2) backwards;
}
.split-menu[data-up='true'] { bottom: calc(100% + 6px); transform-origin: bottom right; }
.split-menu[data-up='false'] { top: calc(100% + 6px); }
.split-item {
  display: flex; width: 100%; flex-direction: column; align-items: flex-start; gap: 1px; text-align: left;
  border-radius: var(--r-md); padding: .55rem .8rem; font-weight: 650; color: rgb(var(--ink)); min-height: 44px; justify-content: center;
  transition: background-color .15s ease;
}
.split-item small { font-size: var(--fs-sm); font-weight: 600; color: rgb(var(--mute)); }
.split-item:hover, .split-item:focus-visible { background: rgb(var(--soft)); }
.split-item:disabled { opacity: .5; cursor: not-allowed; }
@keyframes split-in { from { opacity: 0; } to { opacity: 1; } }

/* ---------- on a gradient (update hero, banners) ---------- */
/* a context button used together with .btn must not inherit the primary gradient, glow or highlight */
:is(.btn-on-grad, .btn-ghost-on-grad, .btn-cta, .btn-glass, .btn-glass-quiet, .btn-icon-glass, .pp-copy) {
  --b-img: none; --b-hl: inset 0 1px 0 0 transparent; --b-ring: inset 0 0 0 1px transparent; --b-ovl: inset 0 0 0 999px transparent; --b-drop: 0 0 0 0 transparent;
  --b-ovl-h: inset 0 0 0 999px transparent; --b-drop-h: 0 0 0 0 transparent;
  --b-hl-a: inset 0 1px 0 0 transparent; --b-ovl-a: inset 0 0 0 999px transparent; --b-drop-a: 0 0 0 0 transparent;
}
.btn-on-grad {
  --b-fs: .875rem; --b-h: 2.375rem; --b-px: 1.1rem;
  --b-fg: #12141a; --b-bg: #fff; --b-bg-h: rgb(255 255 255 / .9); --b-bg-a: rgb(255 255 255 / .82);
  --b-drop: 0 4px 14px -6px rgb(0 0 0 / .4); --b-drop-h: 0 6px 16px -6px rgb(0 0 0 / .45); --b-drop-a: 0 1px 3px -1px rgb(0 0 0 / .3);
}
.btn-ghost-on-grad {
  --b-fs: .875rem; --b-h: 2.375rem; --b-px: 1.1rem;
  --b-fg: #fff; --b-bg: rgb(0 0 0 / .24); --b-bg-h: rgb(0 0 0 / .36); --b-bg-a: rgb(0 0 0 / .44);
  --b-ring: inset 0 0 0 1px rgb(255 255 255 / .16);
}
/* the white call-to-action on a cover */
.btn-cta {
  --b-h: 3rem; --b-px: 1.5rem; --b-fs: 1rem; --b-gap: .5rem;
  --b-fg: #12141a; --b-bg: #fff; --b-bg-h: rgb(255 255 255 / .92); --b-bg-a: rgb(255 255 255 / .84);
  --b-drop: 0 6px 18px -6px rgb(0 0 0 / .5); --b-drop-h: 0 10px 22px -6px rgb(0 0 0 / .55); --b-drop-a: 0 2px 6px -2px rgb(0 0 0 / .4);
  font-weight: 800;
}

/* ---------- on a cover: translucent white / dark glass (no backdrop-filter, see the black-square notes) ---------- */
.btn-glass {
  --b-fg: #fff; --b-bg: rgb(255 255 255 / .24); --b-bg-h: rgb(255 255 255 / .34); --b-bg-a: rgb(255 255 255 / .2);
  --b-ring: inset 0 0 0 1px rgb(255 255 255 / .3);
}
.btn-glass-quiet {
  --b-h: 2.125rem; --b-px: .9rem; --b-fs: .875rem; --b-gap: .4rem;
  --b-fg: rgb(255 255 255 / .94); --b-bg: rgb(8 10 20 / .3); --b-bg-h: rgb(8 10 20 / .46); --b-bg-a: rgb(8 10 20 / .56);
}
.btn-glass-danger { --b-fg: #ffd6d6; --b-fg-h: #fff; --b-bg-h: rgb(185 28 28 / .75); --b-bg-a: rgb(185 28 28 / .85); }
.btn-icon-glass {
  --b-i: 2.75rem; --b-fs: 1.25rem;
  --b-fg: #fff; --b-bg: rgb(255 255 255 / .24); --b-bg-h: rgb(255 255 255 / .34); --b-bg-a: rgb(255 255 255 / .2);
  --b-ring: inset 0 0 0 1px rgb(255 255 255 / .3);
}
/* a smaller glass disc (favourite star on a tile) */
.btn-icon-glass.btn-icon-sm { --b-i: 2rem; }
/* the copy button inside the passport on the banner */
.pp-copy {
  --b-i: 1.875rem; --b-fg: #fff; --b-bg: rgb(255 255 255 / .18); --b-bg-h: rgb(255 255 255 / .3); --b-bg-a: rgb(255 255 255 / .24);
}
.pp-copy { position: relative; }
.pp-copy::before { content: ''; position: absolute; inset: -.4rem; }

/* ---------- sizes ---------- */
.btn-xs { --b-h: 1.75rem; --b-px: .7rem; --b-fs: .78125rem; --b-gap: .35rem; }
.btn-sm { --b-h: 2.125rem; --b-px: .9rem; --b-fs: .875rem; --b-gap: .4rem; }
.btn-lg { --b-h: 3.125rem; --b-px: 1.5rem; --b-fs: 1rem; --b-gap: .6rem; }
:is(.btn-link, .btn-link-danger).btn-sm, :is(.btn-link, .btn-link-danger).btn-xs, :is(.btn-link, .btn-link-danger).btn-lg { --b-h: 0px; --b-px: 0px; min-height: 0; padding: 0; font-size: inherit; }
:where(.btn-block) { display: flex; width: 100%; }

/* ---------- phones: touch targets of at least 44px (everything except inline links and the passport copy) ---------- */
@media (max-width: 639px) {
  :is(
    .btn, .btn-soft, .btn-outline, .btn-ghost, .btn-danger, .btn-danger-solid, .btn-solid-danger, .btn-success, .btn-success-solid, .btn-warn,
    .btn-icon, .btn-icon-sm, .btn-icon-ghost, .btn-icon-danger, .row-act,
    .btn-on-grad, .btn-ghost-on-grad, .btn-cta, .btn-glass, .btn-glass-quiet, .btn-icon-glass
  ) { --tap: 2.75rem; }
  .btn-glass-quiet { --b-px: .7rem; }
}

/* ---------- density «Компактная»: a little lower, same shapes ---------- */
:root[data-density='compact'] :is(.btn, .btn-soft, .btn-outline, .btn-ghost, .btn-danger, .btn-danger-solid, .btn-solid-danger, .btn-success, .btn-success-solid, .btn-warn):not(.btn-xs, .btn-sm, .btn-lg) { --b-h: 2.25rem; --b-px: .95rem; }
:root[data-density='compact'] :is(.btn, .btn-soft, .btn-outline, .btn-ghost, .btn-danger, .btn-danger-solid, .btn-solid-danger, .btn-success, .btn-success-solid, .btn-warn).btn-sm { --b-h: 1.875rem; --b-px: .75rem; }

/* ---------- animated glyphs inside buttons (small, so transform is fine) ---------- */
.ico-refresh { transition: transform .55s cubic-bezier(.3, 1.3, .5, 1); }
:is(.btn, .btn-soft, .btn-outline, .btn-ghost, .btn-icon, .btn-icon-sm, .btn-icon-ghost, .btn-on-grad, .btn-ghost-on-grad, .btn-glass, .btn-glass-quiet):active .ico-refresh { transform: rotate(200deg); transition-duration: .15s; }
.ico-refresh.spinning { animation: spin .85s linear infinite; }
.ico-nudge { transition: transform .22s cubic-bezier(.3, 1.4, .5, 1); }
:is(.btn, .btn-soft, .btn-outline, .btn-ghost, .btn-on-grad, .btn-ghost-on-grad, a):hover > .ico-nudge { transform: translateX(3px); }
.ico-share { transition: transform .22s cubic-bezier(.3, 1.4, .5, 1); }
:is(.btn, .btn-soft, .btn-outline, .btn-ghost, .btn-on-grad, .btn-ghost-on-grad):hover .ico-share { transform: translate(1.5px, -1.5px); }

/* ---------- magnetic call-to-action buttons: the attribute stays, the lean is off (no translate on buttons) ---------- */
[data-magnetic] { translate: none !important; }

/* ---------- accessibility options ---------- */
html[data-contrast='high'] :is(.btn-soft, .btn-icon, .btn-icon-sm, .btn-icon-danger, .row-act, .btn-danger, .btn-success, .btn-warn) { --b-ring: inset 0 0 0 1px rgb(var(--field)); --b-ring-h: inset 0 0 0 1px rgb(var(--ink)); }
html[data-contrast='high'] :is(.btn-outline, .btn-ghost, .btn-icon-ghost) { --b-ring: inset 0 0 0 1px rgb(var(--field)); --b-ring-h: inset 0 0 0 1px rgb(var(--ink)); }
html[data-contrast='high'] :is(.btn-link, .btn-link-danger) { text-decoration-color: currentColor; }
@media (prefers-reduced-motion: reduce) {
  :is(.btn, .btn-soft, .btn-outline, .btn-ghost, .btn-danger, .btn-danger-solid, .btn-solid-danger, .btn-success, .btn-success-solid, .btn-warn, .btn-link, .btn-icon, .btn-icon-sm, .btn-icon-ghost, .btn-icon-danger, .row-act, .btn-on-grad, .btn-ghost-on-grad, .btn-cta, .btn-glass, .btn-glass-quiet, .btn-icon-glass, .pp-copy) { transition: none !important; }
  .split > .split-caret svg, .split-item { transition: none !important; }
}
html[data-motion='reduce'] :is(.btn, .btn-soft, .btn-outline, .btn-ghost, .btn-danger, .btn-danger-solid, .btn-solid-danger, .btn-success, .btn-success-solid, .btn-warn, .btn-link, .btn-icon, .btn-icon-sm, .btn-icon-ghost, .btn-icon-danger, .row-act, .btn-on-grad, .btn-ghost-on-grad, .btn-cta, .btn-glass, .btn-glass-quiet, .btn-icon-glass, .pp-copy) { transition: none !important; }

/* header search: a round icon button on phones, a pill with the label and the shortcut from md up */
.hdr-search { --b-px: 0; --b-fg: rgb(var(--mute)); --b-fg-h: rgb(var(--ink)); width: max(2.5rem, var(--tap, 0px)); height: max(2.5rem, var(--tap, 0px)); min-height: 2.5rem; padding: 0; justify-content: center; white-space: nowrap; }
.hdr-search > svg { flex: none; }
__COREGSM_EOF__
  mkdir -p "$APP_DIR/core-frontend/src/styles"
  cat > "$APP_DIR/core-frontend/src/styles/community.css" << '__COREGSM_EOF__'
/* community: the bento at the top of the main page and the «Сообщество» page */
.cm-bento { display: grid; gap: 14px; grid-template-columns: minmax(0, 1.05fr) minmax(0, 1.25fr) minmax(0, 1fr); }
@media (max-width: 1099px) { .cm-bento { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); } .cm-feed { grid-column: 1 / -1; } }
@media (max-width: 699px) { .cm-bento { grid-template-columns: minmax(0, 1fr); } }
.cm-bento > .tile { padding: 16px 18px; min-width: 0; }
.cm-k { font-size: var(--fs-xs); font-weight: 650; letter-spacing: .04em; text-transform: uppercase; color: rgb(var(--mute)); margin-bottom: 8px; }
.cm-more { display: none; }
.cm-sub { margin-top: 8px; font-size: var(--fs-sm); font-weight: 600; color: rgb(var(--mute)); }

.cm-now { position: relative; overflow: hidden; }
.cm-now::before {
  content: ''; position: absolute; inset: -40% -30% auto auto; width: 70%; aspect-ratio: 1; border-radius: var(--r-pill); pointer-events: none;
  background: radial-gradient(circle, rgb(var(--brand) / .18), transparent 70%);
}
.cm-now.is-record::before { background: radial-gradient(circle, rgb(var(--warn) / .32), transparent 70%); }
.cm-big { font-size: 64px; font-weight: 650; line-height: .95; letter-spacing: -0.045em; }
.cm-meter { margin-top: 10px; height: 8px; border-radius: var(--r-pill); background: rgb(var(--soft)); overflow: hidden; }
.cm-meter > span { display: block; height: 100%; border-radius: inherit; background: linear-gradient(90deg, rgb(var(--brand)), rgb(var(--link))); transition: width .8s cubic-bezier(.2, .8, .2, 1); }
.cm-now.is-record .cm-meter > span { background: linear-gradient(90deg, #f6b73c, #ff7a59); }
.cm-mini { margin-top: 12px; display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; }
.cm-mini > div { border-radius: var(--r-md); background: rgb(var(--soft)); padding: 6px 10px; }
.cm-mini dt { font-size: var(--fs-xs); font-weight: 650; color: rgb(var(--mute)); line-height: 1.2; }
.cm-mini dd { font-size: var(--fs-xl); font-weight: 650; font-variant-numeric: tabular-nums; }

.cm-heat { display: grid; grid-template-columns: 1.6rem repeat(24, minmax(0, 1fr)); gap: 2px; align-items: center; }
.cm-heat.is-big { gap: 3px; grid-template-columns: 2.2rem repeat(24, minmax(0, 1fr)); }
.cm-heat-d { font-size: var(--fs-xs); font-weight: 650; color: rgb(var(--mute)); }
.cm-heat-h { font-size: var(--fs-xs); font-weight: 600; color: rgb(var(--mute)); }
.cm-heat-scale { margin-top: 10px; display: inline-flex; align-items: center; gap: 4px; font-size: var(--fs-sm); font-weight: 600; color: rgb(var(--mute)); }
.cm-heat-scale i { width: 14px; height: 14px; border-radius: 4px; background: color-mix(in srgb, rgb(var(--brand)) calc(var(--a, 0) * 100%), rgb(var(--soft))); }
.cm-heat-c { height: 15px; border-radius: 3px; background: color-mix(in srgb, rgb(var(--brand)) calc(var(--a, 0) * 100%), rgb(var(--soft))); }
.cm-heat.is-big .cm-heat-c { height: clamp(14px, 2.4vw, 26px); border-radius: 5px; }

.cm-feed-list { margin-top: 2px; display: grid; grid-template-columns: minmax(0, 1fr); gap: 8px; }
.cm-feed-i { display: flex; align-items: center; gap: 10px; }
.cm-live, .cm-new { border-radius: var(--r-pill); padding: 0 7px; font-size: var(--fs-xs); font-weight: 650; }
.cm-live { background: rgb(var(--okbg)); color: rgb(var(--ok)); }
.cm-new { background: rgb(var(--link) / .14); color: rgb(var(--link)); }
.cm-feed-i { animation: cm-in .5s cubic-bezier(.2, .8, .2, 1) both; }
.cm-feed-i:nth-child(2) { animation-delay: .05s; } .cm-feed-i:nth-child(3) { animation-delay: .1s; } .cm-feed-i:nth-child(4) { animation-delay: .15s; } .cm-feed-i:nth-child(5) { animation-delay: .2s; }
@keyframes cm-in { from { opacity: 0; transform: translateY(6px); } }
@media (prefers-reduced-motion: reduce) { .cm-feed-i { animation: none; } .cm-meter > span { transition: none; } }
html[data-motion='reduce'] .cm-feed-i { animation: none; }

/* «Сообщество» page */
.cm-hero { display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: 18px; padding: 22px 24px; position: relative; overflow: hidden;
  background: radial-gradient(120% 140% at 0% 0%, rgb(var(--brand) / .14), transparent 55%), rgb(var(--card)); }
.cm-hero-n { font-size: 84px; font-weight: 650; line-height: .9; letter-spacing: -0.05em; }
@media (max-width: 639px) { .cm-hero-n { font-size: 60px; } }
.cm-hero-stats { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 8px; }
@media (max-width: 639px) { .cm-hero-stats { grid-template-columns: repeat(2, minmax(0, 1fr)); width: 100%; } }
.cm-hero-stats > div { min-width: 6.5rem; border-radius: var(--r-lg); background: rgb(var(--soft)); padding: 8px 12px; }
.cm-hero-stats dt { font-size: var(--fs-xs); font-weight: 650; color: rgb(var(--mute)); }
.cm-hero-stats dd { font-size: 24px; font-weight: 650; font-variant-numeric: tabular-nums; }
.cm-srv { display: flex; align-items: center; gap: 12px; border-radius: var(--r-lg); padding: 8px 10px; transition: background-color .15s ease; }
.cm-srv:hover { background: rgb(var(--soft)); }
.cm-srv-bar { display: block; margin-top: 5px; height: 6px; border-radius: var(--r-pill); background: rgb(var(--soft)); overflow: hidden; }
.cm-srv-bar > span { display: block; height: 100%; border-radius: inherit; background: linear-gradient(90deg, rgb(var(--brand)), rgb(var(--link))); }

/* player card */
.pl-hero { display: flex; flex-wrap: wrap; align-items: center; gap: 16px 20px; padding: 22px 24px;
  background: radial-gradient(120% 160% at 100% 0%, rgb(var(--link) / .14), transparent 55%), rgb(var(--card)); }
.pl-ava { display: grid; place-items: center; width: 72px; height: 72px; flex: none; border-radius: var(--r-xl); font-size: 32px; font-weight: 800; color: #fff;
  background: linear-gradient(135deg, rgb(var(--brand)), rgb(var(--link))); box-shadow: 0 12px 30px -12px rgb(var(--brand) / .7); }
.pl-rank { border-radius: var(--r-pill); padding: 1px 10px; font-size: var(--fs-sm); background: rgb(var(--badbg)); color: rgb(var(--bad)); }
.pl-stats { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 8px; }
@media (max-width: 639px) { .pl-stats { grid-template-columns: repeat(2, minmax(0, 1fr)); width: 100%; } }
.pl-stats > div { min-width: 6rem; border-radius: var(--r-lg); background: rgb(var(--soft)); padding: 8px 12px; }
.pl-stats > div.is-hot { background: linear-gradient(135deg, #ffe7c2, #ffd0b5); color: #5a2a00; }
.pl-stats dt { font-size: var(--fs-xs); font-weight: 650; color: rgb(var(--mute)); }
.pl-stats .is-hot dt { color: inherit; opacity: .8; }
.pl-stats dd { font-size: 22px; font-weight: 650; font-variant-numeric: tabular-nums; white-space: nowrap; }
.pl-hours { display: flex; align-items: flex-end; gap: 3px; height: 150px; }
.pl-hour { flex: 1 1 0; height: 100%; display: flex; flex-direction: column; justify-content: flex-end; align-items: center; gap: 4px; }
.pl-hour i { display: block; width: 100%; min-height: 2px; border-radius: 5px 5px 2px 2px; background: linear-gradient(180deg, rgb(var(--link)), rgb(var(--brand))); }
.pl-hour b { height: 14px; font-size: var(--fs-xs); font-weight: 600; color: rgb(var(--mute)); }

/* seasons */
.cm-season { background: radial-gradient(120% 140% at 100% 0%, rgb(var(--warn) / .12), transparent 55%), rgb(var(--card)); }
.cm-fame { display: grid; gap: 10px; grid-template-columns: repeat(auto-fill, minmax(min(100%, 15rem), 1fr)); }
.cm-fame-i { border-radius: var(--r-lg); background: rgb(var(--soft)); padding: 12px 14px; }

/* phones: only «Сейчас играют», compact; when and who arrived are one tap away on «Сообщество» */
@media (max-width: 699px) {
  .cm-bento { grid-template-columns: minmax(0, 1fr); }
  .cm-bento .cm-when, .cm-bento .cm-feed { display: none; }
  .cm-bento > .tile { padding: 12px 14px; }
  .cm-big { font-size: 44px; }
  .cm-mini dd { font-size: var(--fs-base); }
  .cm-more { display: block; margin-top: 8px; font-size: var(--fs-sm); font-weight: 650; color: rgb(var(--link)); }
}

/* ---------- «Сообщество», pass 2 ---------- */
.cm-refresh { display: inline-flex; align-items: center; gap: 8px; padding: 4px 12px; border-radius: var(--r-pill); background: rgb(var(--soft)); font-size: var(--fs-xs); font-weight: 800; color: rgb(var(--mute)); transition: background-color .15s ease; }
.cm-refresh:hover { background: rgb(var(--soft) / .7); color: rgb(var(--ink)); }
.cm-refresh[aria-busy='true'] .live-dot { animation: cm-beat .6s linear infinite; }
@keyframes cm-beat { 50% { transform: scale(1.6); opacity: .5; } }

/* strip of chips under the title */
.cm-nav { position: sticky; top: 4.75rem; z-index: 20; display: flex; gap: 4px; width: max-content; max-width: 100%; margin: 0; padding: 5px; overflow-x: auto; scrollbar-width: none; border-radius: var(--r-pill); background: rgb(var(--card) / .86); box-shadow: inset 0 0 0 1px rgb(var(--line)), var(--shadow-1); }
.cm-nav::-webkit-scrollbar { display: none; }
.cm-nav-i { flex: none; padding: 6px 14px; border-radius: var(--r-pill); background: transparent; font-size: var(--fs-sm); font-weight: 800; color: rgb(var(--mute)); transition: background-color .15s ease, color .15s ease; }
.cm-nav-i:hover { color: rgb(var(--ink)); }
.cm-nav-i[aria-current='true'] { background: rgb(var(--brand)); color: #fff; }
[id^='cm-'] { scroll-margin-top: 64px; }

/* greeting, delta chips */
.cm-greet { display: flex; align-items: center; gap: 12px; padding: 12px 16px; }
.cm-delta { display: inline-flex; align-items: baseline; gap: 3px; font-size: var(--fs-xs); font-weight: 800; font-variant-numeric: tabular-nums; color: rgb(var(--mute)); }
.cm-delta.up { color: rgb(var(--ok)); }
.cm-delta.down { color: rgb(var(--bad)); }
.cm-hero-main { flex: 1 1 22rem; min-width: 0; }
.cm-hero-stats > div { display: flex; flex-direction: column; align-items: flex-start; }
.cm-stat-link { font: inherit; color: inherit; text-decoration: underline dotted; text-underline-offset: 4px; }
.cm-stat-link:hover { color: rgb(var(--link)); }

/* avatars of players */
.cm-ava { position: relative; display: inline-grid; place-items: center; flex: none; border-radius: 30%; font-weight: 800; color: #fff; background: linear-gradient(135deg, hsl(var(--h) 62% 48%), hsl(calc(var(--h) + 40) 62% 38%)); }
.cm-ava-img { position: absolute; inset: 0; border-radius: inherit; }
.cm-ava-on { position: absolute; right: -2px; bottom: -2px; width: 10px; height: 10px; border-radius: 50%; background: rgb(var(--ok)); box-shadow: 0 0 0 2px rgb(var(--card)); }
.cm-ava-game { position: absolute; right: -5px; top: -5px; line-height: 0; border-radius: 50%; box-shadow: 0 0 0 2px rgb(var(--card)); overflow: hidden; }

/* charts with a cursor */
.cm-chart { position: relative; height: 64px; margin-top: 12px; touch-action: pan-y; cursor: crosshair; }
.cm-chart svg { display: block; width: 100%; height: 100%; overflow: visible; }
.cm-chart-hero { height: 56px; }
.cm-chart-day { height: 88px; margin-top: 10px; }
.cm-chart-mark { position: absolute; top: 0; bottom: 0; width: 0; border-left: 2px dashed currentColor; opacity: .5; pointer-events: none; }
.cm-chart-cur { position: absolute; top: 0; bottom: 0; width: 1px; background: currentColor; opacity: .5; pointer-events: none; }
.cm-chart-tip { position: absolute; top: -4px; transform: translate(-50%, -100%); padding: 2px 8px; border-radius: var(--r-md); background: rgb(var(--overlay)); color: rgb(var(--ink)); font-size: var(--fs-xs); font-weight: 700; white-space: nowrap; box-shadow: var(--shadow-2), inset 0 0 0 1px rgb(var(--line)); pointer-events: none; z-index: 2; }
.cm-chart-ticks { display: flex; justify-content: space-between; margin-top: 4px; font-size: var(--fs-2xs); font-weight: 700; color: rgb(var(--mute)); }
.cm-days { display: flex; flex-wrap: wrap; gap: 4px; margin-top: 16px; }
.cm-heat-c.is-now { outline: 2px solid rgb(var(--ink)); outline-offset: 1px; }
.cm-best { display: flex; align-items: center; gap: 8px; margin-bottom: 12px; padding: 8px 12px; border-radius: var(--r-lg); background: rgb(var(--soft)); font-size: var(--fs-md); font-weight: 650; }
.cm-best.is-now { background: rgb(var(--okbg)); color: rgb(var(--ok)); }

/* games share, the hot server */
.cm-share { display: flex; height: 14px; border-radius: var(--r-pill); overflow: hidden; background: rgb(var(--soft)); gap: 2px; }
.cm-share > span { min-width: 4px; }
.cm-share-legend { display: grid; gap: 6px; margin-top: 12px; }
.cm-share-legend li { display: flex; align-items: center; gap: 8px; font-size: var(--fs-md); }
.cm-share-legend i { width: 10px; height: 10px; border-radius: 3px; flex: none; }

/* top: podium, search, moves, my row */
.cm-search { display: flex; gap: 8px; margin-bottom: 14px; }
.cm-search .input { flex: 1; min-width: 0; }
.cm-podium { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); align-items: end; gap: 10px; margin-bottom: 14px; }
.cm-pod { display: flex; flex-direction: column; align-items: center; gap: 4px; padding: 12px 8px; border-radius: var(--r-lg); background: rgb(var(--soft)); text-align: center; min-width: 0; transition: transform .15s ease; }
.cm-pod:hover { transform: translateY(-2px); }
.cm-pod.is-1 { padding-top: 20px; padding-bottom: 18px; background: linear-gradient(180deg, rgb(var(--warn) / .22), rgb(var(--soft))); }
.cm-move { display: inline-flex; align-items: baseline; gap: 2px; padding: 0 6px; border-radius: var(--r-pill); background: rgb(var(--soft)); font-size: var(--fs-2xs); font-weight: 800; line-height: 18px; color: rgb(var(--mute)); flex: none; }
.cm-move.up { color: rgb(var(--ok)); background: rgb(var(--okbg)); }
.cm-move.down { color: rgb(var(--bad)); background: rgb(var(--badbg)); }
.cm-move.new { color: rgb(var(--link)); background: rgb(var(--link) / .14); }
.an-top > li { align-items: center; gap: 10px; }
.an-top > li.is-me { border-radius: var(--r-lg); background: rgb(var(--brand) / .1); box-shadow: inset 0 0 0 1px rgb(var(--brand) / .35); }
.cm-me { margin-bottom: 10px; padding: 6px 12px; border-radius: var(--r-pill); display: inline-block; background: rgb(var(--brand) / .12); font-size: var(--fs-sm); font-weight: 800; }
.cm-me.is-out { background: rgb(var(--soft)); color: rgb(var(--mute)); }

/* feed groups, servers, gallery */
.cm-feed-group + .cm-feed-group { margin-top: 14px; }
.cm-feed-h { margin-bottom: 8px; font-size: var(--fs-xs); font-weight: 800; letter-spacing: .04em; text-transform: uppercase; color: rgb(var(--mute)); }
.cm-feed-i { align-items: center; }
.cm-chips { display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 12px; }
.cm-chip { display: inline-flex; align-items: center; gap: 6px; padding: 4px 12px; border-radius: var(--r-pill); background: rgb(var(--soft)); font-size: var(--fs-sm); font-weight: 800; color: rgb(var(--mute)); }
.cm-chip i { width: 8px; height: 8px; border-radius: 50%; }
.cm-chip[aria-pressed='true'] { background: rgb(var(--brand)); color: #fff; }
.cm-srv.is-off { opacity: .6; }
.cm-srv-spark { flex: none; }
.cm-gal { display: grid; gap: 8px; grid-template-columns: repeat(2, minmax(0, 1fr)); }
.cm-gal li { min-width: 0; aspect-ratio: 16 / 10; }
.cm-gal .gl-shot { height: 100%; }
.cm-gal .gl-shot img { height: 100%; object-fit: cover; }
.cm-gal li.is-big { grid-column: 1 / -1; aspect-ratio: 16 / 8; }
@media (min-width: 720px) {
  .cm-gal { grid-template-columns: repeat(4, minmax(0, 1fr)); }
  .cm-gal li.is-big { grid-column: span 2; grid-row: span 2; aspect-ratio: auto; }
}
.pl-ava { overflow: hidden; }
.pl-ava-img { width: 100% !important; height: 100% !important; border-radius: inherit; }

/* ---------- the community page «Bento»: a mosaic of tiles of different sizes (one column below lg) ---------- */
.cm-bento { display: grid; gap: 1.25rem; grid-template-columns: minmax(0, 1fr); }
.cm-bento > * { min-width: 0; }
.cm-bento > div > .tile, .cm-bento > div > section.tile { height: 100%; }
@media (min-width: 1024px) {
  .cm-bento { grid-template-columns: repeat(12, minmax(0, 1fr)); }
  .cm-bento > .cm-hero, .cm-bento > .b-wide { grid-column: 1 / -1; }
  .cm-bento > .b-hot { grid-column: span 5; }
  .cm-bento > .b-games { grid-column: span 7; }
  .cm-bento > .b-when { grid-column: span 7; }
  .cm-bento > .b-top { grid-column: span 5; }
  .cm-bento > .b-feed { grid-column: span 7; }
  .cm-bento > .b-gal { grid-column: span 5; }
}
/* every tile has its own quiet tint, like the tiles of a dashboard (the colours are soft, so both themes read well) */
.cm-bento > .cm-hero { background: linear-gradient(160deg, rgb(var(--brand) / .2), rgb(var(--brand) / .05) 70%), rgb(var(--card)); }
.cm-bento > .b-hot > .tile { background: linear-gradient(160deg, rgb(45 212 191 / .13), transparent 70%), rgb(var(--card)); }
.cm-bento > .b-games > .tile { background: linear-gradient(160deg, rgb(139 92 246 / .12), transparent 70%), rgb(var(--card)); }
.cm-bento > .b-when > .tile { background: linear-gradient(160deg, rgb(34 197 94 / .1), transparent 70%), rgb(var(--card)); }
.cm-bento > .b-top > .tile { background: linear-gradient(160deg, rgb(250 204 21 / .11), transparent 70%), rgb(var(--card)); }
.cm-bento > .b-feed > .tile { background: linear-gradient(160deg, rgb(244 114 182 / .1), transparent 70%), rgb(var(--card)); }
.cm-bento > .b-gal > .tile, .cm-bento > .b-gal > section { background: linear-gradient(160deg, rgb(249 115 22 / .11), transparent 70%), rgb(var(--card)); }

/* the strip of sections: a gap under it (the sticky capsule has no margin of its own), the icons in front of the labels */
.cm-nav { margin-bottom: 1.25rem; }
.cm-nav-i { display: inline-flex; align-items: center; gap: 7px; }
.cm-nav-i > svg { flex: none; opacity: .85; }
__COREGSM_EOF__
  mkdir -p "$APP_DIR/core-frontend/src/styles"
  cat > "$APP_DIR/core-frontend/src/styles/detail.css" << '__COREGSM_EOF__'
/* detail: styles owned by the server page workstream (see main.tsx)
   Rules: no transform transitions on blocks, no infinite animations, entrance = fill-mode backwards,
   no outline styling (focus = box-shadow ring), no backdrop-filter / will-change. */

/* ---------- chart ---------- */
.hc-fade { animation: hc-fade .6s ease-out backwards; }
@keyframes hc-fade { from { opacity: 0; } to { opacity: 1; } }
.hc-wrap { outline: 0; }
.hc-wrap:focus, .hc-wrap:focus-visible { outline: 0; }
.hc-wrap:focus-visible { box-shadow: 0 0 0 3px rgb(var(--brand) / 0.55); }
.hc-legend { display: flex; flex-wrap: wrap; gap: 4px 14px; margin-top: 8px; font-size: var(--fs-xs); font-weight: 600; color: rgb(var(--mute)); }
.hc-legend li { display: inline-flex; align-items: center; gap: 6px; }
.hc-dot { display: inline-grid; place-items: center; width: 16px; height: 16px; border-radius: var(--r-pill); }

/* ---------- passport (inside the dark banner) ---------- */
.pp {
  display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 1px; overflow: hidden;
  border-radius: var(--r-lg); background: rgba(255, 255, 255, 0.16); box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.18);
}
.pp-i { min-width: 0; padding: 9px 12px; background: rgba(0, 0, 0, 0.26); }
.pp-i.wide { grid-column: 1 / -1; }
.pp-k { font-size: var(--fs-xs); font-weight: 650; letter-spacing: .04em; text-transform: uppercase; color: rgba(255, 255, 255, 0.88); }
.pp-v { margin-top: 1px; display: flex; align-items: center; gap: 8px; min-width: 0; font-size: var(--fs-md); font-weight: 650; color: #fff; }
.pp-v > span, .pp-v > a, .pp-v > code { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.pp-v code { font-family: var(--font-mono); font-size: var(--fs-sm); font-weight: 600; }
.pp-v a { text-decoration: underline; text-underline-offset: 3px; }
/* the ping's quality: white text (readable on any cover) and a coloured light in front of it */
.pp-v > :is(.pp-tone-ok, .pp-tone-warn, .pp-tone-bad) { display: inline-flex; align-items: center; gap: 7px; color: #fff; white-space: normal; overflow: visible; }
:is(.pp-tone-ok, .pp-tone-warn, .pp-tone-bad)::before { content: ''; flex: none; width: 9px; height: 9px; border-radius: var(--r-pill); background: var(--tone); box-shadow: 0 0 0 3px rgb(0 0 0 / .25), 0 0 10px var(--tone); }
.pp-tone-ok { --tone: #4ade80; }
.pp-tone-warn { --tone: #facc15; }
.pp-tone-bad { --tone: #f87171; }
@media (min-width: 640px) { .pp { grid-template-columns: repeat(3, minmax(0, 1fr)); } .pp-i.wide { grid-column: span 2; } }
@media (min-width: 1024px) { .pp { grid-template-columns: repeat(4, minmax(0, 1fr)); } }

/* ---------- players ---------- */
.pl-row {
  display: flex; width: 100%; min-width: 0; align-items: center; gap: 12px; padding: 8px 6px; border-radius: var(--r-md);
  text-align: left; background: transparent; transition: background-color .15s ease;
}
.pl-row:hover { background: rgb(var(--soft)); }
.pl-row:focus, .pl-row:focus-visible { outline: 0; }
.pl-row:focus-visible { box-shadow: 0 0 0 3px rgb(var(--brand) / 0.55); }
.pl-chev { flex: none; color: rgb(var(--mute)); }
.pl-chev[data-open='true'] { transform: rotate(180deg); }
.pl-more {
  display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px 16px; margin: 2px 6px 10px 54px;
  padding: 12px 14px; border-radius: var(--r-md); background: rgb(var(--soft)); animation: dt-in .25s ease-out backwards;
}
.pl-more dt { font-size: var(--fs-xs); font-weight: 650; color: rgb(var(--mute)); }
.pl-more dd { font-size: var(--fs-md); font-weight: 650; }
@keyframes dt-in { from { opacity: 0; } to { opacity: 1; } }
@media (max-width: 480px) { .pl-more { margin-left: 6px; } }

/* ---------- connect ---------- */
.cn-big {
  display: flex; min-width: 0; flex-wrap: wrap; align-items: center; gap: 10px; padding: 12px; border-radius: var(--r-lg);
  background: rgb(var(--soft));
}
.cn-big code {
  min-width: 0; flex: 1 1 200px; overflow-x: auto; white-space: nowrap; padding: 10px 12px; border-radius: var(--r-md);
  background: rgb(var(--card)); font-family: var(--font-mono); font-size: var(--fs-base); font-weight: 600;
}
.cn-step { display: flex; gap: 12px; }
.cn-num {
  display: grid; flex: none; place-items: center; width: 30px; height: 30px; border-radius: var(--r-pill);
  background: rgb(var(--link)); color: #fff; font-size: var(--fs-md); font-weight: 650;
}
.cn-qr { display: block; margin: 0 auto; border-radius: var(--r-lg); background: #fff; padding: 12px; width: min(100%, 260px); height: auto; }
.cn-qr svg { display: block; width: 100%; height: auto; }

@media (prefers-reduced-motion: reduce) {
  .hc-fade, .pl-more { animation: none !important; }
  .pl-row { transition: none !important; }
}

/* ======================================================================
   server page redesign: hero, compact passport, metrics, chart header,
   «Ещё» menu, players / events / connect tabs, phone bar, game accent
   ====================================================================== */

/* ---------- tabs: icons, and the active pill tinted with the game accent (glows a little) ---------- */
.srv-page { --srv-acc: var(--srv-accent, rgb(var(--brand))); }
.srv-tabs { padding: 4px; gap: 2px; box-shadow: inset 0 0 0 1px rgb(var(--line)); }
.srv-tabs > .seg-item { padding: .5rem 1rem .5rem .85rem; }
.srv-tab-i { flex: none; opacity: .65; transition: transform .25s cubic-bezier(.34, 1.56, .64, 1), opacity .15s ease, color .15s ease; }
.srv-tabs > .seg-item:hover .srv-tab-i { opacity: 1; transform: translateY(-1px) scale(1.08); }
.srv-tabs > .seg-item.on .srv-tab-i { opacity: 1; color: var(--srv-acc); }
.srv-tabs.seg[data-ind]::before,
.srv-tabs:not([data-ind]) > .seg-item.on {
  background: linear-gradient(180deg, color-mix(in srgb, var(--srv-acc) 24%, rgb(var(--seg-on))), color-mix(in srgb, var(--srv-acc) 9%, rgb(var(--seg-on))));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--srv-acc) 50%, transparent), inset 0 1px 0 rgb(255 255 255 / .1), 0 8px 20px -10px var(--srv-acc);
}
.srv-tabs > .seg-item.on .tab-count { background: color-mix(in srgb, var(--srv-acc) 30%, transparent); color: rgb(var(--ink)); }
@media (prefers-reduced-motion: reduce) { .srv-tab-i { transition: none; } }

/* tabs as scrollable chips with snapping on phones */
@media (max-width: 639px) {
  .srv-tabs { width: 100%; gap: 8px; padding: 0; background: transparent; box-shadow: none; scroll-snap-type: x proximity; scroll-padding-inline: 12px; }
  .srv-tabs.seg[data-ind]::before { display: none; }
  .srv-tabs > .seg-item { flex: none; scroll-snap-align: center; background: rgb(var(--soft)); }
  .srv-tabs > .seg-item.on, .srv-tabs.seg[data-ind] > .seg-item.on {
    background: linear-gradient(180deg, color-mix(in srgb, var(--srv-acc) 24%, rgb(var(--seg-on))), color-mix(in srgb, var(--srv-acc) 9%, rgb(var(--seg-on))));
    box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--srv-acc) 50%, transparent);
  }
  .srv-page { padding-bottom: 4.5rem; }
}

/* ---------- hero (inside the banner) ---------- */
.srv-hero {
  margin-top: 14px; padding: 14px 16px; border-radius: var(--r-lg); background: rgba(0, 0, 0, 0.1);
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.12); backdrop-filter: blur(6px);
}
.srv-hero-top { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 8px 12px; }
.srv-hero-count { display: flex; flex-wrap: wrap; align-items: baseline; gap: 2px 8px; min-width: 0; }
.srv-hero-n { font-size: 44px; font-weight: 800; line-height: 1; letter-spacing: -0.03em; font-variant-numeric: tabular-nums; color: #fff; }
.srv-hero-max { font-size: 22px; font-weight: 650; color: rgba(255, 255, 255, 0.82); font-variant-numeric: tabular-nums; }
.srv-hero-unit { font-size: var(--fs-base); font-weight: 650; color: rgba(255, 255, 255, 0.88); }
.srv-hero-sub {
  display: inline-flex; align-items: center; gap: 8px; padding: 8px 14px; border-radius: var(--r-pill); font-size: var(--fs-md); font-weight: 650;
  background: rgba(255, 255, 255, 0.16); color: #fff;
}
/* no number while the server is down: a thin, quiet dash instead of a heavy white block */
.srv-hero-none { font-weight: 300; opacity: .55; }
@media (min-width: 640px) { .srv-hero-n { font-size: 56px; } .srv-hero-max { font-size: 26px; } }

/* ---------- compact passport ---------- */
/* up to five facts, only those the server reports: the cells share the row whatever their number */
.pp.pp-main { grid-template-columns: repeat(auto-fit, minmax(min(100%, 8.5rem), 1fr)); }
.pp-more-btn {
  display: inline-flex; align-items: center; gap: 6px; margin-top: 8px; min-height: 36px; padding: 0 14px; border-radius: var(--r-pill);
  font-size: var(--fs-sm); font-weight: 650; color: rgba(255, 255, 255, 0.95); background: rgba(8, 10, 20, 0.22); transition: background-color .15s ease;
}
.pp-more-btn:hover { background: rgba(8, 10, 20, 0.4); }
.pp-more-btn:focus, .pp-more-btn:focus-visible { outline: 0 !important; }
.pp-more-btn:focus-visible { box-shadow: 0 0 0 3px rgba(255, 255, 255, 0.6); }
.pp-more-chev[data-open='true'] { transform: rotate(180deg); }
@media (max-width: 639px) { .pp-more-btn { min-height: 44px; } }

/* ---------- metrics row ---------- */
.srv-metrics { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; }
.srv-metrics > .srv-metric:last-child:nth-child(odd) { grid-column: 1 / -1; }
@media (min-width: 560px) { .srv-metrics { grid-template-columns: repeat(3, minmax(0, 1fr)); } .srv-metrics.has-4 { grid-template-columns: repeat(4, minmax(0, 1fr)); } .srv-metrics > .srv-metric:last-child:nth-child(odd) { grid-column: auto; } }
.srv-metric { min-width: 0; padding: 10px 12px; border-radius: var(--r-lg); background: rgb(var(--soft)); }
.srv-metric-v { margin-top: 2px; font-size: 22px; font-weight: 800; line-height: 1.15; letter-spacing: -0.02em; font-variant-numeric: tabular-nums; }
.srv-metric-of { font-size: var(--fs-md); font-weight: 650; color: rgb(var(--mute)); }
.srv-metric-bar { height: 4px; margin: 7px 0 5px; border-radius: var(--r-pill); background: rgb(var(--line)); overflow: hidden; }
.srv-metric-bar > i { display: block; height: 100%; border-radius: var(--r-pill); background: linear-gradient(90deg, rgb(var(--brand)), rgb(var(--link))); }
.srv-metric-bar > i.is-good { background: rgb(var(--ok-fill)); }
.srv-metric-bar > i.is-warm { background: rgb(var(--warn-fill)); }
.srv-metric-bar > i.is-hot { background: rgb(var(--bad-fill)); }
.srv-metric-h { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: var(--fs-xs); font-weight: 600; color: rgb(var(--mute)); }

/* ---------- chart header ---------- */
.srv-chart-bar { display: flex; flex-wrap: wrap; align-items: center; justify-content: flex-end; gap: 8px; margin-bottom: 10px; }
.hc-head { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 6px 12px; margin-bottom: 8px; font-size: var(--fs-sm); }
.hc-cap { font-weight: 650; color: rgb(var(--mute)); }
.hc-notes { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 8px; }
.hc-note, .hc-now {
  display: inline-flex; align-items: center; gap: 6px; padding: 3px 10px; border-radius: var(--r-pill); font-weight: 650;
  background: rgb(var(--soft)); color: rgb(var(--ink));
}
.hc-now { box-shadow: inset 0 0 0 1.5px var(--hc, rgb(var(--brand))); }
.hc-now > i { width: 8px; height: 8px; border-radius: var(--r-pill); background: var(--hc, rgb(var(--brand))); }

/* ---------- «Ещё» menu ---------- */
.srv-more { position: relative; display: inline-block; }
.srv-more > .btn-glass { width: 100%; }
.srv-more-pop {
  z-index: 40; min-width: 230px; max-width: min(320px, calc(100vw - 32px)); padding: 6px;
  border-radius: var(--r-lg); background: rgb(var(--card)); color: rgb(var(--ink)); border: 1px solid var(--tile-border);
  box-shadow: 0 16px 40px -12px rgba(0, 0, 0, 0.45); animation: dt-in .15s ease-out backwards;
}
.srv-more-item {
  position: relative; display: flex; align-items: center; gap: 10px; width: 100%; min-height: 44px; padding: 8px 12px; border-radius: var(--r-md);
  font-size: var(--fs-base); font-weight: 650; text-align: left; background: transparent; color: inherit; transition: background-color .12s ease;
}
.srv-more-item:hover, .srv-more-item:focus { background: rgb(var(--soft)); }
.srv-more-item:focus, .srv-more-item:focus-visible { outline: 0 !important; }
.srv-more-item:focus { box-shadow: inset 0 0 0 2px rgb(var(--brand) / 0.55); }
.srv-more-item:disabled { opacity: .55; }
.srv-more-item.is-danger { color: rgb(var(--bad)); }
.srv-more-item.has-divider { margin-top: 7px; }
.srv-more-item.has-divider::before { content: ''; position: absolute; left: 10px; right: 10px; top: -4px; height: 1px; background: rgb(var(--line)); }
.srv-more-ico { display: inline-grid; place-items: center; width: 20px; flex: none; color: rgb(var(--mute)); }

/* ---------- players ---------- */
.pl-sticky {
  position: sticky; z-index: 5; margin: -4px -6px 8px; padding: 8px 6px 10px; background: rgb(var(--card));
  border-bottom: 1px solid rgb(var(--line));
}
.pl-count { margin-bottom: 8px; font-size: var(--fs-md); font-weight: 600; color: rgb(var(--mute)); }
.pl-count b { font-weight: 800; color: rgb(var(--ink)); }
.srv-chipset { display: flex; flex-wrap: wrap; gap: 6px; }

/* ---------- connect wizard ---------- */
.cn-wizard { list-style: none; margin: 0; padding: 0; display: grid; gap: 22px; }
.cn-step-big { gap: 14px; }
.cn-step-big > .cn-num { width: 36px; height: 36px; font-size: var(--fs-lg); }
.cn-h { font-size: var(--fs-xl); font-weight: 800; line-height: 1.3; padding-top: 5px; }
.cn-sub { margin: 0; padding-left: 18px; display: grid; gap: 6px; list-style: disc; font-weight: 600; line-height: 1.4; }
.cn-sub li::marker { color: rgb(var(--mute)); }
.cn-big code { font-size: var(--fs-lg); }
.cn-part { display: inline; padding: 2px 4px; margin-right: 6px; font-weight: 650; text-decoration: underline; text-underline-offset: 3px; background: transparent; color: rgb(var(--link)); }
.cn-part code { font-family: var(--font-mono); font-weight: 600; }
.cn-part:focus, .cn-part:focus-visible { outline: 0 !important; }
.cn-part:focus-visible { box-shadow: 0 0 0 3px rgb(var(--brand) / 0.55); border-radius: 6px; }
@media (max-width: 639px) { .cn-qr { width: min(100%, 320px); } }

/* ---------- phone action bar (solid, no blur; sits above the bottom navigation of the app) ---------- */
.srv-mbar { display: none; }
@media (max-width: 639px) {
  /* a floating bar above the bottom navigation, only while the banner's own buttons are out of sight */
  .srv-mbar {
    display: flex; gap: 8px; position: fixed; left: 12px; right: 12px; z-index: 30; padding: 8px;
    bottom: calc(5.75rem + env(safe-area-inset-bottom, 0px));
    border-radius: var(--r-xl); background: rgb(var(--card) / .92); box-shadow: 0 0 0 1px rgb(var(--line)), 0 14px 34px -14px rgb(0 0 0 / .55);
    -webkit-backdrop-filter: blur(14px); backdrop-filter: blur(14px);
    opacity: 0; transform: translateY(12px); pointer-events: none; transition: opacity .2s ease, transform .25s cubic-bezier(.2, .8, .2, 1);
  }
  .srv-mbar.is-on { opacity: 1; transform: none; pointer-events: auto; }
  .srv-mbar > * { flex: 1 1 0; min-width: 0; min-height: 44px; }
  /* the banner's buttons on a phone: one line each, the main one across the whole row */
  .srv-banner :is(.btn-cta, .btn-glass) { white-space: nowrap; }
}
@media (max-width: 639px) and (prefers-reduced-motion: reduce) { .srv-mbar { transition: none; } }

@media (prefers-reduced-motion: reduce) {
  .srv-more-pop { animation: none !important; }
  .srv-more-item, .pp-more-btn { transition: none !important; }
}
html[data-motion='reduce'] .srv-more-pop { animation: none !important; }
html[data-motion='reduce'] :is(.srv-more-item, .pp-more-btn) { transition: none !important; }

/* ---------- history chart: tools, the usual band, the ping axis, zoom ---------- */
.hc-tools { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 8px; margin-bottom: 8px; }
.hc-chip {
  display: inline-flex; align-items: center; gap: 7px; min-height: 30px; padding: 3px 12px; border-radius: var(--r-pill);
  font-size: var(--fs-sm); font-weight: 650; color: rgb(var(--mute)); background: rgb(var(--soft)); transition: color .15s ease, background-color .15s ease, box-shadow .15s ease;
}
.hc-chip[aria-pressed='true'] { color: rgb(var(--ink)); background: rgb(var(--card)); box-shadow: 0 0 0 1.5px rgb(var(--line)), 0 1px 2px rgba(20, 24, 40, .06); }
.hc-chip.is-zoom { color: rgb(var(--link)); background: rgb(var(--link) / .1); }
.hc-chip i { width: 16px; height: 8px; border-radius: 4px; }
.hc-chip-usual { background: repeating-linear-gradient(90deg, rgb(var(--mute) / .6) 0 4px, transparent 4px 7px), rgb(var(--mute) / .15); }
.hc-chip-ping { background: rgb(var(--link)); height: 3px !important; }
.hc-tip { font-size: var(--fs-xs); font-weight: 600; color: rgb(var(--mute)); }
@media (hover: none) { .hc-tip { display: none; } }
.hc-usual path:first-child { fill: rgb(var(--mute) / .12); }
.hc-usual path:last-child { stroke: rgb(var(--mute) / .55); stroke-width: 1.5; }
.hc-ping { stroke: rgb(var(--link)); stroke-width: 1.6; opacity: .85; }
.hc-ping-tick { fill: rgb(var(--link)); }
.hc-drag { fill: var(--srv-accent, rgb(var(--brand))); fill-opacity: .12; stroke: var(--srv-accent, rgb(var(--brand))); stroke-opacity: .5; stroke-dasharray: 4 3; }
.hc-over { margin-top: 8px; border-radius: var(--r-md); overflow: hidden; background: rgb(var(--soft)); }
.hc-over-dim { fill: rgb(var(--card)); fill-opacity: .55; }
.hc-over-win { fill: none; stroke: var(--srv-accent, rgb(var(--brand))); stroke-width: 2; rx: 6; }

/* ---------- reviews ---------- */
.rv { display: grid; gap: 14px; }
.rv-score { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 22px; align-items: center; border-radius: var(--r-lg); background: rgb(var(--soft)); padding: 14px 18px; }
.rv-avg { font-size: 44px; font-weight: 650; line-height: 1; letter-spacing: -0.03em; }
.rv-stars { display: inline-flex; gap: 1px; color: rgb(var(--line)); line-height: 1; }
.rv-stars .on { color: #f6b73c; }
.rv-dist { display: grid; gap: 4px; font-size: var(--fs-sm); font-weight: 650; color: rgb(var(--mute)); }
.rv-dist li { display: flex; align-items: center; gap: 8px; }
.rv-dist-bar { flex: 1; height: 8px; border-radius: var(--r-pill); background: rgb(var(--card)); overflow: hidden; }
.rv-dist-bar > span { display: block; height: 100%; border-radius: inherit; background: linear-gradient(90deg, #f6b73c, #ff9a3c); }
.rv-pick { display: inline-flex; gap: 2px; }
.rv-pick button { font-size: 26px; line-height: 1; color: rgb(var(--line)); transition: transform .15s cubic-bezier(.34, 1.56, .64, 1), color .1s ease; }
.rv-pick button.on { color: #f6b73c; }
.rv-pick button:hover { transform: scale(1.18); }
.rv-form { display: grid; gap: 10px; border-radius: var(--r-lg); padding: 14px; box-shadow: inset 0 0 0 1px rgb(var(--line)); }
.rv-item { border-radius: var(--r-lg); background: rgb(var(--soft)); padding: 10px 14px; }
.rv-item.is-mine { box-shadow: inset 0 0 0 1px rgb(var(--brand) / .4); }
@media (prefers-reduced-motion: reduce) { .rv-pick button { transition: none; } }

/* ---------- availability from several places ---------- */
.pr-points { display: grid; gap: 8px; grid-template-columns: repeat(auto-fill, minmax(min(100%, 13rem), 1fr)); }
.pr-point { display: flex; align-items: center; gap: 10px; border-radius: var(--r-lg); background: rgb(var(--soft)); padding: 10px 12px; }
.pr-dot { width: 10px; height: 10px; flex: none; border-radius: var(--r-pill); background: rgb(var(--mute)); }
.pr-dot.is-up { background: rgb(var(--ok)); box-shadow: 0 0 0 4px rgb(var(--ok) / .18); }
.pr-dot.is-down { background: rgb(var(--bad)); box-shadow: 0 0 0 4px rgb(var(--bad) / .18); }

/* ---------- the server banner: a scrim, the counter and the fill bar in one row, the address on the copy button ---------- */
.srv-scrim { background: linear-gradient(90deg, rgb(8 10 20 / .5) 0%, rgb(8 10 20 / .22) 62%, rgb(8 10 20 / .08) 100%), linear-gradient(180deg, transparent 55%, rgb(8 10 20 / .3)); }
@media (min-width: 640px) {
  .srv-hero { display: grid; grid-template-columns: auto minmax(0, 1fr); column-gap: 28px; align-items: center; }
  .srv-hero > .srv-hero-top { grid-column: 1; }
  .srv-hero > .srv-hero-bar { grid-column: 2; margin-top: 0; }
  .srv-hero > .srv-hero-free { grid-column: 1 / -1; }
}
.srv-addr-btn { font-family: var(--font-mono); font-weight: 600; max-width: 100%; }
@media (max-width: 639px) { .srv-addr-btn { min-width: 0; max-width: 100%; } }
/* reviews: an empty block is one line */
.rv-none { margin: 0; font-weight: 600; color: rgb(var(--mute)); }

/* the name and the players in the sticky tab bar (wide screens, once the banner is scrolled away) */
.srv-mini-wrap { display: none; }
@media (min-width: 1100px) {
  .srv-mini-wrap { display: block; position: absolute; right: 12px; top: 50%; transform: translateY(-50%); max-width: 38%; }
}
.srv-mini { display: flex; align-items: center; gap: 10px; min-width: 0; padding: 4px 10px 4px 12px; border-radius: var(--r-pill); background: rgb(var(--soft)); font-size: var(--fs-sm); font-weight: 700; }
.srv-mini b { font-weight: 800; }
.srv-mini-dot { width: 8px; height: 8px; flex: none; border-radius: 50%; background: rgb(var(--bad)); }
.srv-mini-dot.on { background: rgb(var(--ok)); }

/* ======================================================================
   server page, pass 2: who is playing, trends, tiles, record cards, tab slide, block errors
   ====================================================================== */

/* «Сейчас на сервере»: a stack of avatars in the banner */
.srv-who { display: inline-flex; max-width: 100%; align-items: center; gap: 10px; margin-top: 12px; padding: 4px 14px 4px 4px; border-radius: var(--r-pill); background: rgb(0 0 0 / .22); color: #fff; text-decoration: none; transition: background-color .15s ease; }
.srv-who:hover { background: rgb(0 0 0 / .34); }
.srv-who-stack { display: flex; flex: none; }
.srv-who-stack > b { display: block; box-sizing: border-box; width: 28px; height: 28px; margin-left: -8px; overflow: hidden; border-radius: 50%; border: 2px solid rgb(30 30 40 / .9); }
.srv-who-stack > b:first-child { margin-left: 0; }
.srv-who-stack > b > i { display: grid; place-items: center; width: 100%; height: 100%; font-style: normal; font-size: var(--fs-xs); font-weight: 800; }
.srv-who-stack > b > img { width: 100% !important; height: 100% !important; }
.srv-who-more { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: var(--fs-md); font-weight: 700; }

/* metrics: sparkline and a trend arrow */
.srv-spark { display: block; width: 100%; height: 22px; margin-top: 6px; color: var(--srv-acc, rgb(var(--brand))); opacity: .85; }
.srv-trend { margin-left: 8px; font-size: var(--fs-sm); font-weight: 800; letter-spacing: 0; vertical-align: middle; }
.srv-trend.is-up { color: rgb(var(--ok)); }
.srv-trend.is-down { color: rgb(var(--bad)); }
.srv-trend.is-flat { color: rgb(var(--mute)); }

/* players: view switch, session bar, place chip, tiles, leaving rows, record cards */
.pl-view { flex: none; }
.pl-view .seg-item { padding: .4rem .65rem; }
.pl-bar { display: block; height: 4px; margin-top: 5px; border-radius: var(--r-pill); background: rgb(var(--ink) / .08); overflow: hidden; }
.pl-bar > u { display: block; height: 100%; border-radius: inherit; background: var(--srv-acc, rgb(var(--brand))); opacity: .75; text-decoration: none; transition: width .4s ease; }
.pl-place-chip { flex: none; padding: 0 7px; border-radius: var(--r-pill); font-size: var(--fs-xs); font-weight: 800; line-height: 18px; background: color-mix(in srgb, var(--srv-acc, rgb(var(--brand))) 18%, transparent); color: rgb(var(--ink)); }
.pl-tiles { display: grid; grid-template-columns: repeat(auto-fill, minmax(132px, 1fr)); gap: 8px; }
.pl-tile { display: flex; width: 100%; flex-direction: column; align-items: center; gap: 4px; padding: 12px 8px 10px; border-radius: var(--r-lg); background: rgb(var(--soft)); text-align: center; transition: transform .15s ease, background-color .15s ease; -webkit-touch-callout: none; user-select: none; }
.pl-tile:hover { transform: translateY(-2px); }
.pl-tile:focus-visible { outline: 0; box-shadow: 0 0 0 3px rgb(var(--brand) / .55); }
.pl-tile-n { max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: var(--fs-md); }
.pl-tile-t { font-size: var(--fs-sm); font-weight: 600; color: rgb(var(--mute)); }
.pl-tile .pl-bar { width: 100%; }
.pl-row { -webkit-touch-callout: none; }
.pl-gone { overflow: hidden; color: rgb(var(--mute)); animation: pl-gone 2.6s ease-in both; }
@keyframes pl-gone { 0% { opacity: .9; max-height: 64px; } 70% { opacity: 0; max-height: 64px; } 100% { opacity: 0; max-height: 0; } }
.pl-facts { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 8px; margin-bottom: 14px; }
.pl-fact { display: flex; min-width: 0; flex-direction: column; gap: 1px; padding: 10px 12px; border-radius: var(--r-lg); background: rgb(var(--soft)); }
.pl-fact-k { font-size: var(--fs-sm); font-weight: 700; color: rgb(var(--mute)); }
.pl-fact-v { font-size: 22px; font-weight: 800; line-height: 1.15; letter-spacing: -.02em; font-variant-numeric: tabular-nums; }
.pl-fact-h { font-size: var(--fs-sm); font-weight: 600; color: rgb(var(--mute)); }

/* a failed block */
.srv-block-err { display: flex; flex-direction: column; align-items: flex-start; gap: 6px; padding: 14px 16px; border-radius: var(--r-lg); background: rgb(var(--badbg)); color: rgb(var(--bad)); }

/* the new tab slides in from the side the user moved to */
@keyframes tab-slide-r { from { opacity: 0; transform: translateX(22px); } to { opacity: 1; transform: none; } }
@keyframes tab-slide-l { from { opacity: 0; transform: translateX(-22px); } to { opacity: 1; transform: none; } }
.tab-slide-r { animation: tab-slide-r .28s cubic-bezier(.2, .8, .2, 1) both; }
.tab-slide-l { animation: tab-slide-l .28s cubic-bezier(.2, .8, .2, 1) both; }

/* the game's accent reaches a few more details */
.srv-page { accent-color: var(--srv-acc); }
.srv-page .chip-filter.on { box-shadow: 0 0 0 1.5px var(--srv-acc), 0 2px 6px rgba(40, 50, 80, .08); }
.srv-page .pl-row:hover { background: color-mix(in srgb, var(--srv-acc) 9%, rgb(var(--soft))); }
.srv-page ::selection { background: color-mix(in srgb, var(--srv-acc) 35%, transparent); }

@media (prefers-reduced-motion: reduce) {
  .tab-slide-r, .tab-slide-l { animation: none; }
  .pl-gone { animation: none; display: none; }
  .pl-tile { transition: none; }
  .pl-tile:hover { transform: none; }
}
html[data-motion='reduce'] :is(.tab-slide-r, .tab-slide-l) { animation: none; }

/* ======================================================================
   server card, pass 3: cover layer, slots, who is playing, ribbon passport, action group, players and events
   ====================================================================== */

/* the cover is a layer of its own: it moves a little slower than the page; the time of day tints it */
.srv-cover { position: absolute; inset: -40px 0; transform: translate3d(0, calc(var(--par, 0) * 1px), 0); will-change: transform; }
.srv-tod { position: absolute; inset: 0; transition: background .8s ease; }
.srv-tod[data-tod='morning'] { background: linear-gradient(180deg, rgb(255 224 150 / .16), transparent 65%); }
.srv-tod[data-tod='dusk'] { background: linear-gradient(180deg, rgb(255 140 70 / .2), rgb(190 60 120 / .06) 70%, transparent); }
.srv-tod[data-tod='night'] { background: linear-gradient(180deg, rgb(30 50 140 / .3), rgb(10 14 50 / .12) 75%, transparent); }

/* chips of the title row stay on one line on a phone: «обновлено» shrinks to its dot */
@media (max-width: 639px) {
  .srv-live { padding-inline: 9px; }
  .srv-live-t { display: none; }
}

/* the game icon: a glow in the page's accent that breathes while the server is online */
.srv-ico { position: relative; flex: none; isolation: isolate; border-radius: 22px; }
.srv-ico::before { content: ''; position: absolute; inset: -12px; z-index: -1; border-radius: 40%; background: radial-gradient(closest-side, var(--srv-acc, rgb(var(--brand))), transparent); opacity: .0; filter: blur(12px); }
.srv-ok .srv-ico::before { opacity: .5; animation: srv-breathe 3.8s ease-in-out infinite; }
@keyframes srv-breathe { 0%, 100% { opacity: .32; transform: scale(.94); } 50% { opacity: .62; transform: scale(1.06); } }

/* the favourite star: lit gold when it is on */
.btn-icon-glass.is-fav { color: #fde047; background: rgb(250 204 21 / .26); box-shadow: inset 0 0 0 1px rgb(250 204 21 / .55), 0 0 18px rgb(250 204 21 / .32); }

/* the hero: no dark box, the cover shows through and fades to dark under the numbers */
.srv-hero { background: linear-gradient(180deg, transparent, rgb(8 10 20 / .4)); box-shadow: none; padding: 16px 4px 4px; }
.srv-hero-n { text-shadow: 0 2px 24px rgb(0 0 0 / .45); }
.srv-hero-max small { font-size: .55em; font-weight: 600; opacity: .8; }
.srv-record { position: relative; display: inline-flex; align-items: center; gap: 6px; margin-left: 4px; padding: 3px 12px; border-radius: var(--r-pill); font-size: var(--fs-sm); font-weight: 800; color: #1a1300; background: linear-gradient(135deg, #fde047, #f59e0b); animation: srv-record 6s ease both; }
@keyframes srv-record { 0% { transform: scale(.6); opacity: 0; } 8% { transform: scale(1.08); opacity: 1; } 14% { transform: none; } 88% { opacity: 1; } 100% { opacity: 0; } }
.srv-hero-trend { display: flex; align-items: center; gap: 8px; margin-top: 8px; font-size: var(--fs-sm); font-weight: 650; color: rgb(255 255 255 / .85); }
.srv-hero-trend > svg { width: 84px; height: 20px; color: #fff; opacity: .9; }

/* in the wide two-column hero the new rows take the whole width */
.srv-hero > :is(.srv-hero-trend, .srv-who) { grid-column: 1 / -1; }

/* slots */
.srv-hero-bar { margin-top: 12px; }
.srv-slots-bar { display: flex; flex: 1; min-width: 0; gap: 2px; height: 16px; }
.srv-slots-bar > i { position: relative; flex: 1 1 0; min-width: 0; border-radius: 3px; background: rgb(255 255 255 / .2); transition: background-color .3s ease; }
.srv-slots-bar > i.on { background: #fff; animation: slot-on .5s ease both; animation-delay: var(--d, 0ms); }
.srv-slots-bar.warm > i.on { background: #fbbf24; }
.srv-slots-bar.hot > i.on { background: #f87171; }
.srv-slots-bar > i.is-peak { background: rgb(255 255 255 / .2); box-shadow: inset 0 -3px 0 #fde047; }
.srv-slots-bar > i.is-peak::after { content: ''; position: absolute; left: 50%; top: -6px; width: 0; height: 0; margin-left: -4px; border: 4px solid transparent; border-top-color: #fde047; }
@keyframes slot-on { from { transform: scaleY(.35); opacity: 0; } to { transform: none; opacity: 1; } }
.srv-slotpill { display: inline-flex; align-items: center; padding: 3px 12px; border-radius: var(--r-pill); font-size: var(--fs-md); font-weight: 750; background: rgb(74 222 128 / .22); color: #bbf7d0; box-shadow: inset 0 0 0 1px rgb(74 222 128 / .45); }
.srv-slotpill.almost { background: rgb(251 191 36 / .22); color: #fde68a; box-shadow: inset 0 0 0 1px rgb(251 191 36 / .5); }
.srv-slotpill.full { background: rgb(248 113 113 / .24); color: #fecaca; box-shadow: inset 0 0 0 1px rgb(248 113 113 / .55); }
.srv-peaknote { font-size: var(--fs-sm); font-weight: 650; color: rgb(255 255 255 / .8); }

/* who is playing: replaces the old plain link */
.srv-who { position: relative; margin-top: 12px; }
.srv-who-row { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 12px; }
.srv-who-stack { display: flex; align-items: center; flex: none; }
.srv-who-av { display: block; box-sizing: border-box; width: 34px; height: 34px; margin-left: -8px; padding: 0; overflow: hidden; border-radius: 50%; border: 2px solid rgb(30 30 40 / .9); cursor: pointer; transition: transform .15s ease; }
.srv-who-av:first-child { margin-left: 0; }
.srv-who-av:hover, .srv-who-av[aria-expanded='true'] { transform: translateY(-3px); z-index: 2; }
.srv-who-av.ring-new { border-color: #4ade80; }
.srv-who-av.ring-vet { border-color: #fbbf24; }
.srv-who-av > i { display: grid; place-items: center; width: 100%; height: 100%; font-style: normal; font-size: var(--fs-sm); font-weight: 800; }
.srv-who-av > img { width: 100% !important; height: 100% !important; }
.srv-who-more-n { margin-left: 6px; font-size: var(--fs-md); font-weight: 800; color: #fff; }
.srv-who-link { font-size: var(--fs-md); font-weight: 700; color: rgb(255 255 255 / .92); text-decoration: none; }
.srv-who-link:hover { text-decoration: underline; text-underline-offset: 3px; }
.srv-who-pop { position: absolute; left: 0; top: calc(100% + 8px); z-index: 12; display: flex; min-width: 190px; max-width: min(88vw, 280px); flex-direction: column; gap: 2px; padding: 12px 14px; border-radius: var(--r-lg); background: rgb(14 16 28 / .96); color: #fff; box-shadow: 0 0 0 1px rgb(255 255 255 / .16), 0 18px 40px -12px rgb(0 0 0 / .7); animation: srv-pop .15s ease both; }
@keyframes srv-pop { from { opacity: 0; transform: translateY(-4px); } to { opacity: 1; transform: none; } }
.srv-who-prof { font-size: var(--fs-md); font-weight: 800; color: #c4b5fd; text-decoration: none; }
.srv-who-prof:hover { text-decoration: underline; }
.srv-who-pop .pl-place-chip { color: #fff; }

/* passport: a ribbon of icons and values */
.pp-ribbon { display: flex; flex-wrap: wrap; gap: 8px; margin: 0; padding: 0; list-style: none; }
.pp-chip { display: inline-flex; min-width: 0; max-width: 100%; align-items: center; gap: 7px; padding: 6px 12px; border-radius: var(--r-pill); font-size: var(--fs-md); font-weight: 650; color: #fff; background: rgb(8 10 20 / .34); box-shadow: inset 0 0 0 1px rgb(255 255 255 / .16); }
.pp-chip > svg { flex: none; opacity: .85; }
.pp-flag { font-size: 20px; line-height: 1; filter: drop-shadow(0 1px 3px rgb(0 0 0 / .5)); }
.pp-ping[data-tone='ok'] { --tone: #4ade80; }
.pp-ping[data-tone='warn'] { --tone: #facc15; }
.pp-ping[data-tone='bad'] { --tone: #f87171; }
.pp-bars { display: inline-flex; align-items: flex-end; gap: 2px; height: 17px; }
.pp-bars > i { width: 3px; border-radius: 1px; background: rgb(255 255 255 / .28); }
.pp-bars > i.on { background: var(--tone); box-shadow: 0 0 6px var(--tone); }

/* actions: «Подписаться» and «Ещё» as one capsule; the main button shows the address */
.srv-act-group { display: inline-flex; align-items: stretch; border-radius: var(--r-pill); background: rgb(255 255 255 / .12); box-shadow: inset 0 0 0 1px rgb(255 255 255 / .28); }
.srv-act-group :is(.btn-glass, .srv-more > button) { --b-bg: transparent; --b-bg-h: rgb(255 255 255 / .18); --b-bg-a: rgb(255 255 255 / .12); --b-ring: inset 0 0 0 0 transparent; }
.srv-act-group .srv-more { border-left: 1px solid rgb(255 255 255 / .22); }
.srv-act-group > :first-child:not(.srv-more) .btn-glass, .srv-act-group > .srv-more:first-child > button { border-radius: var(--r-pill) 0 0 var(--r-pill); }
.srv-act-group > .srv-more > button { border-radius: 0 var(--r-pill) var(--r-pill) 0; }
.srv-act-group > .srv-more:first-child { border-left: 0; }
.srv-act-group > .srv-more:first-child > button { border-radius: var(--r-pill); }
.srv-banner .srv-cta { position: relative; overflow: hidden; flex-direction: column; gap: 0; padding-block: .4rem; line-height: 1.15; --b-img: linear-gradient(135deg, #fff 0%, color-mix(in srgb, var(--srv-acc, #fff) 28%, #fff) 100%); }
.srv-cta-addr { max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-family: var(--font-mono); font-size: var(--fs-xs); font-weight: 600; opacity: .7; }
.srv-banner .srv-cta::after { content: ''; position: absolute; inset: 0; background: linear-gradient(110deg, transparent 35%, rgb(255 255 255 / .8) 50%, transparent 65%); transform: translateX(-130%); transition: transform .7s ease; pointer-events: none; }
.srv-banner .srv-cta:hover::after { transform: translateX(130%); }

/* a one-off hint on touch screens */
.srv-swipe-hint { margin: -4px 0 0; text-align: center; font-size: var(--fs-sm); font-weight: 700; color: rgb(var(--mute)); animation: srv-hint 5.5s ease both; }
@keyframes srv-hint { 0% { opacity: 0; transform: translateY(-4px); } 12% { opacity: 1; transform: none; } 85% { opacity: 1; } 100% { opacity: 0; } }

/* tab icons pop when their tab opens */
.srv-tabs > .seg-item.on .srv-tab-i { animation: tab-i-pop .45s cubic-bezier(.2, .9, .3, 1.4) both; }
@keyframes tab-i-pop { 0% { transform: scale(.6) rotate(-14deg); } 100% { transform: none; } }

/* the page keeps a free strip at the bottom: the last block is never hidden under the phone navigation */
@media (max-width: 639px) { .srv-page { padding-bottom: 5.5rem; } }

/* players: a rank colours the left edge of the row; session spread; empty state */
/* the rank is shown by its badge; the coloured stripe at the edge of the row is gone */
.pl-spread { margin-bottom: 14px; padding: 10px 12px 8px; border-radius: var(--r-lg); background: rgb(var(--soft)); }
.pl-spread-k { font-size: var(--fs-sm); font-weight: 700; color: rgb(var(--mute)); }
.pl-spread-bars { display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); gap: 6px; margin-top: 6px; }
.pl-spread-c { position: relative; display: flex; height: 76px; flex-direction: column; align-items: center; justify-content: flex-end; gap: 2px; }
.pl-spread-c > i { display: block; width: 100%; max-width: 34px; border-radius: 5px 5px 2px 2px; background: rgb(var(--ink) / .1); transform-origin: bottom; animation: bar-up .5s ease both; }
.pl-spread-c > i[data-on] { background: var(--srv-acc, rgb(var(--brand))); }
.pl-spread-c > b { position: absolute; top: 0; font-size: var(--fs-xs); font-weight: 800; font-variant-numeric: tabular-nums; }
.pl-spread-c > small { font-size: var(--fs-2xs); font-weight: 650; color: rgb(var(--mute)); white-space: nowrap; }
@keyframes bar-up { from { transform: scaleY(0); } to { transform: none; } }
.pl-empty { display: flex; flex-direction: column; align-items: center; gap: 6px; padding: 18px 8px 8px; text-align: center; color: rgb(var(--mute)); }
.pl-empty > svg { color: var(--srv-acc, rgb(var(--brand))); }
.pl-empty-t { font-size: var(--fs-xl); font-weight: 800; color: rgb(var(--ink)); }
.pl-empty-x { max-width: 34ch; font-weight: 600; }

/* events: summary of the period and a coloured type before each title */
.ev-sum { display: grid; grid-template-columns: repeat(auto-fit, minmax(120px, 1fr)); gap: 8px; margin-bottom: 14px; }
.ev-sum-c { display: flex; flex-direction: column; padding: 10px 12px; border-radius: var(--r-lg); background: rgb(var(--soft)); }
.ev-sum-c > b { font-size: 21px; font-weight: 800; line-height: 1.15; font-variant-numeric: tabular-nums; }
.ev-sum-c > span { font-size: var(--fs-sm); font-weight: 650; color: rgb(var(--mute)); }
.ev-type { padding: 0 8px; border-radius: var(--r-pill); font-size: var(--fs-xs); font-weight: 800; line-height: 19px; letter-spacing: .02em; text-transform: uppercase; }
.ev-down { background: rgb(var(--badbg)); color: rgb(var(--bad)); }
.ev-up { background: rgb(var(--okbg)); color: rgb(var(--ok)); }
.ev-peak, .ev-maintenance { background: rgb(var(--soft)); color: rgb(var(--link)); }

/* the chart line draws itself once */
.hc-line { stroke-dasharray: 1; stroke-dashoffset: 0; animation: hc-draw 1.1s ease both; }
@keyframes hc-draw { from { stroke-dashoffset: 1; } to { stroke-dashoffset: 0; } }

@media (prefers-reduced-motion: reduce) {
  .srv-ok .srv-ico::before, .srv-record, .srv-swipe-hint, .srv-slots-bar > i.on, .pl-spread-c > i, .hc-line,
  .srv-tabs > .seg-item.on .srv-tab-i { animation: none; }
  .srv-cover { transform: none; }
  .srv-banner .srv-cta::after { display: none; }
}
html[data-motion='reduce'] :is(.srv-record, .srv-swipe-hint, .srv-slots-bar > i.on, .pl-spread-c > i, .hc-line) { animation: none; }

/* ======================================================================
   server tabs, pass 4: reviews, subscription preview, pinned notice, phone metrics
   ====================================================================== */

/* the metrics are one swipeable row on a phone: the next card peeks in */
@media (max-width: 559px) {
  .srv-metrics { display: flex; overflow-x: auto; gap: 8px; margin-inline: -4px; padding: 2px 4px 4px; scroll-snap-type: x mandatory; overscroll-behavior-x: contain; }
  .srv-metrics > .srv-metric, .srv-metrics > .srv-metric:last-child:nth-child(odd) { flex: 0 0 62%; scroll-snap-align: start; }
}

/* reviews */
.rv-stars .fr { background: linear-gradient(90deg, #f6b73c calc(var(--f) * 100%), rgb(var(--line)) calc(var(--f) * 100%)); -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent; color: transparent; }
.rv-reco { margin-top: 6px; display: inline-block; padding: 1px 10px; border-radius: var(--r-pill); font-size: var(--fs-sm); font-weight: 800; background: rgb(var(--okbg)); color: rgb(var(--ok)); }
.rv-dist-row { display: flex; width: 100%; align-items: center; gap: 8px; padding: 1px 4px; margin: 0 -4px; border-radius: 8px; text-align: left; font: inherit; color: inherit; transition: background-color .15s ease; }
.rv-dist-row:not(:disabled):hover { background: rgb(var(--soft)); }
.rv-dist-row:disabled { opacity: .55; cursor: default; }
.rv-dist-row.is-on { background: color-mix(in srgb, #f6b73c 20%, transparent); }
.rv-word { min-width: 6.5em; font-size: var(--fs-md); font-weight: 800; color: rgb(var(--mute)); }
.rv-pick button.is-pop { animation: rv-star .32s cubic-bezier(.2, .9, .3, 1.5) both; animation-delay: calc(var(--i, 1) * 45ms); }
@keyframes rv-star { 0% { transform: scale(.55) rotate(-18deg); } 100% { transform: none; } }
.rv-actions { display: flex; flex-wrap: wrap; align-items: center; gap: 4px 14px; margin-top: 8px; }
.rv-vote { display: inline-flex; align-items: center; gap: 6px; padding: 3px 12px; border-radius: var(--r-pill); font-size: var(--fs-sm); font-weight: 750; color: rgb(var(--mute)); background: rgb(var(--card)); box-shadow: inset 0 0 0 1px rgb(var(--line)); transition: background-color .15s ease, color .15s ease; }
.rv-vote:not(:disabled):hover { color: rgb(var(--ink)); }
.rv-vote.is-on { color: rgb(var(--ink)); background: color-mix(in srgb, var(--srv-acc, rgb(var(--brand))) 22%, transparent); box-shadow: inset 0 0 0 1px var(--srv-acc, rgb(var(--brand))); }
.rv-vote:disabled { cursor: default; }
.rv-reply { margin-top: 8px; padding: 8px 12px; border-radius: var(--r-md); background: rgb(var(--card)); box-shadow: inset 3px 0 0 var(--srv-acc, rgb(var(--brand))); }
.rv-reply-k { display: block; margin-bottom: 2px; font-size: var(--fs-xs); font-weight: 800; letter-spacing: .02em; color: rgb(var(--mute)); }
.rv-reply-form { display: grid; gap: 8px; margin-top: 8px; }

/* a message sample in the subscription dialog */
.sub-preview { margin: 6px 6px 2px 34px; padding: 8px 12px; border-radius: 4px 14px 14px 14px; font-size: var(--fs-md); font-weight: 600; line-height: 1.35; color: rgb(var(--ink)); background: rgb(var(--card)); box-shadow: inset 3px 0 0 rgb(var(--brand)); }

/* the pinned note of the staff */
.srv-notice { display: flex; align-items: flex-start; gap: 12px; padding: 12px 16px; border-radius: var(--r-lg); background: rgb(var(--soft)); box-shadow: inset 4px 0 0 rgb(var(--link)); }
.srv-notice.is-ok { background: rgb(var(--okbg)); box-shadow: inset 4px 0 0 rgb(var(--ok)); }
.srv-notice.is-warn { background: rgb(var(--warnbg)); box-shadow: inset 4px 0 0 rgb(var(--warn)); }
.srv-notice.is-bad { background: rgb(var(--badbg)); box-shadow: inset 4px 0 0 rgb(var(--bad)); }
.srv-notice-i { flex: none; font-size: 20px; line-height: 1.3; }
.srv-notice-add { align-self: flex-start; padding: 6px 14px; border-radius: var(--r-pill); font-size: var(--fs-md); font-weight: 750; color: rgb(var(--mute)); box-shadow: inset 0 0 0 1px rgb(var(--line)); }
.srv-notice-add:hover { color: rgb(var(--ink)); background: rgb(var(--soft)); }
.srv-notice-form { display: grid; gap: 10px; padding: 14px; border-radius: var(--r-lg); box-shadow: inset 0 0 0 1px rgb(var(--line)); }

@media (prefers-reduced-motion: reduce) { .rv-pick button.is-pop { animation: none; } }

/* ---------- a server that is down: one status line in the banner, a plaque and an availability strip instead of the chart ---------- */
.srv-hero-off { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 12px; margin-top: 14px; }
.srv-off-line { margin: 0; display: flex; flex-wrap: wrap; align-items: baseline; gap: 2px 12px; font-size: var(--fs-base); color: rgba(255, 255, 255, 0.82); }
.srv-off-line b { font-size: var(--fs-lg); font-weight: 750; color: #fff; }
.off-state { display: grid; gap: 14px; }
.off-plaque { display: flex; align-items: flex-start; gap: 12px; padding: 12px 14px; border-radius: var(--r-lg); background: rgb(var(--badbg)); box-shadow: inset 0 0 0 1px rgb(var(--bad) / .3); }
.off-dot { flex: none; width: 10px; height: 10px; margin-top: 7px; border-radius: var(--r-pill); background: rgb(var(--bad)); }
.off-title { margin: 0; font-size: var(--fs-lg); font-weight: 700; color: rgb(var(--ink)); }
.off-why { margin: 2px 0 0; font-size: var(--fs-sm); font-weight: 600; color: rgb(var(--mute)); overflow-wrap: anywhere; }
.off-up-head { display: flex; justify-content: space-between; gap: 12px; margin-bottom: 6px; font-size: var(--fs-sm); font-weight: 650; color: rgb(var(--mute)); }
.off-up-head b { color: rgb(var(--ink)); font-variant-numeric: tabular-nums; }
.off-bars { display: flex; gap: 2px; height: 28px; }
.off-cell { flex: 1 1 0; min-width: 0; border-radius: 3px; background: rgb(var(--line)); }
.off-cell.up { background: rgb(var(--ok) / .75); }
.off-cell.down { background: rgb(var(--bad) / .8); }
.off-cell.part { background: rgb(var(--warn) / .8); }
.off-ticks { display: flex; justify-content: space-between; margin-top: 4px; font-size: var(--fs-xs); font-weight: 600; color: rgb(var(--mute)); }
.off-toggle { justify-self: start; }

/* ---------- the server page «Sidebar»: from lg up the banner is a column on the left, the tabs and the content on the right ---------- */
@media (min-width: 1024px) {
  .srv-shell { display: grid; grid-template-columns: 19.5rem minmax(0, 1fr); gap: 1.25rem; align-items: start; }
  /* the column stays in view while the content scrolls (only when the window is tall enough to show all of it) */
  @media (min-height: 860px) { .srv-shell > .srv-banner { position: sticky; top: 5.25rem; } }
  .srv-shell > .srv-banner { padding: 1.25rem; }
  .srv-shell .srv-title { flex-direction: column; align-items: flex-start; gap: .85rem; }
  .srv-shell .srv-title h1 { font-size: 1.3rem; }
  .srv-shell .srv-title > div { width: 100%; }
  /* the counter, the bar and the names stack: the two-column grid of the wide banner does not fit a column */
  .srv-shell .srv-hero { display: block; padding-inline: 0; }
  .srv-shell .srv-hero > * { grid-column: auto; }
  .srv-shell .srv-hero .srv-hero-bar { margin-top: .85rem; }
  .srv-shell .pp-ribbon { flex-direction: column; align-items: stretch; gap: 6px; }
  .srv-shell .pp-chip { max-width: 100%; border-radius: var(--r-md); }
  .srv-shell .srv-actions { display: grid; grid-template-columns: minmax(0, 1fr); }
  .srv-shell .srv-actions .srv-cta, .srv-shell .srv-actions .srv-addr-btn { width: 100%; justify-content: center; }
  .srv-shell .srv-act-group { display: flex; gap: .5rem; }
  .srv-shell .srv-act-group > * { flex: 1; }
}
@media (min-width: 1024px) { .srv-shell .srv-tabs > .seg-item { padding: .5rem .7rem .5rem .6rem; } .srv-shell .srv-tabs { max-width: 100%; } }

/* ---------- the server page «Sidebar», polish: a quiet column, a calm content area ---------- */
@media (min-width: 1024px) {
  /* the column: one soft card instead of cards inside a card */
  .srv-shell > .srv-banner { border-radius: var(--r-xl); }
  .srv-shell .srv-hero { background: none !important; box-shadow: none !important; padding: 0; margin-top: 1rem; }
  .srv-shell .srv-hero-trend { display: none; }
  .srv-shell .srv-hero-n { font-size: 4.25rem; }
  .srv-shell .srv-peaknote { display: none; }
  /* the facts: a plain list (the name on the left, the value on the right), not a stack of bordered pills */
  .srv-shell .pp-ribbon { gap: 0; margin-top: .5rem; }
  .srv-shell .pp-chip { background: none !important; box-shadow: none !important; border-radius: 0; padding: .55rem .1rem; border-bottom: 1px solid rgb(255 255 255 / .12); font-weight: 650; }
  .srv-shell .pp-chip:last-child { border-bottom: 0; }
  .srv-shell .pp-more-btn { margin-top: .25rem; }
  /* the buttons: «Connect» takes the row, «Copy» and «More» share the next one */
  .srv-shell .srv-actions { grid-template-columns: minmax(0, 1fr) auto; margin-top: 1.1rem; }
  .srv-shell .srv-actions .srv-cta { grid-column: 1 / -1; }
  .srv-shell .srv-actions .srv-addr-btn { width: auto; }
  .srv-shell .srv-act-group { display: contents; }
  .srv-shell .srv-act-group > * { flex: none; }
}
/* the sections: the arrow of folding appears when the pointer is on the title (it stays for keyboard and touch) */
@media (hover: hover) {
  .srv-sec .srv-sec-chev { opacity: 0; transition: opacity .15s ease; }
  .srv-sec:hover .srv-sec-chev, .srv-sec-btn:focus-visible .srv-sec-chev { opacity: .7; }
}
.srv-sec-head { margin-bottom: .6rem; }
/* the chart: the hints that repeat what the chart does are quiet */
.hc-tip { display: none; }
.hc-legend { opacity: .8; }
@media (min-width: 1024px) { .srv-shell .srv-page .h-\[320px\], .srv-shell .hc-svg { max-height: 300px; } }
@media (min-width: 1024px) { .srv-shell .srv-who { background: none; padding-left: 0; } .srv-shell .srv-who:hover { background: none; } }

/* ---------- the server page «Sidebar», polish 2 ---------- */
/* the dark scrim of the big card of the list leaked into this banner as a dark box around the figures: gone */
.srv-page .srv-hero::before { content: none; }
@media (min-width: 1024px) {
  /* the decorative circles of the wide banner do not fit a column */
  .srv-shell > .srv-banner .depth-l1, .srv-shell > .srv-banner .depth-l2 { display: none; }
  /* the game is in the list of facts: the chip would say it twice */
  .srv-shell .srv-game-chip { display: none; }
  /* the star sits in the corner of the column, not on a row of its own */
  .srv-shell .srv-title { position: relative; }
  .srv-shell .srv-title > .btn-icon-glass { position: absolute; top: 0; right: 0; }
  /* the name and the players are already in the column: the mini bar in the tabs would only be in the way */
  .srv-shell .srv-mini-wrap { display: none; }
  /* the tab bar: no full-width dark band; while stuck it fades from the colour of the page */
  .srv-shell .srv-tabbar { margin-inline: 0; padding-inline: 0; }
  .srv-shell .srv-tabbar.is-stuck { background: linear-gradient(rgb(var(--page) / .94) 65%, transparent); box-shadow: none; -webkit-backdrop-filter: none; backdrop-filter: none; }
}

/* the players list: the rank as a ring round the avatar and a coloured name, the time with its bar in one column, the leaders, the groups */
.pl-row.has-rank > :first-child, div.has-rank > :first-child { box-shadow: 0 0 0 2px rgb(var(--card)), 0 0 0 3.5px var(--rk); }
.has-rank .pl-rank { color: color-mix(in srgb, var(--rk) 62%, rgb(var(--ink))); }
.pl-time { display: grid; justify-items: end; gap: 5px; min-width: 4.75rem; }
.pl-time .pl-bar { width: 4.75rem; margin-top: 0; }
.pl-top { background: linear-gradient(90deg, rgb(var(--brand) / .09), transparent 70%); border-radius: var(--r-md); }
.pl-group { padding: 12px 4px 4px; font-size: var(--fs-xs); font-weight: 800; letter-spacing: .06em; text-transform: uppercase; color: rgb(var(--mute)); }
ul > .pl-group:first-child { padding-top: 2px; }
