  cat > "$APP_DIR/core-frontend/src/styles/mobile.css" << '__COREGSM_EOF__'
/* ==========================================================================
   Phones. Everything here is about a 360–430 px wide screen: nothing may stick out past the edge, controls stay
   reachable with a thumb, and a row that cannot fit scrolls instead of widening the page.
   Loaded after the other sheets (see main.tsx).
   ========================================================================== */

/* 1. a page never wider than the screen: the root clips what sticks out sideways (the sticky bars and tooltips are inside it) */
html, body { overflow-x: clip; }
#main-content { min-width: 0; max-width: 100%; }
/* grid and flex children may shrink below their content */
:is(.tile, .panel, .cm-bento, .cm-hero, .cm-hero-main, .nw-page, .srv-page) { min-width: 0; }
.nw-page { overflow-x: clip; }

/* 2. a segmented control wider than its row scrolls inside itself (hidden scroll bar), and the active pill stays in sight */
.seg { max-width: 100%; overflow-x: auto; overscroll-behavior-x: contain; scrollbar-width: none; -webkit-overflow-scrolling: touch; }
.seg::-webkit-scrollbar { display: none; }
.seg > .seg-item { flex: none; }
/* the sliding pill is positioned in the scroller's own space: it must be able to move with it */
.seg[data-ind] { position: relative; }

/* 3. weekday chips and other chip rows: one line, scrolling, not a ragged wrap */
@media (max-width: 639px) {
  .cm-days { flex-wrap: nowrap; overflow-x: auto; scrollbar-width: none; margin-inline: -2px; padding: 2px; }
  .cm-days::-webkit-scrollbar { display: none; }
  .cm-days > * { flex: none; }
  .rp-day { min-width: 2.5rem; padding: 8px 10px; }
}

/* 4. «Сообщество»: the strip of section chips keeps its edge, fades at both sides and does not push the page */
.cm-nav { margin: 0; padding-inline: 0; max-width: 100%; scroll-snap-type: x proximity; overscroll-behavior-x: contain; }
.cm-nav-i { scroll-snap-align: center; min-height: 36px; }
@media (max-width: 639px) {
  .cm-nav { -webkit-mask-image: linear-gradient(90deg, #000 calc(100% - 28px), transparent); mask-image: linear-gradient(90deg, #000 calc(100% - 28px), transparent); padding-right: 28px; }
  .cm-hero { padding: 16px; gap: 12px; }
  .cm-hero-stats > div { min-width: 0; }
  .cm-heat { grid-template-columns: 1.3rem repeat(24, minmax(0, 1fr)); gap: 1px; }
  .cm-heat.is-big { grid-template-columns: 1.6rem repeat(24, minmax(0, 1fr)); gap: 2px; }
  .cm-heat-h { font-size: var(--fs-2xs); letter-spacing: -.04em; }
  .cm-search { flex-wrap: wrap; }
  .cm-podium { gap: 6px; }
  .cm-pod { padding-inline: 4px; }
  .pl-hero { padding: 16px; }
  .pl-stats > div { min-width: 0; }
}

/* 5. servers: tab strip, metrics and the featured card */
@media (max-width: 639px) {
  .srv-tabs { overflow-x: auto; scrollbar-width: none; margin-inline: -12px; padding-inline: 12px; width: auto; max-width: none; }
  .srv-tabs::-webkit-scrollbar { display: none; }
  .srv-hero { padding: 16px; border-radius: var(--r-xl); }
  /* the metric cards: a two-column grid again instead of a sideways scroller that a screen reader cannot reach */
  .srv-metrics { display: grid !important; grid-template-columns: repeat(2, minmax(0, 1fr)); overflow: visible; margin-inline: 0; padding: 0; scroll-snap-type: none; }
  .srv-metrics > .srv-metric, .srv-metrics > .srv-metric:last-child:nth-child(odd) { flex: none; min-width: 0; }
  .srv-metrics > .srv-metric:last-child:nth-child(odd) { grid-column: 1 / -1; }
}

/* 6. long names and values break instead of widening the row */
:is(.tile, .panel) :is(h1, h2, h3, h4, .truncate-safe, .adm-tile-v, .cm-srv, .pl-hero) { overflow-wrap: anywhere; }
.truncate { min-width: 0; }

/* 7. the chart: the mouse hint is useless on a touch screen; a row of quick windows replaces it. The tooltip stays inside the chart */
.hc-quick { display: none; gap: 6px; }
@media (pointer: coarse) {
  .hc-tip { display: none; }
  .hc-quick { display: inline-flex; flex-wrap: wrap; }
}
.cm-chart-tip { max-width: 60vw; overflow: hidden; text-overflow: ellipsis; }
@media (max-width: 639px) {
  .cm-chart-ticks { font-size: var(--fs-2xs); }
  .hc-tools { flex-wrap: wrap; gap: 6px; }
}

/* 8. admin: lists and the horizontal section row */
.adm-tablewrap { overflow-x: auto; overscroll-behavior-x: contain; }
.adm-nav { scrollbar-width: none; scroll-snap-type: x proximity; }
.adm-nav::-webkit-scrollbar { display: none; }
.adm-nav .adm-link { scroll-snap-align: center; flex: none; }
.adm-tiles { grid-template-columns: repeat(auto-fit, minmax(min(100%, 9rem), 1fr)); }
@media (max-width: 639px) { .adm-bulk { padding: 8px; } }

/* 9. dialogs as bottom sheets: a grip to drag, the sheet lifts above the on-screen keyboard */
.sheet-grip { display: none; }
@media (max-width: 639px) {
  .sheet-grip { display: flex; justify-content: center; margin: -8px 0 6px; padding: 6px 0 8px; touch-action: none; }
  .sheet-grip > i { width: 40px; height: 4px; border-radius: var(--r-pill); background: rgb(var(--field)); opacity: .6; }
  .modal-ov { padding-bottom: var(--kb, 0px); }
  .modal-ov > [role='dialog'] { max-height: calc(92dvh - var(--kb, 0px)); }
}
/* the floating bottom bar steps aside while the keyboard is open, so it does not sit on top of the field */
html.has-kb .nav-bottom { display: none; }
html.has-kb .save-bar { bottom: calc(.75rem + var(--kb, 0px)); }

/* 10. the page does not end under the floating bottom bar */
@media (max-width: 767px) {
  #main-content { padding-bottom: calc(5.5rem + env(safe-area-inset-bottom, 0px)); }
  .save-bar { bottom: calc(5.5rem + env(safe-area-inset-bottom, 0px)); }
}

/* 11. touch targets: at least 44 × 44 px of hit area, the picture itself stays as it was */
@media (pointer: coarse) {
  :is(.btn-icon, .hint-close, .cm-react, .cm-chip, .hc-chip, .nw-chip, .nw-rubric, .cm-move, .us-perm, .cm-nav-i, .rp-day) { position: relative; }
  :is(.btn-icon, .hint-close, .cm-react, .cm-chip, .hc-chip, .nw-chip, .nw-rubric, .us-perm, .cm-nav-i, .rp-day)::after {
    content: ''; position: absolute; left: 50%; top: 50%; width: max(100%, 44px); height: max(100%, 44px); transform: translate(-50%, -50%);
  }
  .cm-react { min-height: 36px; }
  .nw-rubrics, .cm-chips { gap: 8px; }
}

/* 12. login: the form sits at the top while the keyboard is open, not glued to the bottom */
html.has-kb :is(.auth-shell, .auth-card) { align-self: start; }
@media (max-width: 639px) { html.has-kb .auth-showcase { display: none; } }

/* 13. no network: a thin strip under the safe area */
.net-bar { position: fixed; inset: 0 0 auto 0; z-index: 95; padding: calc(6px + env(safe-area-inset-top, 0px)) 12px 6px; text-align: center; font-size: var(--fs-sm); font-weight: 800; background: rgb(var(--warn)); color: #1b1300; box-shadow: var(--shadow-2); }
.net-bar.is-back { background: rgb(var(--ok)); color: #fff; }

/* 14. data saver: no decorations, no animations, no blur (the data itself is requested half as often, see usePoll) */
@media (max-width: 639px) { .auth-float { display: none !important; } }
html[data-lite] :is(.nw-glow, .nw-backdrop, .auth-glow, .auth-float, .art-float, .art-float-2, .art-twinkle) { display: none !important; }
html[data-lite] *, html[data-lite] *::before, html[data-lite] *::after { animation: none !important; transition: none !important; scroll-behavior: auto !important; }
html[data-lite] .glass, html[data-lite] [class*='backdrop-blur'] { -webkit-backdrop-filter: none; backdrop-filter: none; }
html[data-lite] img[loading='lazy'] { content-visibility: auto; }

/* 15. what the 360 px and landscape pictures showed: a clipped brand, a squeezed server name, a crowded bottom bar */
@media (max-width: 420px) {
  .hdr-word { display: none; }
  .srv-hero .sh-head { flex-wrap: wrap; }
  .srv-hero .sh-actions { flex-basis: 100%; }
}
@media (max-width: 400px) {
  .bn-item { font-size: var(--fs-2xs); letter-spacing: -0.01em; padding-inline: 0; }
}
/* a phone on its side and a small tablet: the menu has no room for the brand name and the user name next to the sections */
@media (min-width: 768px) and (max-width: 1023px) {
  .hdr-word, .pm-btn > .truncate { display: none; }
}
__COREGSM_EOF__
  mkdir -p "$APP_DIR/core-frontend/src/styles"
  cat > "$APP_DIR/core-frontend/src/styles/news-page.css" << '__COREGSM_EOF__'
/* news page (public): rubrics, two columns, cover, article. Colours / shadows / opacity only; no transforms, no infinite animation.
   The page sits on the same grid as every other page: the title on the left edge, no panel of its own behind it. */
.nw-page { position: relative; padding: 0 0 3rem; }
.nw-grid { display: grid; gap: 1.5rem; }
.nw-main { display: grid; grid-template-columns: minmax(0, 1fr); gap: 1.25rem; min-width: 0; align-content: start; }
.nw-feed { max-width: none; margin: 0; }
.nw-group { display: grid; grid-template-columns: minmax(0, 1fr); gap: .75rem; }
.nw-article-wrap { max-width: 52rem; margin: 0 auto; display: grid; gap: 1.25rem; }
@media (min-width: 1100px) {
  .nw-grid.has-side { grid-template-columns: minmax(0, 1fr) 19rem; align-items: start; }
  .nw-aside { position: sticky; top: 1rem; }
}

.nw-rubrics { display: flex; gap: .5rem; overflow-x: auto; scroll-snap-type: x proximity; scrollbar-width: none; padding: .1rem .1rem .35rem; margin: 0 -.1rem; }
.nw-rubrics::-webkit-scrollbar { display: none; }
.nw-rub { flex: 0 0 auto; scroll-snap-align: start; display: inline-flex; align-items: center; gap: .4rem; min-height: 44px; padding: 0 .95rem; border-radius: var(--r-pill);
  border: 1px solid rgb(var(--line)); background: rgb(var(--card)); color: rgb(var(--ink)); font-weight: 650; font-size: .9375rem; cursor: pointer;
  transition: background-color .15s, border-color .15s, color .15s, box-shadow .15s; }
.nw-rub { border-color: transparent; background: transparent; color: rgb(var(--mute)); }
.nw-rub:hover { background: rgb(var(--soft)); color: rgb(var(--ink)); }
.nw-rub[aria-pressed='true'] { background: rgb(var(--brand)); border-color: rgb(var(--brand)); color: #fff; }
.nw-rub-n { min-width: 1.4rem; padding: 0 .4rem; border-radius: var(--r-pill); background: rgb(var(--soft)); color: rgb(var(--mute)); font-size: .8125rem; font-weight: 650; text-align: center; line-height: 1.4rem; }
.nw-rub[aria-pressed='true'] .nw-rub-n { background: rgb(255 255 255 / .22); color: #fff; }
@media (min-width: 640px) { .nw-rubrics { flex-wrap: wrap; overflow: visible; } }

.nw-chip { display: inline-flex; align-items: center; gap: .3rem; padding: .2rem .65rem; border-radius: var(--r-pill); font-size: .8125rem; font-weight: 650; line-height: 1.3;
  background: var(--nw-bg, rgb(var(--soft))); color: var(--nw-fg, rgb(var(--ink))); }
.nw-tone-announcement, .nw-tone-event { --nw-fg: rgb(var(--link)); --nw-bg: rgb(var(--soft)); }
.nw-tone-wipe { --nw-fg: rgb(var(--bad)); --nw-bg: rgb(var(--badbg)); }
.nw-tone-update { --nw-fg: rgb(var(--ok)); --nw-bg: rgb(var(--okbg)); }
.nw-tone-maintenance { --nw-fg: rgb(var(--warn)); --nw-bg: rgb(var(--warnbg)); }
.nw-tone-other { --nw-fg: rgb(var(--mute)); --nw-bg: rgb(var(--soft)); }
.nw-chip-pin { --nw-fg: rgb(var(--ink)); --nw-bg: rgb(var(--card)); box-shadow: inset 0 0 0 1px rgb(var(--field)); }
.nw-chip-date { --nw-fg: rgb(var(--ink)); --nw-bg: rgb(var(--soft)); }
.nw-chips { display: flex; flex-wrap: wrap; align-items: center; gap: .35rem .5rem; }
.nw-date { font-size: .875rem; font-weight: 600; color: rgb(var(--mute)); }

.nw-hero::before { display: none; }
.nw-hero .nf-hero-in { background-image: none; }
.nw-cover { position: relative; overflow: hidden; display: flex; align-items: flex-end; min-height: 17rem; background: rgb(var(--soft)); color: #fff; }
.nw-cover.is-tall { min-height: 22rem; }
.nw-cover-bg { position: absolute; inset: 0; background-size: cover; background-position: center; }
.nw-cover-shade { position: absolute; inset: 0; background: linear-gradient(180deg, rgb(8 10 20 / .08) 18%, rgb(8 10 20 / .86) 100%); }
.nw-cover-in { position: relative; width: 100%; display: grid; gap: .6rem; padding: 3rem 2rem 1.4rem; }
.nw-cover-chips { display: flex; flex-wrap: wrap; gap: .4rem; }
.nw-cover-title { margin: 0; font-size: clamp(1.6rem, 4vw, 2.4rem); line-height: 1.15; font-weight: 800; letter-spacing: -.02em; overflow-wrap: anywhere; color: #fff; }
.nw-cover-title a { color: inherit; text-decoration: none; }
.nw-cover-title a:hover { text-decoration: underline; }

.nw-thumb { display: block; }
.nw-item .nf-item-title a { color: inherit; text-decoration: none; }
.nw-item .nf-item-title a:hover { text-decoration: underline; }
/* the whole card is one big link (the title link is stretched over it) */
.nw-item .nf-item-title a::after { content: ''; position: absolute; inset: 0; }
.nw-item:hover .nw-more { text-decoration: underline; }
.nw-more { display: inline-flex; align-items: center; min-height: 44px; font-weight: 650; color: rgb(var(--link)); text-decoration: none; }
.nw-more:hover { text-decoration: underline; }
.nw-strip { display: flex; gap: .4rem; flex-wrap: wrap; text-decoration: none; }
.nw-strip img, .nw-strip-more { width: 4.5rem; height: 3rem; border-radius: var(--r-sm); object-fit: cover; background: rgb(var(--soft)); }
.nw-strip-more { display: grid; place-items: center; font-weight: 650; color: rgb(var(--mute)); }
.nw-author-name { color: rgb(var(--ink)); }
.nw-role { padding: .05rem .5rem; border-radius: var(--r-pill); font-size: .75rem; font-weight: 650; background: rgb(var(--soft)); color: rgb(var(--link)); }
.nw-role-moderator { background: rgb(var(--okbg)); color: rgb(var(--ok)); }

.nw-countdown { display: inline-flex; align-items: center; gap: .4rem; padding: .3rem .8rem; border-radius: var(--r-pill); font-weight: 650; background: rgb(var(--warnbg)); color: rgb(var(--warn)); }
.nw-countdown.is-done { background: rgb(var(--okbg)); color: rgb(var(--ok)); }
.nw-countdown.is-compact { padding: .15rem .6rem; font-size: .875rem; }

.nw-prose { font-size: 1.0625rem; max-width: 70ch; overflow-wrap: anywhere; }
.nw-prose-lg { font-size: 1.125rem; }
.nw-prose .leading-snug { line-height: 1.7; }
.nw-prose-lg .h-\[0\.6em\] { height: .85em; }
.nw-prose .flex.gap-2, .nw-prose .flex.gap-1\.5 { margin: .2em 0; }
.nw-prose div[style*='border-left'] { margin: .7em 0; padding: .25em 0 .25em 1em; }
.nw-prose pre { margin: .7em 0; }
.nf-text .nw-prose { max-width: none; }

.nw-h2 { margin: 0 0 .75rem; font-size: 1.125rem; font-weight: 800; letter-spacing: -.01em; }
.nw-changes-grid { display: grid; gap: .75rem; }
@media (min-width: 640px) { .nw-changes-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
.nw-change { --nw-fg: rgb(var(--link)); --nw-bg: rgb(var(--soft)); padding: .85rem 1rem; border-radius: var(--r-lg); background: rgb(var(--card)); border: 1px solid rgb(var(--line)); border-left: 4px solid var(--nw-fg); }
.nw-change-add { --nw-fg: rgb(var(--ok)); --nw-bg: rgb(var(--okbg)); }
.nw-change-change { --nw-fg: rgb(var(--warn)); --nw-bg: rgb(var(--warnbg)); }
.nw-change-remove { --nw-fg: rgb(var(--bad)); --nw-bg: rgb(var(--badbg)); }
.nw-change-head { display: flex; align-items: center; gap: .5rem; margin: 0 0 .5rem; font-size: 1rem; font-weight: 650; }
.nw-change-ico { display: grid; place-items: center; width: 1.75rem; height: 1.75rem; border-radius: var(--r-pill); background: var(--nw-bg); color: var(--nw-fg); }
.nw-change ul { margin: 0; padding: 0 0 0 1.1rem; display: grid; gap: .3rem; line-height: 1.5; }

.nw-gallery { list-style: none; margin: 0; padding: 0; display: grid; gap: .6rem; grid-template-columns: repeat(auto-fill, minmax(10rem, 1fr)); }
.nw-gallery-1 { grid-template-columns: minmax(0, 1fr); }
.nw-gallery-2, .nw-gallery-4 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.nw-gal-item { display: block; width: 100%; padding: 0; aspect-ratio: 16 / 10; overflow: hidden; border-radius: var(--r-lg); border: 1px solid rgb(var(--line)); background: rgb(var(--soft)); cursor: pointer; transition: box-shadow .15s, opacity .15s; }
.nw-gal-item:hover { box-shadow: var(--shadow-2); opacity: .92; }
.nw-gal-item img { display: block; width: 100%; height: 100%; object-fit: cover; }
.nw-viewer { position: fixed; inset: 0; z-index: 60; display: grid; place-items: center; padding: 4rem 1rem 3.5rem; background: rgb(8 10 20 / .88); }
.nw-viewer-img { max-width: 100%; max-height: 100%; object-fit: contain; border-radius: var(--r-md); }
.nw-viewer-btn { position: absolute; display: grid; place-items: center; width: 48px; height: 48px; border-radius: var(--r-pill); border: 0; background: rgb(255 255 255 / .16); color: #fff; font-size: 1.75rem; line-height: 1; cursor: pointer; transition: background-color .15s; }
.nw-viewer-btn:hover { background: rgb(255 255 255 / .28); }
.nw-viewer-close { top: .75rem; right: .75rem; }
.nw-viewer-prev { left: .5rem; top: 50%; margin-top: -24px; }
.nw-viewer-next { right: .5rem; top: 50%; margin-top: -24px; }
.nw-viewer-count { position: absolute; bottom: 1rem; left: 0; right: 0; text-align: center; color: #fff; font-weight: 600; }

.nw-srv-list { list-style: none; margin: 0; padding: 0; display: grid; gap: .6rem; grid-template-columns: repeat(auto-fill, minmax(16rem, 1fr)); }
.nw-srv { display: flex; align-items: center; gap: .75rem; min-height: 56px; padding: .65rem .85rem; border-radius: var(--r-lg); background: rgb(var(--card)); border: 1px solid rgb(var(--line)); color: inherit; text-decoration: none; transition: box-shadow .15s, border-color .15s; }
.nw-srv:hover { box-shadow: var(--shadow-2); border-color: rgb(var(--field)); }
.nw-srv-main { flex: 1; min-width: 0; display: grid; gap: .1rem; }
.nw-srv-name { font-weight: 650; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.nw-srv-meta { display: flex; gap: .6rem; font-size: .8125rem; font-weight: 600; color: rgb(var(--mute)); }
.nw-srv-skel { height: 56px; border-radius: var(--r-lg); }

.nw-actions, .nw-actions-wrap, .nw-toolbar { display: flex; flex-wrap: wrap; gap: .6rem; align-items: center; }
.nw-react { display: grid; gap: .4rem; }
.nw-react-row { display: flex; flex-wrap: wrap; gap: .5rem; }
.nw-react-btn { display: inline-flex; align-items: center; justify-content: center; gap: .45rem; min-height: 44px; min-width: 68px; padding: 0 .9rem; border-radius: var(--r-pill); border: 1px solid rgb(var(--line));
  background: rgb(var(--card)); color: rgb(var(--ink)); font-weight: 650; cursor: pointer; transition: background-color .15s, border-color .15s, box-shadow .15s; }
.nw-react-btn:hover:not(:disabled) { border-color: rgb(var(--field)); box-shadow: var(--shadow-1); }
.nw-react-btn[aria-pressed='true'] { background: rgb(var(--soft)); border-color: rgb(var(--brand)); box-shadow: inset 0 0 0 1px rgb(var(--brand)); }
.nw-react-btn:disabled { cursor: default; opacity: .8; }
.nw-react-emoji { font-size: 1.15rem; }
.nw-react-hint { margin: 0; font-size: .875rem; font-weight: 600; color: rgb(var(--mute)); }
.nw-prevnext { display: grid; gap: .75rem; grid-template-columns: repeat(2, minmax(0, 1fr)); padding: 0 1.25rem 1.25rem; }
.nw-pn { display: grid; gap: .15rem; min-height: 44px; padding: .75rem 1rem; border-radius: var(--r-lg); background: rgb(var(--soft)); color: inherit; text-decoration: none; transition: box-shadow .15s; }
.nw-pn:hover { box-shadow: var(--shadow-1); }
.nw-pn-next { text-align: right; grid-column: 2; }
.nw-pn-kicker { font-size: .8125rem; font-weight: 650; color: rgb(var(--mute)); }
.nw-pn-title { font-weight: 650; overflow-wrap: anywhere; }

.nw-article { background: rgb(var(--card)); border: 1px solid rgb(var(--line)); border-radius: var(--r-xl); overflow: hidden; box-shadow: var(--shadow-1); }
.nw-read { display: inline-flex; align-items: center; padding: .15rem .65rem; border-radius: var(--r-pill); background: rgb(var(--soft)); color: rgb(var(--mute)); font-size: .8125rem; font-weight: 650; }
.nw-article-in { display: grid; gap: 1.5rem; padding: 1.5rem 2rem 2rem; }

.nw-aside { display: grid; grid-template-columns: minmax(0, 1fr); gap: .75rem; }
.nw-side-sec { padding: .5rem 1rem; border-radius: var(--r-lg); background: rgb(var(--card)); border: 1px solid rgb(var(--line)); }
.nw-side-h { margin: .6rem 0 .3rem; font-size: .8125rem; font-weight: 650; letter-spacing: .06em; text-transform: uppercase; color: rgb(var(--mute)); }
.nw-side-toggle { display: flex; align-items: center; justify-content: space-between; width: 100%; min-height: 44px; padding: 0; border: 0; background: none; color: rgb(var(--ink)); font-weight: 650; font-size: 1rem; cursor: pointer; }
.nw-side-body { padding-bottom: .5rem; }
.nw-side-list { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: minmax(0, 1fr); }
.nw-side-list a, .nw-side-rub { display: flex; align-items: center; gap: .5rem; width: 100%; min-height: 44px; padding: 0; border: 0; background: none; color: rgb(var(--ink)); font-weight: 600; text-align: left; text-decoration: none; cursor: pointer; }
.nw-side-list a span { overflow: hidden; text-overflow: ellipsis; }
.nw-side-list a:hover, .nw-side-rub:hover, .nw-side-rub[aria-pressed='true'] { color: rgb(var(--link)); }
.nw-side-rub span:nth-child(2) { flex: 1; }
.nw-works li { display: grid; gap: .1rem; padding: .5rem 0; }
.nw-work-name { font-weight: 650; }
.nw-work-meta { font-size: .875rem; font-weight: 600; color: rgb(var(--mute)); }

.nw-skel { display: grid; gap: 1rem; }
.nw-skel-hero { height: 20rem; border-radius: var(--r-xl); }
.nw-skel-hero.is-tall { height: 22rem; }
.nw-skel-row { display: grid; grid-template-columns: 8.5rem minmax(0, 1fr); gap: 1rem; padding: .75rem; border-radius: var(--r-lg); background: rgb(var(--card)); border: 1px solid rgb(var(--line)); }
.nw-skel-thumb { min-height: 6.5rem; border-radius: var(--r-md); }
.nw-skel-lines { display: grid; gap: .6rem; align-content: center; }

/* editor */
.nw-edit-row { display: grid; gap: .5rem; grid-template-columns: minmax(0, 9rem) minmax(0, 1fr) auto; align-items: center; }

@media (max-width: 560px) {
  .nw-hero, .nw-article { border-radius: var(--r-lg); }
  .nw-cover { min-height: 13rem; }
  .nw-cover.is-tall { min-height: 15rem; }
  .nw-cover-in { padding: 2.5rem 1.1rem 1.1rem; }
  .nw-article-in { padding: 1.25rem 1.1rem 1.5rem; }
  .nw-skel-row { grid-template-columns: 5.5rem minmax(0, 1fr); }
  .nw-skel-hero { height: 14rem; }
  .nw-prevnext { grid-template-columns: minmax(0, 1fr); }
  .nw-pn-next { grid-column: auto; }
  .nw-edit-row { grid-template-columns: minmax(0, 1fr); }
}

/* ---------- generated cover: no picture and no game, so the panel draws one in the colour of the rubric (--gen) ---------- */
.nw-gen {
  background:
    radial-gradient(90% 120% at 8% -10%, color-mix(in srgb, var(--gen) 92%, #fff) 0%, transparent 62%),
    radial-gradient(80% 110% at 105% 105%, color-mix(in srgb, var(--gen) 55%, #7c3aed) 0%, transparent 60%),
    linear-gradient(155deg, color-mix(in srgb, var(--gen) 38%, #0b0c16), #0b0c16 85%);
  overflow: hidden;
}
/* a faint grid that fades out away from the corner */
.nw-gen::before { content: ''; position: absolute; inset: 0; pointer-events: none;
  background-image: linear-gradient(rgb(255 255 255 / .07) 1px, transparent 1px), linear-gradient(90deg, rgb(255 255 255 / .07) 1px, transparent 1px);
  background-size: 28px 28px;
  -webkit-mask-image: radial-gradient(80% 90% at 85% 12%, #000, transparent 75%); mask-image: radial-gradient(80% 90% at 85% 12%, #000, transparent 75%); }
/* the pictogram of the rubric, large and quiet */
.nw-gen-ico { position: absolute; right: 7%; top: 0; bottom: 0; margin: auto 0; height: 62%; aspect-ratio: 1; display: grid; place-items: center; color: #fff; opacity: .17; pointer-events: none; }
.nw-gen-ico svg { width: 100%; height: 100%; stroke-width: 1.15; }
.nf-thumb.nw-gen { position: relative; }
.nf-thumb .nw-gen-ico { height: 58%; right: 9%; }
/* without a picture the cover is compact: no empty half above the title */
.nw-cover.is-gen { min-height: 10.5rem; }
.nw-cover.is-gen.is-tall { min-height: 13rem; }
.nw-cover.is-gen .nw-cover-shade { opacity: .5; }
.nw-cover.is-gen .nw-cover-in { padding-top: 2rem; }
@media (max-width: 560px) { .nw-cover.is-gen { min-height: 8.5rem; } .nw-cover.is-gen.is-tall { min-height: 10rem; } }

/* ---------- page background: a soft glow behind the content; on an article the picture, blurred (or the rubric's colour) ---------- */
.nw-page { isolation: isolate; }
.nw-glow, .nw-backdrop { position: absolute; z-index: -1; pointer-events: none; inset: -4rem -1.5rem auto -1.5rem; }
.nw-glow { height: 30rem;
  background: radial-gradient(60% 70% at 18% 0%, rgb(var(--brand) / .2), transparent 70%), radial-gradient(45% 60% at 88% 8%, rgb(236 72 153 / .12), transparent 70%);
  /* fade out at the sides too: no hard vertical edges */
  -webkit-mask-image: linear-gradient(90deg, transparent, #000 18%, #000 82%, transparent); mask-image: linear-gradient(90deg, transparent, #000 18%, #000 82%, transparent); }
.nw-backdrop { height: 34rem; background-size: cover; background-position: center top; filter: blur(46px) saturate(1.35); opacity: .3;
  background-image: radial-gradient(60% 80% at 50% 0%, color-mix(in srgb, var(--gen, rgb(var(--brand))) 70%, transparent), transparent 72%);
  -webkit-mask-image: linear-gradient(#000 25%, transparent), linear-gradient(90deg, transparent, #000 18%, #000 82%, transparent);
  mask-image: linear-gradient(#000 25%, transparent), linear-gradient(90deg, transparent, #000 18%, #000 82%, transparent);
  -webkit-mask-composite: source-in; mask-composite: intersect; }
.nw-backdrop.is-flat { opacity: .5; }

/* ---------- article: contents, reading progress, read next ---------- */
.nw-toc { padding: 1rem 1.15rem; border-radius: var(--r-lg); background: rgb(var(--soft)); border: 1px solid rgb(var(--line)); }
.nw-toc-h { margin: 0 0 .4rem; font-size: .9375rem; font-weight: 800; }
.nw-toc ol { list-style: none; margin: 0; padding: 0; display: grid; gap: .05rem; }
.nw-toc button { display: block; width: 100%; min-height: 36px; padding: .2rem 0; border: 0; background: none; text-align: left; font: inherit; font-weight: 600; color: rgb(var(--link)); cursor: pointer; }
.nw-toc button:hover { text-decoration: underline; }
.nw-toc-l2 { padding-left: 1rem; }
.nw-toc-l3 { padding-left: 2rem; }
.nw-prose [id^='nw-h-'] { scroll-margin-top: 5.5rem; }
.nw-progress { position: fixed; top: 0; left: 0; height: 3px; z-index: 50; pointer-events: none; border-radius: 0 var(--r-pill) var(--r-pill) 0;
  background: linear-gradient(90deg, rgb(var(--brand)), rgb(var(--brand-2))); transition: width .1s linear; }
.nw-related { display: grid; gap: .5rem; padding: 0 2rem 1.5rem; }
.nw-related .nf-list { grid-template-columns: repeat(auto-fill, minmax(14rem, 1fr)); }
@media (max-width: 560px) { .nw-related { padding: 0 1.1rem 1.25rem; } }

/* ---------- side panel: the servers right now ---------- */
.nw-live a { justify-content: flex-start; }
.nw-live-dot { width: .55rem; height: .55rem; flex: none; border-radius: var(--r-pill); background: rgb(var(--field)); }
.nw-live-dot.is-on { background: rgb(var(--ok)); box-shadow: 0 0 0 3px rgb(var(--ok) / .2); }
.nw-live-dot.is-off { background: rgb(var(--bad)); }
.nw-live-name { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.nw-live-n { flex: none; font-size: .8125rem; font-weight: 650; color: rgb(var(--mute)); }

/* ---------- editorial buttons in the news: text links with a coloured underline, an arrow on the main one ----------
   (the variables are overridden, so every state of the generic button rule stays transparent) */
:is(.nw-hero, .nw-article) :is(.btn, .btn-soft) {
  --b-bg: transparent; --b-bg-h: transparent; --b-bg-a: transparent; --b-img: none;
  --b-hl: inset 0 0 0 0 transparent; --b-hl-h: inset 0 0 0 0 transparent; --b-hl-a: inset 0 0 0 0 transparent;
  --b-ring: inset 0 0 0 0 transparent; --b-ring-h: inset 0 0 0 0 transparent; --b-ring-a: inset 0 0 0 0 transparent;
  --b-ovl: inset 0 0 0 999px transparent; --b-ovl-h: inset 0 0 0 999px transparent; --b-ovl-a: inset 0 0 0 999px transparent;
  --b-drop: 0 0 0 0 transparent; --b-drop-h: 0 0 0 0 transparent; --b-drop-a: 0 0 0 0 transparent;
  --b-fg: rgb(var(--ink)); --b-fg-h: rgb(var(--link));
  padding: .25rem 0; border-radius: 0; font-size: 1rem; font-weight: 650; letter-spacing: 0;
  text-decoration: underline; text-decoration-thickness: 2px; text-underline-offset: .4em; text-decoration-color: rgb(var(--brand));
}
:is(.nw-hero, .nw-article) .btn:not(.btn-soft)::after { content: '→'; display: inline-block; margin-left: .1rem; text-decoration: none; transition: margin-left .15s ease; }
:is(.nw-hero, .nw-article) .btn:not(.btn-soft):hover::after { margin-left: .4rem; }
/* the second actions: quiet, a thin underline */
:is(.nw-hero, .nw-article) .btn-soft {
  --b-fg: rgb(var(--mute)); --b-fg-h: rgb(var(--ink));
  font-size: .9375rem; font-weight: 500; text-decoration-thickness: 1px; text-decoration-color: rgb(var(--field));
}
:is(.nw-hero, .nw-article) .nw-toolbar, :is(.nw-hero, .nw-article) .nw-actions-wrap, .nw-hero .nf-actions { gap: .25rem 1.5rem; }

/* ---------- the generated covers differ: the rubric colour, but another pattern and light for every fourth news (data-v = id % 4) ---------- */
.nw-gen[data-v='1'] { background:
    radial-gradient(70% 100% at 92% 108%, color-mix(in srgb, var(--gen) 90%, #fff) 0%, transparent 60%),
    radial-gradient(60% 90% at -6% -10%, color-mix(in srgb, var(--gen) 50%, #7c3aed) 0%, transparent 62%),
    linear-gradient(200deg, color-mix(in srgb, var(--gen) 34%, #0b0c16), #0b0c16 85%); }
.nw-gen[data-v='1']::before { background-image: radial-gradient(rgb(255 255 255 / .16) 1.2px, transparent 1.6px); background-size: 16px 16px;
  -webkit-mask-image: radial-gradient(80% 90% at 18% 85%, #000, transparent 75%); mask-image: radial-gradient(80% 90% at 18% 85%, #000, transparent 75%); }
.nw-gen[data-v='2'] { background:
    radial-gradient(90% 120% at 50% -20%, color-mix(in srgb, var(--gen) 95%, #fff) 0%, transparent 64%),
    radial-gradient(70% 90% at 100% 100%, color-mix(in srgb, var(--gen) 55%, #0ea5e9) 0%, transparent 60%),
    linear-gradient(170deg, color-mix(in srgb, var(--gen) 36%, #0b0c16), #0b0c16 85%); }
.nw-gen[data-v='2']::before { background-image: repeating-linear-gradient(135deg, rgb(255 255 255 / .1) 0 1px, transparent 1px 14px);
  -webkit-mask-image: radial-gradient(90% 90% at 80% 10%, #000, transparent 80%); mask-image: radial-gradient(90% 90% at 80% 10%, #000, transparent 80%); }
.nw-gen[data-v='3'] { background:
    radial-gradient(80% 110% at 100% 0%, color-mix(in srgb, var(--gen) 90%, #fff) 0%, transparent 60%),
    radial-gradient(70% 100% at 0% 100%, color-mix(in srgb, var(--gen) 55%, #ec4899) 0%, transparent 62%),
    linear-gradient(120deg, color-mix(in srgb, var(--gen) 34%, #0b0c16), #0b0c16 85%); }
.nw-gen[data-v='3']::before { background-image: repeating-radial-gradient(circle at 82% 22%, rgb(255 255 255 / .12) 0 1px, transparent 1px 18px);
  background-size: auto; -webkit-mask-image: radial-gradient(90% 100% at 82% 22%, #000, transparent 78%); mask-image: radial-gradient(90% 100% at 82% 22%, #000, transparent 78%); }
.nw-soon { display: grid; gap: .35rem; padding: .35rem 0 .6rem; color: inherit; text-decoration: none; }
.nw-soon b { font-weight: 650; overflow-wrap: anywhere; }
.nw-soon:hover b { text-decoration: underline; }

.nw-hints { display: grid; grid-template-columns: repeat(auto-fit, minmax(190px, 1fr)); gap: 10px; list-style: none; padding: 0; margin: 18px 0 0; }
.nw-hint { display: grid; gap: 4px; padding: 14px; border-radius: var(--r-md); border: 1px dashed rgb(var(--line)); font-size: var(--fs-sm); }
.nw-hint b { font-size: var(--fs-md); }
.nw-hint > span:last-child { opacity: .7; }
.nw-hint-ico { display: inline-grid; place-items: center; width: 34px; height: 34px; border-radius: var(--r-md); background: color-mix(in srgb, currentColor 10%, transparent); }
.nw-side-hint { margin-left: auto; margin-right: 8px; font-size: var(--fs-xs); font-weight: 500; opacity: .65; }
.nw-gallery-3 > li:first-child, .nw-gallery-5 > li:first-child { grid-column: span 2; grid-row: span 2; }
.nw-gallery-6 > li:first-child { grid-column: span 2; grid-row: span 2; }
.nw-react-btn { position: relative; }
.nw-skel-entry { border-radius: 16px; overflow: hidden; border: 1px solid rgb(var(--line)); margin-bottom: 14px; }
.nw-skel-banner { height: 120px; border-radius: 0; }
.nw-skel-entry .nw-skel-lines { display: grid; gap: 10px; padding: 16px; }

/* ---------- «Новое», the hero, anchors, up, zoom, unread counter ---------- */
.nw-new { display: inline-flex; align-items: center; padding: .2rem .6rem; border-radius: var(--r-pill); font-size: .75rem; font-weight: 800; letter-spacing: .04em; text-transform: uppercase; color: #fff; background: linear-gradient(135deg, rgb(var(--brand)), rgb(var(--brand-2))); }
.nw-hero { display: grid; gap: .75rem; }
.nw-hero .nw-cover { border-radius: var(--r-xl); }
.nw-hero-in { display: flex; flex-wrap: wrap; align-items: center; gap: .75rem 1rem; }
.nw-hero-in p { flex: 1 1 18rem; min-width: 0; margin: 0; font-weight: 600; color: rgb(var(--mute)); }
.nw-h { position: relative; }
.nw-anchor { margin-left: .4em; padding: 0 .2em; font: inherit; font-size: .8em; font-weight: 700; color: rgb(var(--mute)); opacity: 0; transition: opacity .15s ease; }
.nw-h:hover .nw-anchor, .nw-anchor:focus-visible { opacity: 1; }
.nw-anchor:hover { color: rgb(var(--link)); }
@media (hover: none) { .nw-anchor { opacity: .5; } }
.nw-top { position: fixed; right: 1rem; bottom: 6rem; z-index: 40; display: grid; place-items: center; width: 2.75rem; height: 2.75rem; border-radius: 50%; font-size: 1.25rem; font-weight: 800; color: #fff; background: linear-gradient(135deg, rgb(var(--brand)), rgb(var(--brand-2))); box-shadow: var(--shadow-3); animation: nw-top-in .2s ease; }
@media (min-width: 768px) { .nw-top { bottom: 1.5rem; right: 1.5rem; } }
@keyframes nw-top-in { from { opacity: 0; transform: translateY(8px); } }
.nw-cover-zoomable { position: relative; }
.nw-zoom { position: absolute; top: .75rem; right: .75rem; z-index: 2; display: grid; place-items: center; width: 2.25rem; height: 2.25rem; border-radius: 50%; font-size: 1.1rem; color: #fff; background: rgb(0 0 0 / .45); backdrop-filter: blur(6px); opacity: .85; transition: opacity .15s ease, background-color .15s ease; }
.nw-zoom:hover, .nw-zoom:focus-visible { opacity: 1; background: rgb(0 0 0 / .65); }
.nw-unread { display: inline-grid; place-items: center; min-width: 1.15rem; height: 1.15rem; padding: 0 .3rem; margin-left: .4rem; border-radius: var(--r-pill); font-size: .7rem; font-weight: 800; line-height: 1; color: #fff; background: rgb(var(--bad)); font-variant-numeric: tabular-nums; }
.nw-unread-abs { position: absolute; top: .35rem; right: 24%; margin: 0; }
@media (prefers-reduced-motion: reduce) { .nw-top { animation: none; } }

/* ---------- comments under an item ---------- */
.nw-comments { margin-top: 2.5rem; display: grid; gap: 1rem; scroll-margin-top: 5rem; }
.cm-top { display: flex; flex-wrap: wrap; align-items: center; gap: .6rem 1rem; }
.cm-top .nw-h2 { margin: 0; margin-right: auto; }
.cm-total { color: rgb(var(--mute)); font-weight: 700; }
.cm-note, .cm-empty { margin: 0; font-weight: 600; color: rgb(var(--mute)); }
.cm-list { display: grid; gap: .75rem; }
.cm-thread { display: grid; gap: .5rem; }
.cm { position: relative; display: grid; gap: .45rem; padding: .85rem 1rem; border-radius: var(--r-lg, 16px); background: rgb(var(--soft)); scroll-margin-top: 6rem; transition: box-shadow .3s, background .3s; }
.cm.is-pinned { box-shadow: inset 3px 0 0 rgb(var(--brand)); }
.cm.is-target { background: color-mix(in srgb, rgb(var(--brand)) 14%, rgb(var(--soft))); box-shadow: 0 0 0 2px rgb(var(--brand)); }
.cm-replies { display: grid; gap: .5rem; margin-left: 1.25rem; padding-left: .85rem; border-left: 2px solid rgb(var(--line)); }
.cm-head { display: flex; flex-wrap: wrap; align-items: center; gap: .4rem .6rem; }
.cm-ava { display: inline-grid; place-items: center; width: 1.75rem; height: 1.75rem; border-radius: 50%; background: color-mix(in srgb, rgb(var(--brand)) 20%, transparent); font-size: .8rem; font-weight: 800; }
.cm-author { font-weight: 800; overflow-wrap: anywhere; }
.cm-time { font-size: .8rem; font-weight: 700; color: rgb(var(--mute)); text-decoration: none; }
a.cm-time:hover { color: rgb(var(--link)); }
.cm-text { display: grid; gap: .25rem; overflow-wrap: anywhere; font-weight: 500; }
.cm-text p { margin: 0; }
.cm-text blockquote { margin: 0; padding: .1rem .75rem; border-left: 3px solid rgb(var(--line)); color: rgb(var(--mute)); }
.cm-text code { padding: .05rem .35rem; border-radius: 6px; background: rgb(var(--line) / .5); font-size: .9em; }
.cm-text a { color: rgb(var(--link)); text-decoration: underline; text-underline-offset: 2px; }
.cm-mention { font-weight: 800; color: rgb(var(--link)); }
.cm-stub { margin: 0; font-style: italic; font-weight: 600; color: rgb(var(--mute)); }
.cm-foot { display: flex; flex-wrap: wrap; align-items: center; gap: .25rem .75rem; }
.cm-reacts { display: inline-flex; gap: .25rem; }
.cm-react { display: inline-flex; align-items: center; gap: .3rem; min-height: 32px; padding: 0 .55rem; border: 1px solid transparent; border-radius: var(--r-pill); background: transparent; font-size: .85rem; font-weight: 700; cursor: pointer; }
.cm-react:hover:not(:disabled) { background: rgb(var(--line) / .5); }
.cm-react[aria-pressed='true'] { border-color: rgb(var(--brand)); background: color-mix(in srgb, rgb(var(--brand)) 14%, transparent); }
.cm-react:disabled { opacity: .55; cursor: default; }
.cm-act { padding: .25rem .1rem; border: 0; background: none; font-size: .85rem; font-weight: 700; color: rgb(var(--mute)); cursor: pointer; }
.cm-act:hover { color: rgb(var(--link)); text-decoration: underline; }
.cm-compose { position: relative; display: grid; gap: .5rem; }
.cm-input { min-height: 5rem; resize: vertical; }
.cm-compose-foot { display: flex; flex-wrap: wrap; align-items: center; gap: .5rem .9rem; }
.cm-counter { font-size: .8rem; font-weight: 700; color: rgb(var(--mute)); font-variant-numeric: tabular-nums; }
.cm-counter.is-near { color: rgb(var(--warn, var(--bad))); }
.cm-md-hint { flex: 1 1 12rem; font-size: .78rem; font-weight: 600; color: rgb(var(--mute)); }
.cm-compose-btns { display: inline-flex; gap: .4rem; margin-left: auto; }
.cm-hint { position: absolute; left: .5rem; bottom: 3.2rem; z-index: 5; display: grid; min-width: 10rem; margin: 0; padding: .25rem; list-style: none; border-radius: 12px; border: 1px solid rgb(var(--line)); background: rgb(var(--card, var(--bg))); box-shadow: 0 8px 24px rgb(0 0 0 / .18); }
.cm-hint button { width: 100%; padding: .4rem .6rem; border: 0; border-radius: 8px; background: none; text-align: left; font-weight: 700; cursor: pointer; }
.cm-hint button:hover, .cm-hint button:focus-visible { background: rgb(var(--soft)); }
.nw-cmcount { font-size: .85rem; font-weight: 800; color: rgb(var(--mute)); text-decoration: none; }
.nw-cmcount:hover { color: rgb(var(--link)); }
@media (max-width: 640px) { .cm-replies { margin-left: .5rem; padding-left: .6rem; } }

/* ---------- feed tools, compact list, author box ---------- */
.nw-tools { display: flex; flex-wrap: wrap; align-items: center; gap: .5rem .9rem; margin: .25rem 0 .5rem; }
.nw-tools .seg { max-width: 100%; overflow-x: auto; }
.nw-feed.is-dense .nf-item { padding-block: .5rem; }
.nw-feed.is-dense .nf-text { display: none; }
.nw-feed.is-dense .nf-thumb { width: 3.5rem; min-width: 3.5rem; aspect-ratio: 1; }
.nw-authorbox { display: flex; flex-wrap: wrap; align-items: center; gap: .6rem 1rem; margin-top: 2rem; padding: .85rem 1rem; border-radius: var(--r-lg, 16px); background: rgb(var(--soft)); }
.nw-authorbox-n { flex: 1 1 8rem; font-size: .85rem; font-weight: 700; color: rgb(var(--mute)); }
__COREGSM_EOF__
  mkdir -p "$APP_DIR/core-frontend/src/styles"
  cat > "$APP_DIR/core-frontend/src/styles/news.css" << '__COREGSM_EOF__'
/* public news feed: the latest news large, the rest as a grid of cards with a cover. Colours and shadows only; no transforms. */
.nf { max-width: 52rem; margin: 0 auto; display: grid; gap: 1.5rem; }
.nf-hero { position: relative; overflow: hidden; border-radius: var(--r-xl); background: rgb(var(--card)); border: 1px solid rgb(var(--line)); box-shadow: var(--shadow-2); }
.nf-hero::before { content: ''; position: absolute; inset: 0 0 auto 0; height: 6px; background: var(--nf-accent, rgb(var(--brand))); opacity: .85; z-index: 1; }
.nf-hero-img { height: 15rem; background-size: cover; background-position: center; background-color: rgb(var(--soft)); }
.nf-hero-in { padding: 1.5rem 2rem 1.75rem; display: grid; gap: .85rem; }
.nf-meta { display: flex; flex-wrap: wrap; align-items: center; gap: .35rem .9rem; font-size: .875rem; font-weight: 600; color: rgb(var(--mute)); }
.nf-date { padding: .15rem .7rem; border-radius: var(--r-pill); background: color-mix(in srgb, var(--nf-accent, #5b4fe0) 14%, rgb(var(--card))); color: rgb(var(--ink)); }
.nf-author { display: inline-flex; align-items: center; gap: .4rem; }
.nf-author img, .nf-ava { width: 22px; height: 22px; border-radius: var(--r-pill); object-fit: cover; }
.nf-ava { display: inline-grid; place-items: center; background: rgb(var(--brand)); color: #fff; font-size: .75rem; font-weight: 650; }
.nf-title { margin: 0; font-size: clamp(1.6rem, 4vw, 2.3rem); line-height: 1.12; font-weight: 800; letter-spacing: -.02em; overflow-wrap: anywhere; }
.nf-text { font-size: 1.0625rem; line-height: 1.6; color: rgb(var(--ink)); overflow-wrap: anywhere; }
.nf-text.is-clamped { display: -webkit-box; -webkit-line-clamp: 4; -webkit-box-orient: vertical; overflow: hidden; }
.nf-text.is-clamped-2 { display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; font-size: .96rem; line-height: 1.5; color: rgb(var(--mute)); }
.nf-actions { display: flex; flex-wrap: wrap; gap: .5rem .75rem; align-items: center; margin-top: .25rem; }
.nf-fields { display: grid; gap: .5rem; margin: .9rem 0 0; grid-template-columns: repeat(auto-fit, minmax(11rem, 1fr)); }
.nf-fields > div { padding: .6rem .8rem; border-radius: var(--r-md); background: rgb(var(--soft)); }
.nf-fields dt { font-size: .8125rem; font-weight: 650; color: rgb(var(--mute)); }
.nf-fields dd { margin: .1rem 0 0; font-weight: 600; }
/* section headings: a plain heading, not a shouting label */
.nf-more { margin: .75rem .25rem 0; font-size: 1.125rem; font-weight: 800; letter-spacing: -.01em; color: rgb(var(--ink)); }

/* the rest of the news: cards in a grid, the cover on top, the whole card reacts to the pointer */
.nf-list { display: grid; gap: 1rem; grid-template-columns: repeat(auto-fill, minmax(17rem, 1fr)); }
.nf-item { position: relative; display: grid; grid-template-rows: auto 1fr; overflow: hidden; border-radius: var(--r-lg); background: rgb(var(--card)); border: 1px solid rgb(var(--line)); box-shadow: var(--shadow-1); transition: box-shadow .18s, border-color .18s; }
.nf-item:hover { box-shadow: var(--shadow-3); border-color: rgb(var(--field)); }
.nf-item:focus-within { outline: 2px solid rgb(var(--brand)); outline-offset: 2px; }
.nf-thumb { aspect-ratio: 16 / 9; background-size: cover; background-position: center; background-color: rgb(var(--soft)); }
.nf-item-in { display: grid; gap: .5rem; align-content: start; min-width: 0; padding: 1rem 1.1rem 1.1rem; }
.nf-item-title { margin: 0; font-size: 1.15rem; font-weight: 650; line-height: 1.25; letter-spacing: -.01em; overflow-wrap: anywhere; }
@media (max-width: 560px) {
  .nf-hero-in { padding: 1.25rem 1.1rem 1.4rem; }
  .nf-hero-img { height: 11rem; }
  /* a phone: a compact row again (small picture on the left) instead of tall cards */
  .nf-list { grid-template-columns: minmax(0, 1fr); gap: .75rem; }
  .nf-item { grid-template-rows: none; grid-template-columns: 5.5rem minmax(0, 1fr); gap: .75rem; padding: .65rem; }
  .nf-thumb { aspect-ratio: 1; align-self: start; min-height: 0; border-radius: var(--r-md); }
  .nf-item-in { padding: 0; align-content: center; }
}

/* ---------- the editorial list of the news page: date | rubric, serif headline, teaser | cover ---------- */
.ne-list { max-width: none; margin: 0; display: grid; gap: 0; }
.ne-h { margin: 1.5rem 0 .25rem; font-size: .9375rem; font-weight: 650; letter-spacing: .02em; color: rgb(var(--mute)); }
.ne-h:first-child { margin-top: 0; }
.ne { display: grid; grid-template-columns: 4.25rem minmax(0, 1fr) 11rem; gap: 1.25rem 1.5rem; align-items: center; padding: 1.4rem .25rem; border-top: 1px solid rgb(var(--line)); }
.ne-date { display: grid; justify-items: start; line-height: 1; color: rgb(var(--mute)); }
.ne-date b { font-size: 1.9rem; font-weight: 650; letter-spacing: -.02em; color: rgb(var(--ink)); font-variant-numeric: tabular-nums; }
.ne-date span { margin-top: .2rem; font-size: .9375rem; font-weight: 650; text-transform: lowercase; }
.ne-date small { margin-top: .15rem; font-size: .75rem; font-weight: 600; }
.ne-body { display: grid; gap: .5rem; min-width: 0; }
.ne-title { margin: 0; font-family: 'Literata Variable', Literata, Georgia, 'Times New Roman', serif; font-size: clamp(1.4rem, 2.6vw, 1.9rem); font-weight: 600; line-height: 1.16; letter-spacing: -.01em; overflow-wrap: anywhere; }
.ne-title a { color: inherit; text-decoration: none; }
.ne-title a:hover { text-decoration: underline; text-decoration-thickness: 2px; text-underline-offset: .18em; text-decoration-color: var(--nf-accent, rgb(var(--brand))); }
.ne-text { margin: 0; max-width: 60ch; display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; line-height: 1.55; color: rgb(var(--mute)); }
.ne-foot { display: flex; flex-wrap: wrap; align-items: center; gap: .25rem 1.25rem; }
.ne-cover { position: relative; display: block; aspect-ratio: 16 / 10; border-radius: var(--r-lg); background-size: cover; background-position: center; background-color: rgb(var(--soft)); box-shadow: inset 0 0 0 1px rgb(var(--line)); overflow: hidden; }
.ne:hover .ne-cover { box-shadow: var(--shadow-2), inset 0 0 0 1px rgb(var(--field)); }
.ne:focus-within { outline: 2px solid rgb(var(--brand)); outline-offset: 2px; border-radius: var(--r-md); }
.ne-cover .nw-gen-ico { height: 62%; right: 10%; }
@media (max-width: 760px) {
  .ne { grid-template-columns: minmax(0, 1fr) 6.5rem; gap: .75rem 1rem; padding: 1.1rem 0; }
  .ne-date { grid-column: 1 / -1; grid-row: 1; display: flex; align-items: baseline; gap: .4rem; }
  .ne-date b { font-size: 1rem; } .ne-date small { display: none; }
  .ne-body { grid-column: 1; grid-row: 2; } .ne-cover { grid-column: 2; grid-row: 2; align-self: start; }
  .ne-text { -webkit-line-clamp: 2; }
}

.ne-more { display: flex; justify-content: center; padding: 1.25rem 0 .5rem; }

/* ---------- the news as a small article: a banner with the headline on it, the whole text below ---------- */
.ne-list { gap: 1.1rem; }
.ne-list .nw-group { display: grid; grid-template-columns: minmax(0, 1fr); gap: 1.1rem; }
.nb { overflow: hidden; border-radius: var(--r-xl); background: rgb(var(--card)); border: 1px solid rgb(var(--line)); box-shadow: var(--shadow-2); }
.nb-banner { position: relative; display: flex; align-items: flex-end; min-height: 9.5rem; padding: 1.25rem 1.5rem; color: #fff; text-decoration: none; background-size: cover; background-position: center; background-color: rgb(var(--soft)); isolation: isolate; }
.nb-banner:not(.nw-gen)::before { content: ''; position: absolute; inset: 0; z-index: -1; background: linear-gradient(180deg, rgb(8 10 20 / .15), rgb(8 10 20 / .78)); }
.nb-banner.nw-gen .nw-gen-ico { height: 70%; right: 6%; }
.nb-banner-in { position: relative; z-index: 2; display: grid; grid-template-columns: minmax(0, 1fr); gap: .5rem; max-width: 46rem; min-width: 0; }
.nb-chips { display: flex; flex-wrap: wrap; align-items: center; gap: .4rem .5rem; }
.nb-date { padding: .2rem .65rem; border-radius: var(--r-pill); background: rgb(0 0 0 / .45); font-size: .8125rem; font-weight: 650; }
.nb-title { margin: 0; font-size: clamp(1.45rem, 3vw, 2rem); font-weight: 800; line-height: 1.12; letter-spacing: -.015em; overflow-wrap: anywhere; text-shadow: 0 2px 18px rgb(0 0 0 / .35); }
.nb-banner:hover .nb-title { text-decoration: underline; text-decoration-thickness: 2px; text-underline-offset: .18em; }
.nb-body { display: grid; gap: .9rem; padding: 1.15rem 1.5rem 1.3rem; }
.nb-text { display: -webkit-box; -webkit-line-clamp: 9; -webkit-box-orient: vertical; overflow: hidden; font-size: 1.0625rem; line-height: 1.6; overflow-wrap: anywhere; }
.nb-text .nw-prose { max-width: none; }
.nb-foot { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: .35rem 1rem; }
.nb:focus-within { outline: 2px solid rgb(var(--brand)); outline-offset: 2px; }
@media (max-width: 560px) { .nb-banner { min-height: 8rem; padding: 1rem 1.1rem; } .nb-body { padding: 1rem 1.1rem 1.15rem; } .nb-text { font-size: 1rem; } }

/* feed cards: pinned ring, long-text fade, tools */
.nb.is-pinned { box-shadow: 0 0 0 1.5px color-mix(in srgb, rgb(var(--brand)) 55%, transparent), var(--shadow-2); }
.nb-text { position: relative; }
.nb-text.is-long::after { content: ''; position: absolute; inset: auto 0 0 0; height: 2.6em; pointer-events: none; background: linear-gradient(to bottom, transparent, rgb(var(--card))); }
.nb-text .nw-prose > p:first-child { font-size: 1.06em; line-height: 1.55; }
.nb-tools { display: inline-flex; align-items: center; gap: 6px; margin-left: auto; }
.nb-tool { display: inline-grid; place-items: center; width: 30px; height: 30px; border-radius: 8px; color: var(--muted, #6b7280); background: transparent; border: 0; cursor: pointer; }
.nb-tool:hover { background: color-mix(in srgb, currentColor 12%, transparent); color: inherit; }
.nw-read { font-size: var(--fs-xs); opacity: .7; white-space: nowrap; }
.nw-code { position: relative; }
.nw-code-copy { position: absolute; top: 8px; right: 8px; font-size: var(--fs-2xs); padding: 2px 8px; border-radius: 6px; border: 1px solid currentColor; background: transparent; opacity: 0; cursor: pointer; }
.nw-code:hover .nw-code-copy, .nw-code-copy:focus-visible { opacity: .75; }
@media (hover: none) { .nw-code-copy { opacity: .6; } }
@media (max-width: 560px) {
  /* the page has a 12px gutter on a phone: the card reaches the screen edges exactly, not 4px past them */
  .nb { border-radius: 0; margin-inline: -12px; }
  .nb-banner, .nb-body { padding-inline: 16px; }
  .nb-read { display: none; }
}

/* ---------- calmer feed: a smaller headline, one banner height, the whole card is a link, one row of rubrics + a small menu ---------- */
.nb { position: relative; transition: box-shadow .15s ease, border-color .15s ease; }
.nb:hover { border-color: rgb(var(--brand) / .4); box-shadow: var(--shadow-3, var(--shadow-2)); }
.nb-stretch { position: absolute; inset: 0; z-index: 1; border-radius: inherit; }
.nb-banner { height: 11rem; min-height: 0; overflow: hidden; }
.nb-title { font-size: clamp(1.5rem, 2.4vw, 1.75rem); line-height: 1.15; display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }
.nb-banner:hover .nb-title { text-decoration: none; }
.nb:hover .nb-title { text-decoration: underline; text-decoration-thickness: 2px; text-underline-offset: .18em; }
.nb-text { pointer-events: none; }
.nb-text a, .nb-text button, .nb-text summary, .nb-text input, .nb-text [role='button'] { position: relative; z-index: 2; pointer-events: auto; }
.nb-foot a, .nb-foot button { position: relative; z-index: 2; }
.nb-foot { pointer-events: none; }
.nb-foot a, .nb-foot button { pointer-events: auto; }
.nb:focus-within { outline: 2px solid rgb(var(--brand)); outline-offset: 2px; }
@media (max-width: 560px) { .nb-banner { height: 10rem; min-height: 0; } .nb-title { font-size: 1.5rem; } }

.nw-bar { display: flex; align-items: center; gap: .5rem; min-width: 0; }
.nw-bar .nw-rubrics { flex: 1 1 auto; min-width: 0; }
.nw-menu-btn { flex: none; display: inline-flex; align-items: center; gap: .45rem; min-height: 44px; padding: 0 .9rem; border-radius: var(--r-pill); border: 1px solid rgb(var(--line)); background: rgb(var(--card)); color: rgb(var(--ink)); font-size: var(--fs-sm); font-weight: 650; cursor: pointer; }
.nw-menu-btn:hover { background: rgb(var(--soft)); }
.nw-menu-h { margin: 6px 12px 2px; font-size: var(--fs-xs); font-weight: 700; letter-spacing: .04em; text-transform: uppercase; color: rgb(var(--mute)); }
.nw-menu-h:not(:first-child) { margin-top: 10px; }

/* the news card in a narrow place («What's new» of the servers page): the same banner, a little smaller, no bleeding to the screen edges */
.nb.nb-compact { margin-inline: 0; border-radius: var(--r-lg); box-shadow: none; }
.nb.nb-compact .nb-banner { min-height: 7.5rem; padding: .9rem 1rem; }
.nb.nb-compact .nb-title { font-size: 1.1rem; line-height: 1.2; }
.nb.nb-compact .nb-body { padding: .8rem 1rem 1rem; gap: .6rem; }
.nb.nb-compact .nb-text { font-size: .9375rem; line-height: 1.5; -webkit-line-clamp: 4; }
