.kit-grid { display: grid; gap: 1rem; grid-template-columns: repeat(auto-fill, minmax(min(100%, 15rem), 1fr)); }
.kit-swatch { height: 3rem; border-radius: var(--r-md); border: 1px solid var(--tile-border); }
