// ---------- sign-in / first-run: glow, floating pictograms, one centred card ----------
const FLOATERS: { icon: string; x: string; y: string; s: string; r: string; d: string }[] = [
  { icon: 'cube', x: '6%', y: '12%', s: '54px', r: '-12deg', d: '19s' },
